--[[
	Cherry UI 1.1.0 — single-file bundle.

	Generated by tools/bundle.py from src/. Do not edit by hand;
	change the modular sources and rebuild.

	Load it from a LocalScript or a Roblox Lua executor:

		local CherryUI = loadstring(game:HttpGet("<raw url>/dist/CherryUI.lua"))()
		local window = CherryUI:CreateWindow({ Title = "Cherry" })

	The chunk returns the library table (and sets `getgenv().CherryUI`
	when the environment provides `getgenv`).
]]

local __modules = {}
local __cache = {}

local function __require(name)
	local cached = __cache[name]
	if cached ~= nil then
		return cached
	end

	local factory = __modules[name]
	if not factory then
		error("[CherryUI] missing module: " .. tostring(name))
	end

	local value = factory()
	__cache[name] = value
	return value
end

__modules["Components/Button"] = function()
	--[[
		Components/Button.lua
		Primary / Secondary / Danger action button.

		Primary buttons use the theme's Primary -> Accent gradient, Secondary is a
		surface button with an outline, Danger uses the danger color. Clicking
		animates a small press and invokes `config.Callback`.
	]]

	local Base = __require("Utils/Base")
	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")

	local Button = setmetatable({}, { __index = Base })
	Button.__index = Button

	function Button.new(library, section, config)
		config = config or {}
		config.Height = config.Height or 36

		local self = Base.new(library, section, "Button", config)
		setmetatable(self, Button)

		self.Variant = config.Variant or "Primary"
		self.Value = nil

		self.Button = Create.textButton({
			Name = "Button",
			Size = UDim2.fromScale(1, 1),
			ZIndex = 2,
			Parent = self.Holder,
		})
		Create.corner(self.Button, 8)

		self.Label = Create.label({
			Name = "Label",
			Size = UDim2.fromScale(1, 1),
			Text = config.Text or self.Name,
			TextSize = 12,
			Font = Enum.Font.GothamBold,
			TextXAlignment = Enum.TextXAlignment.Center,
			ZIndex = 3,
			Parent = self.Button,
		})

		self.Overlay = Create.new("Frame", {
			Name = "Overlay",
			Size = UDim2.fromScale(1, 1),
			BackgroundColor3 = Color3.new(1, 1, 1),
			BackgroundTransparency = 1,
			ZIndex = 4,
			Parent = self.Button,
		})
		Create.corner(self.Overlay, 8)

		self.Scale = Create.new("UIScale", { Scale = 1, Parent = self.Button })

		self:_applyVariant()
		self:_wireEvents()

		return self
	end

	function Button:_applyVariant()
		local palette = self.Library.Palette
		local variant = self.Variant
		local background, textColor, strokeColor, strokeTransparency

		if variant == "Danger" then
			background = palette.Danger
			textColor = Color3.new(1, 1, 1)
			strokeColor = palette.Danger
			strokeTransparency = 0.45
		elseif variant == "Secondary" then
			background = palette.SurfaceHigh
			textColor = palette.Text
			strokeColor = palette.Outline
			strokeTransparency = 0.2
		else
			background = palette.Primary
			textColor = Color3.new(1, 1, 1)
			strokeColor = palette.Accent
			strokeTransparency = 0.55
		end

		self.Button.BackgroundColor3 = background
		self.Label.TextColor3 = textColor

		if self.Stroke then
			self.Stroke.Color = strokeColor
			self.Stroke.Transparency = strokeTransparency
		else
			self.Stroke = Create.stroke(self.Button, strokeColor, 1, strokeTransparency)
		end

		if variant == "Primary" then
			if not self.Gradient then
				self.Gradient = Create.new("UIGradient", { Rotation = 25, Parent = self.Button })
				self.Library.ThemeManager:BindGradient(self.Gradient, { "Primary", "Accent" })
			end
		elseif self.Gradient then
			self.Gradient:Destroy()
			self.Gradient = nil
		end
	end

	function Button:_wireEvents()
		self:_track(self.Button.MouseEnter:Connect(function()
			Tween.play(self.Overlay, {
				BackgroundTransparency = self.Variant == "Secondary" and 0.94 or 0.86,
			}, Tween.Info.Fast)
		end))

		self:_track(self.Button.MouseLeave:Connect(function()
			Tween.play(self.Overlay, { BackgroundTransparency = 1 }, Tween.Info.Fast)
			Tween.play(self.Scale, { Scale = 1 }, Tween.Info.Fast)
		end))

		self:_track(self.Button.MouseButton1Down:Connect(function()
			if self.Disabled then
				return
			end
			Tween.play(self.Scale, { Scale = 0.97 }, Tween.Info.Snap)
		end))

		self:_track(self.Button.MouseButton1Up:Connect(function()
			Tween.play(self.Scale, { Scale = 1 }, Tween.Info.Fast)
		end))

		self:_track(self.Button.Activated:Connect(function()
			if self.Destroyed or self.Disabled then
				return
			end

			local callback = self.Config.Callback or self.Config.OnClick
			if type(callback) == "function" then
				local ok, err = pcall(callback)
				if not ok then
					warn("[CherryUI] Button callback error: " .. tostring(err))
				end
			end
		end))

		self:OnThemeChanged(function()
			self:_applyVariant()
		end)
	end

	function Button:SetText(text)
		self.Label.Text = tostring(text)
	end

	function Button:SetEnabled(enabled)
		self.Disabled = not enabled
		self.Button.Active = self.Disabled ~= true
		self.Label.TextTransparency = self.Disabled and 0.5 or 0
		self.Button.BackgroundTransparency = self.Disabled and 0.35 or 0
		return self
	end

	function Button:Destroy()
		Base.Destroy(self)
	end

	return Button
end

__modules["Components/ColorPicker"] = function()
	--[[
		Components/ColorPicker.lua
		Compact HSV color picker for ESP/aimbot colors.

		The field shows a live swatch and hex code; the popup (built lazily) has a
		saturation/value square, a hue strip and a hex input. Dragging updates the
		value continuously so a connected ESP can preview the change instantly.
	]]

	local UserInputService = game:GetService("UserInputService")

	local Base = __require("Utils/Base")
	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")
	local Util = __require("Utils/Util")
	local Popup = __require("Utils/Popup")

	local ColorPicker = setmetatable({}, { __index = Base })
	ColorPicker.__index = ColorPicker

	local POPUP_WIDTH = 216
	local POPUP_HEIGHT = 186

	function ColorPicker.new(library, section, config)
		config = config or {}
		config.Height = config.Height or 34

		local default = config.Default
		if typeof(default) ~= "Color3" then
			default = library.Palette.Primary
		end
		config.Default = default

		local self = Base.new(library, section, "ColorPicker", config)
		setmetatable(self, ColorPicker)

		self.Value = default
		self.DragMode = nil

		local hue, saturation, brightness = default:ToHSV()
		self.HueValue = hue
		self.Saturation = saturation
		self.Brightness = brightness

		self.Hit = Create.textButton({
			Name = "Hit",
			Size = UDim2.fromScale(1, 1),
			ZIndex = 2,
			Parent = self.Holder,
		})
		self:AddHover(self.Hit)

		self.Label = Create.label({
			Name = "Label",
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -150, 1, 0),
			Text = self.Name,
			TextSize = 13,
			ZIndex = 3,
			Parent = self.Hit,
		})
		library:Styled(self.Label, "Text", "TextColor3")

		self.Field = Create.textButton({
			Name = "ColorField",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -10, 0.5, 0),
			Size = UDim2.fromOffset(112, 24),
			BackgroundTransparency = 0.15,
			ZIndex = 3,
			Parent = self.Hit,
		})
		Create.corner(self.Field, 6)
		library:Styled(self.Field, "SurfaceHigh", "BackgroundColor3")
		library:Styled(Create.stroke(self.Field, library.Palette.Outline, 1, 0.4), "Outline", "Color")

		self.Swatch = Create.new("Frame", {
			Name = "Swatch",
			Position = UDim2.fromOffset(5, 4),
			Size = UDim2.fromOffset(16, 16),
			BackgroundColor3 = self.Value,
			ZIndex = 4,
			Parent = self.Field,
		})
		Create.corner(self.Swatch, UDim.new(1, 0))
		Create.stroke(self.Swatch, Color3.new(0, 0, 0), 1, 0.75)

		self.ValueLabel = Create.label({
			Name = "Hex",
			Position = UDim2.fromOffset(27, 0),
			Size = UDim2.new(1, -32, 1, 0),
			Text = Util.hex(self.Value),
			TextSize = 11,
			Font = Enum.Font.Code,
			ZIndex = 4,
			Parent = self.Field,
		})
		library:Styled(self.ValueLabel, "SubText", "TextColor3")

		self:_track(self.Field.Activated:Connect(function()
			if self.Destroyed then
				return
			end
			self:Open()
		end))

		self:OnThemeChanged(function()
			self:_render()
		end)

		self:_render()

		return self
	end

	-- Drag listeners are created on mouse-down and removed on release.
	function ColorPicker:_beginDrag()
		if self._dragConnection then
			return
		end

		self._dragConnection = UserInputService.InputChanged:Connect(function(input)
			if not self.DragMode then
				return
			end
			if input.UserInputType ~= Enum.UserInputType.MouseMovement
				and input.UserInputType ~= Enum.UserInputType.Touch
			then
				return
			end

			if self.DragMode == "sv" then
				self:_updateSV(input.Position)
			elseif self.DragMode == "hue" then
				self:_updateHue(input.Position)
			end
		end)

		self._endConnection = UserInputService.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch
				then
				self:_endDrag()
			end
		end)
	end

	function ColorPicker:_endDrag()
		self.DragMode = nil

		if self._dragConnection then
			self._dragConnection:Disconnect()
			self._dragConnection = nil
		end

		if self._endConnection then
			self._endConnection:Disconnect()
			self._endConnection = nil
		end
	end

	function ColorPicker:_ensurePopup()
		if self.Popup then
			return
		end

		self.Popup = Popup.new(self.Library, {
			Name = "ColorPickerPopup",
			Width = POPUP_WIDTH,
			Height = POPUP_HEIGHT,
			OnClose = function()
				self:_endDrag()
				if self.HexBox and self.HexBox:IsFocused() then
					self.HexBox:ReleaseFocus()
				end
			end,
		})

		local frame = self.Popup.Frame

		-- Saturation / value square.
		self.SV = Create.new("Frame", {
			Name = "SaturationValue",
			Position = UDim2.fromOffset(10, 10),
			Size = UDim2.fromOffset(POPUP_WIDTH - 20, 104),
			BackgroundColor3 = Color3.new(1, 1, 1),
			Active = true,
			Parent = frame,
		})
		Create.corner(self.SV, 6)

		self.SVGradient = Create.new("UIGradient", {
			Rotation = 0,
			Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromHSV(self.HueValue, 1, 1)),
			Parent = self.SV,
		})

		local shade = Create.new("Frame", {
			Name = "Shade",
			Size = UDim2.fromScale(1, 1),
			BackgroundColor3 = Color3.new(0, 0, 0),
			Parent = self.SV,
		})
		Create.corner(shade, 6)
		Create.new("UIGradient", {
			Rotation = 90,
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Parent = shade,
		})

		self.SVPicker = Create.new("Frame", {
			Name = "SVPicker",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Size = UDim2.fromOffset(12, 12),
			BackgroundTransparency = 1,
			Parent = self.SV,
		})
		Create.corner(self.SVPicker, UDim.new(1, 0))
		Create.stroke(self.SVPicker, Color3.new(1, 1, 1), 2, 0.1)

		-- Hue strip.
		self.HueStrip = Create.new("Frame", {
			Name = "Hue",
			Position = UDim2.fromOffset(10, 122),
			Size = UDim2.fromOffset(POPUP_WIDTH - 20, 12),
			Active = true,
			Parent = frame,
		})
		Create.corner(self.HueStrip, 6)

		local hueKeypoints = {}
		for index = 0, 6 do
			table.insert(
				hueKeypoints,
				ColorSequenceKeypoint.new(index / 6, Color3.fromHSV(index / 6, 1, 1))
			)
		end
		Create.new("UIGradient", {
			Color = ColorSequence.new(hueKeypoints),
			Parent = self.HueStrip,
		})

		self.HuePicker = Create.new("Frame", {
			Name = "HuePicker",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0, 0.5),
			Size = UDim2.fromOffset(6, 18),
			BackgroundColor3 = Color3.new(1, 1, 1),
			ZIndex = 2,
			Parent = self.HueStrip,
		})
		Create.corner(self.HuePicker, 3)
		Create.stroke(self.HuePicker, Color3.new(0, 0, 0), 1, 0.5)

		-- Hex input + preview.
		self.HexBox = Create.new("TextBox", {
			Name = "HexInput",
			Position = UDim2.fromOffset(10, 146),
			Size = UDim2.fromOffset(120, 28),
			Text = Util.hex(self.Value),
			Font = Enum.Font.Code,
			TextSize = 12,
			TextXAlignment = Enum.TextXAlignment.Left,
			ClearTextOnFocus = false,
			ZIndex = 2,
			Parent = frame,
		})
		Create.corner(self.HexBox, 6)
		self.Library:Styled(self.HexBox, "SurfaceHigh", "BackgroundColor3")
		self.Library:Styled(self.HexBox, "Text", "TextColor3")
		Create.padding(self.HexBox, 8, 6, 8, 6)
		self.Library:Styled(
			Create.stroke(self.HexBox, self.Library.Palette.Outline, 1, 0.4),
			"Outline",
			"Color"
		)

		self.Preview = Create.new("Frame", {
			Name = "Preview",
			Position = UDim2.fromOffset(POPUP_WIDTH - 48, 146),
			Size = UDim2.fromOffset(28, 28),
			BackgroundColor3 = self.Value,
			ZIndex = 2,
			Parent = frame,
		})
		Create.corner(self.Preview, 6)
		Create.stroke(self.Preview, Color3.new(0, 0, 0), 1, 0.75)

		self.SV.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch
			then
				self.DragMode = "sv"
				self:_beginDrag()
				self:_updateSV(input.Position)
			end
		end)

		self.HueStrip.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch
			then
				self.DragMode = "hue"
				self:_beginDrag()
				self:_updateHue(input.Position)
			end
		end)

		self.HexBox.FocusLost:Connect(function()
			local color = Util.fromHex(self.HexBox.Text)
			if color then
				self:SetValue(color)
			else
				self.HexBox.Text = Util.hex(self.Value)
			end
		end)

		self:_render()
	end

	function ColorPicker:_updateSV(position)
		local size = self.SV.AbsoluteSize
		if size.X <= 0 or size.Y <= 0 then
			return
		end

		local relativeX = Util.clamp((position.X - self.SV.AbsolutePosition.X) / size.X, 0, 1)
		local relativeY = Util.clamp((position.Y - self.SV.AbsolutePosition.Y) / size.Y, 0, 1)

		self.Saturation = relativeX
		self.Brightness = 1 - relativeY

		self:_commitColor()
	end

	function ColorPicker:_updateHue(position)
		local size = self.HueStrip.AbsoluteSize
		if size.X <= 0 then
			return
		end

		self.HueValue = Util.clamp((position.X - self.HueStrip.AbsolutePosition.X) / size.X, 0, 0.999)

		self:_commitColor()
	end

	function ColorPicker:_commitColor()
		local color = Color3.fromHSV(self.HueValue, self.Saturation, self.Brightness)
		local changed = self.Value ~= color

		self.Value = color
		self:_render()

		if changed then
			self:_commit(color, false)
		end
	end

	function ColorPicker:_render()
		local palette = self.Library.Palette
		local color = self.Value or palette.Primary

		self.Swatch.BackgroundColor3 = color
		self.ValueLabel.Text = Util.hex(color)

		if self.SV then
			self.SVGradient.Color = ColorSequence.new(
				Color3.new(1, 1, 1),
				Color3.fromHSV(self.HueValue, 1, 1)
			)
			self.SVPicker.Position = UDim2.fromScale(self.Saturation, 1 - self.Brightness)
			self.HuePicker.Position = UDim2.fromScale(self.HueValue, 0.5)
			self.Preview.BackgroundColor3 = color

			if not self.HexBox:IsFocused() then
				self.HexBox.Text = Util.hex(color)
			end
		end
	end

	function ColorPicker:Open()
		if self.Destroyed then
			return
		end

		self:_ensurePopup()
		self.Popup:Open(self.Field)
	end

	function ColorPicker:Close()
		if self.Popup then
			self.Popup:Close()
		end
	end

	function ColorPicker:SetValue(value, silent)
		if self.Destroyed or typeof(value) ~= "Color3" then
			return
		end

		local changed = self.Value ~= value
		self.Value = value

		local hue, saturation, brightness = value:ToHSV()
		self.HueValue = hue
		self.Saturation = saturation
		self.Brightness = brightness

		self:_render()

		if changed then
			self:_commit(value, silent)
		end
	end

	function ColorPicker:GetValue()
		return self.Value
	end

	function ColorPicker:Destroy()
		if self.Destroyed then
			return
		end

		self:_endDrag()

		if self.Popup then
			self.Popup:Destroy()
			self.Popup = nil
		end

		Base.Destroy(self)
	end

	return ColorPicker
end

__modules["Components/Dropdown"] = function()
	--[[
		Components/Dropdown.lua
		Single- and multi-select dropdown with a scrollable, pooled option list.

		The menu is created lazily the first time it is opened and lives in the
		library overlay so it is never clipped by the tab's scrolling frame. Option
		rows come from an instance pool, so opening a dropdown repeatedly does not
		create garbage.
	]]

	local Base = __require("Utils/Base")
	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")
	local Icons = __require("Utils/Icons")
	local Pool = __require("Utils/Pool")
	local Popup = __require("Utils/Popup")

	local Dropdown = setmetatable({}, { __index = Base })
	Dropdown.__index = Dropdown

	function Dropdown.new(library, section, config)
		config = config or {}
		config.Height = config.Height or 34

		local self = Base.new(library, section, "Dropdown", config)
		setmetatable(self, Dropdown)

		self.Multi = config.Multi == true
		self.Placeholder = config.Placeholder or "Select..."
		self.Options = {}
		self._optionSet = {}
		self._rendered = {}
		self._widgets = {}
		self.IsOpen = false

		for _, option in ipairs(config.Options or {}) do
			local text = tostring(option)
			if text ~= "" and not self._optionSet[text] then
				self._optionSet[text] = true
				table.insert(self.Options, text)
			end
		end

		if self.Multi then
			self.Value = {}
			if type(config.Default) == "table" then
				for _, item in ipairs(config.Default) do
					local text = tostring(item)
					if self._optionSet[text] and not table.find(self.Value, text) then
						table.insert(self.Value, text)
					end
				end
			end
			self.Default = table.clone(self.Value)
		else
			local default = config.Default
			if type(default) ~= "string" or not self._optionSet[default] then
				default = self.Options[1]
			end
			self.Value = default
			self.Default = default
		end

		self.Hit = Create.textButton({
			Name = "Hit",
			Size = UDim2.fromScale(1, 1),
			ZIndex = 2,
			Parent = self.Holder,
		})
		self:AddHover(self.Hit)

		self.Label = Create.label({
			Name = "Label",
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(0.5, -8, 1, 0),
			Text = self.Name,
			TextSize = 13,
			ZIndex = 3,
			Parent = self.Hit,
		})
		library:Styled(self.Label, "Text", "TextColor3")

		self.ValueLabel = Create.label({
			Name = "Value",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -26, 0.5, 0),
			Size = UDim2.new(0.45, 0, 1, 0),
			TextSize = 12,
			TextXAlignment = Enum.TextXAlignment.Right,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = 3,
			Parent = self.Hit,
		})

		self.Chevron = Icons.new("chevron", self.Hit, 12, library.Palette.SubText, 3)
		self.Chevron.AnchorPoint = Vector2.new(1, 0.5)
		self.Chevron.Position = UDim2.new(1, -10, 0.5, 0)
		Icons.bindTheme(self.Chevron, library, "SubText")

		self:_renderField()

		self:_track(self.Hit.Activated:Connect(function()
			if self.Destroyed then
				return
			end
			if self.IsOpen then
				self:Close()
			else
				self:Open()
			end
		end))

		self:OnThemeChanged(function()
			self:_renderField()
		end)

		return self
	end

	function Dropdown:_isSelected(option)
		if self.Multi then
			return table.find(self.Value, option) ~= nil
		end
		return self.Value == option
	end

	function Dropdown:_renderField()
		local palette = self.Library.Palette
		local text
		local empty = false

		if self.Multi then
			local count = #self.Value
			if count == 0 then
				text = self.Placeholder
				empty = true
			elseif count == 1 then
				text = self.Value[1]
			elseif count == 2 then
				text = self.Value[1] .. ", " .. self.Value[2]
			else
				text = self.Value[1] .. " +" .. tostring(count - 1)
			end
		else
			empty = self.Value == nil
			text = self.Value or self.Placeholder
		end

		self.ValueLabel.Text = text
		self.ValueLabel.TextColor3 = empty and palette.Placeholder or palette.Text
	end

	function Dropdown:_setChevron(open)
		Tween.play(self.Chevron, { Rotation = open and 180 or 0 }, Tween.Info.Fast)
	end

	function Dropdown:_ensureMenu()
		if self.Popup then
			return
		end

		self.Popup = Popup.new(self.Library, {
			Name = "DropdownMenu",
			Width = 180,
			Height = 120,
			OnClose = function()
				self.IsOpen = false
				self:_setChevron(false)
			end,
		})

		self.List = Create.new("ScrollingFrame", {
			Name = "Options",
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ScrollBarThickness = 3,
			ScrollBarImageColor3 = self.Library.Palette.Outline,
			ScrollingDirection = Enum.ScrollingDirection.Y,
			CanvasSize = UDim2.new(0, 0, 0, 0),
			Parent = self.Popup.Frame,
		})
		Create.padding(self.List, 4)
		Create.list(self.List, 2)

		self.Pool = Pool.new(function()
			local option = Create.textButton({
				Name = "Option",
				Size = UDim2.new(1, 0, 0, 28),
				TextSize = 12,
				Font = Enum.Font.Gotham,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Parent = nil,
			})
			Create.corner(option, 6)
			Create.padding(option, 0, 8, 0, 10)

			local check = Icons.new("check", option, 13, self.Library.Palette.Primary, 4)
			check.AnchorPoint = Vector2.new(1, 0.5)
			check.Position = UDim2.new(1, -9, 0.5, 0)
			check.Visible = false

			self._widgets[option] = { Check = check }

			option.Activated:Connect(function()
				local value = option:GetAttribute("Option")
				if type(value) == "string" and value ~= "" and not self.Destroyed then
					self:_select(value)
				end
			end)

			option.MouseEnter:Connect(function()
				Tween.play(option, { BackgroundTransparency = 0.4 }, Tween.Info.Fast)
			end)

			option.MouseLeave:Connect(function()
				local value = option:GetAttribute("Option")
				local selected = type(value) == "string" and self:_isSelected(value)
				Tween.play(option, { BackgroundTransparency = selected and 0.75 or 1 }, Tween.Info.Fast)
			end)

			return option
		end, function(option)
			option:SetAttribute("Option", nil)
			option.Text = ""
			local widgets = self._widgets[option]
			if widgets then
				widgets.Check.Visible = false
			end
			option.BackgroundTransparency = 1
		end, 4)
	end

	function Dropdown:_renderOptions()
		if not self.Popup then
			return
		end

		for _, item in ipairs(self._rendered) do
			self.Pool:Release(item.Button)
		end
		table.clear(self._rendered)

		local palette = self.Library.Palette

		for index, option in ipairs(self.Options) do
			local button = self.Pool:Get(self.List)
			local widgets = self._widgets[button]
			local selected = self:_isSelected(option)

			button.LayoutOrder = index
			button:SetAttribute("Option", option)
			button.Text = option
			button.TextColor3 = selected and palette.Primary or palette.Text
			button.BackgroundColor3 = palette.SurfaceHigh
			button.BackgroundTransparency = selected and 0.75 or 1

			widgets.Check.Visible = selected
			Icons.setColor(widgets.Check, palette.Primary)

			table.insert(self._rendered, { Button = button })
		end

		self.List.CanvasSize = UDim2.new(0, 0, 0, #self.Options * 30 + 8)
		self.List.ScrollBarImageColor3 = palette.Outline

		local width = math.clamp(self.Holder.AbsoluteSize.X * 0.5, 180, 280)
		local height = math.clamp(#self.Options * 30 + 12, 44, 240)
		self.Popup:SetSize(width, height)
	end

	function Dropdown:Open()
		if self.Destroyed or self.IsOpen or #self.Options == 0 then
			return
		end

		self:_ensureMenu()
		self:_renderOptions()

		self.IsOpen = true
		self.Popup:Open(self.Holder)
		self:_setChevron(true)
	end

	function Dropdown:Close()
		if not self.IsOpen then
			return
		end

		self.IsOpen = false
		self:_setChevron(false)

		if self.Popup then
			self.Popup:Close()
		end
	end

	function Dropdown:_select(option)
		if self.Multi then
			local index = table.find(self.Value, option)
			if index then
				table.remove(self.Value, index)
			else
				table.insert(self.Value, option)
			end

			self:_renderField()
			self:_renderOptions()
			self:_commit(self:GetValue(), false)
		else
			if self.Value ~= option then
				self.Value = option
				self:_renderField()
				self:_renderOptions()
				self:_commit(option, false)
			end
			self:Close()
		end
	end

	function Dropdown:SetValue(value, silent)
		if self.Destroyed then
			return
		end

		if self.Multi then
			local list = {}
			if type(value) == "table" then
				for _, item in ipairs(value) do
					local text = tostring(item)
					if self._optionSet[text] and not table.find(list, text) then
						table.insert(list, text)
					end
				end
			end
			self.Value = list
		else
			local text = type(value) == "string" and value or nil
			if text == nil or not self._optionSet[text] then
				text = self.Options[1]
			end
			self.Value = text
		end

		self:_renderField()
		if self.Popup then
			self:_renderOptions()
		end
		self:_commit(self:GetValue(), silent)
	end

	function Dropdown:GetValue()
		if self.Multi then
			return table.clone(self.Value)
		end
		return self.Value
	end

	function Dropdown:Destroy()
		if self.Destroyed then
			return
		end

		if self.Popup then
			self.Popup:Destroy()
			self.Popup = nil
		end

		if self.Pool then
			self.Pool:Destroy()
			self.Pool = nil
		end

		table.clear(self._rendered)
		table.clear(self._widgets)

		Base.Destroy(self)
	end

	return Dropdown
end

__modules["Components/ESPPreview"] = function()
	--[[
		Components/ESPPreview.lua
		A live, interactive ESP preview.

		A styled 2D avatar sits in a dark stage with a highlight, box + corner
		brackets, a tracer and a name tag with a health bar. The chips above the
		stage toggle each visual, and the whole scene is animated at a capped 30 Hz
		through the library scheduler (never per-frame).

			preview:SetTarget({ Name = "Player", Health = 72, Distance = 60 })
			preview:OnChanged(function(settings) ... end)
	]]

	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")
	local Signal = __require("Utils/Signal")
	local Util = __require("Utils/Util")

	local ESPPreview = {}
	ESPPreview.__index = ESPPreview

	local CHIP_DEFS = {
		{ Key = "Highlight", Label = "Glow" },
		{ Key = "Box", Label = "Box" },
		{ Key = "Tracer", Label = "Tracer" },
		{ Key = "Name", Label = "Name" },
	}

	function ESPPreview.new(library, parent, config)
		config = config or {}

		local self = setmetatable({}, ESPPreview)

		self.Library = library
		self.Name = tostring(config.Name or "ESP Preview")
		self.Height = config.Height or 320
		self.Color = typeof(config.Color) == "Color3" and config.Color or library.Palette.Primary
		self.Enabled = { Highlight = true, Box = true, Tracer = true, Name = true }
		self.Target = {
			Name = tostring(config.TargetName or "Cherry"),
			Health = 100,
			MaxHealth = 100,
			Distance = 42,
		}
		self.Changed = Signal.new()
		self.Destroyed = false

		self._connections = {}
		self._partStrokes = {}
		self._brackets = {}
		self._sway = 0
		self._bob = 0
		self._lean = 0

		local palette = library.Palette

		self.Frame = Create.new("Frame", {
			Name = "ESPPreview",
			Size = UDim2.new(1, 0, 0, self.Height),
			BackgroundTransparency = 0.08,
			Parent = parent,
		})
		library:Styled(self.Frame, "Surface", "BackgroundColor3")
		Create.corner(self.Frame, 10)
		library:Styled(Create.stroke(self.Frame, palette.Outline, 1, 0.4), "Outline", "Color")

		-- Header.
		self.LivePill = Create.new("Frame", {
			Name = "Live",
			Position = UDim2.fromOffset(10, 10),
			Size = UDim2.fromOffset(40, 18),
			BackgroundColor3 = self.Color,
			BackgroundTransparency = 0.85,
			Parent = self.Frame,
		})
		Create.corner(self.LivePill, 9)

		self.LiveDot = Create.new("Frame", {
			Name = "Dot",
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.fromOffset(7, 9),
			Size = UDim2.fromOffset(4, 4),
			BackgroundColor3 = self.Color,
			Parent = self.LivePill,
		})
		Create.corner(self.LiveDot, UDim.new(1, 0))

		self.LiveLabel = Create.label({
			Name = "LiveLabel",
			Text = "LIVE",
			Font = Enum.Font.GothamBold,
			TextSize = 9,
			TextColor3 = self.Color,
			TextXAlignment = Enum.TextXAlignment.Center,
			Position = UDim2.fromOffset(13, 0),
			Size = UDim2.new(1, -13, 1, 0),
			Parent = self.LivePill,
		})

		self.Title = Create.label({
			Name = "Title",
			Text = self.Name,
			Font = Enum.Font.GothamBold,
			TextSize = 12,
			TextColor3 = palette.Text,
			Position = UDim2.fromOffset(58, 10),
			Size = UDim2.new(1, -140, 0, 18),
			Parent = self.Frame,
		})
		library:Styled(self.Title, "Text", "TextColor3")

		self.DistanceLabel = Create.label({
			Name = "Distance",
			Text = "42 m",
			TextSize = 11,
			TextXAlignment = Enum.TextXAlignment.Right,
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -10, 0, 10),
			Size = UDim2.fromOffset(70, 18),
			Parent = self.Frame,
		})
		library:Styled(self.DistanceLabel, "SubText", "TextColor3")

		-- Toggle chips.
		local chipRow = Create.new("Frame", {
			Name = "Chips",
			Position = UDim2.fromOffset(10, 38),
			Size = UDim2.new(1, -20, 0, 20),
			BackgroundTransparency = 1,
			Parent = self.Frame,
		})
		Create.new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 6),
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Parent = chipRow,
		})

		self.Chips = {}

		for index, definition in ipairs(CHIP_DEFS) do
			local chip = Create.textButton({
				Name = definition.Key,
				Size = UDim2.fromOffset(68, 20),
				Parent = chipRow,
			})
			chip.LayoutOrder = index
			Create.corner(chip, 5)

			local dot = Create.new("Frame", {
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.fromOffset(8, 10),
				Size = UDim2.fromOffset(4, 4),
				BackgroundColor3 = self.Color,
				Parent = chip,
			})
			Create.corner(dot, UDim.new(1, 0))

			local label = Create.label({
				Text = definition.Label,
				TextSize = 10,
				Position = UDim2.fromOffset(17, 0),
				Size = UDim2.new(1, -19, 1, 0),
				Parent = chip,
			})

			chip.Activated:Connect(function()
				self:Toggle(definition.Key)
			end)

			self.Chips[definition.Key] = { Button = chip, Dot = dot, Label = label }
		end

		-- Stage.
		self.Stage = Create.new("Frame", {
			Name = "Stage",
			Position = UDim2.fromOffset(10, 68),
			Size = UDim2.new(1, -20, 1, -78),
			BackgroundColor3 = palette.Background,
			BackgroundTransparency = 0.3,
			ClipsDescendants = true,
			Parent = self.Frame,
		})
		library:Styled(self.Stage, "Background", "BackgroundColor3")
		Create.corner(self.Stage, 8)
		library:Styled(Create.stroke(self.Stage, palette.Outline, 1, 0.5), "Outline", "Color")

		for index = 1, 3 do
			local offset = index * 0.25
			local vertical = Create.new("Frame", {
				Name = "GridV",
				Position = UDim2.fromScale(offset, 0),
				Size = UDim2.new(0, 1, 1, 0),
				BackgroundTransparency = 0.65,
				ZIndex = 1,
				Parent = self.Stage,
			})
			library:Styled(vertical, "Outline", "BackgroundColor3")

			local horizontal = Create.new("Frame", {
				Name = "GridH",
				Position = UDim2.fromScale(0, offset),
				Size = UDim2.new(1, 0, 0, 1),
				BackgroundTransparency = 0.65,
				ZIndex = 1,
				Parent = self.Stage,
			})
			library:Styled(horizontal, "Outline", "BackgroundColor3")
		end

		-- Tracer.
		self.Tracer = Create.new("Frame", {
			Name = "Tracer",
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.fromScale(0.5, 1),
			Size = UDim2.fromOffset(100, 1.5),
			BackgroundColor3 = self.Color,
			BackgroundTransparency = 0.25,
			ZIndex = 2,
			Parent = self.Stage,
		})
		Create.new("UIGradient", {
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.15),
				NumberSequenceKeypoint.new(1, 0.9),
			}),
			Parent = self.Tracer,
		})

		-- Avatar.
		self.Character = Create.new("Frame", {
			Name = "Character",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(64, 140),
			BackgroundTransparency = 1,
			ZIndex = 4,
			Parent = self.Stage,
		})
		self.CharacterScale = Create.new("UIScale", { Scale = 1, Parent = self.Character })

		self.HighlightGlow = Create.new("Frame", {
			Name = "HighlightGlow",
			AnchorPoint = Vector2.new(0.5, 0),
			Position = UDim2.new(0.5, 0, 0, -6),
			Size = UDim2.fromOffset(76, 138),
			BackgroundColor3 = self.Color,
			BackgroundTransparency = 0.9,
			ZIndex = 1,
			Parent = self.Character,
		})
		Create.corner(self.HighlightGlow, 18)

		self.Highlight = Create.new("Frame", {
			Name = "Highlight",
			AnchorPoint = Vector2.new(0.5, 0),
			Position = UDim2.new(0.5, 0, 0, 0),
			Size = UDim2.fromOffset(52, 128),
			BackgroundColor3 = self.Color,
			BackgroundTransparency = 0.55,
			ZIndex = 2,
			Parent = self.Character,
		})
		Create.corner(self.Highlight, 14)

		local function makePart(name, position, size, corner, rotation)
			local part = Create.new("Frame", {
				Name = name,
				AnchorPoint = Vector2.new(0.5, 0),
				Position = position,
				Size = size,
				Rotation = rotation or 0,
				BackgroundTransparency = 0.05,
				ZIndex = 3,
				Parent = self.Character,
			})
			library:Styled(part, "SurfaceHigh", "BackgroundColor3")
			Create.corner(part, corner)
			table.insert(self._partStrokes, Create.stroke(part, self.Color, 1, 0.75))
			return part
		end

		makePart("Head", UDim2.new(0.5, 0, 0, 4), UDim2.fromOffset(24, 24), 12)
		makePart("Torso", UDim2.new(0.5, 0, 0, 30), UDim2.fromOffset(32, 50), 7)
		makePart("LeftArm", UDim2.new(0.5, -22, 0, 32), UDim2.fromOffset(10, 44), 5, 5)
		makePart("RightArm", UDim2.new(0.5, 22, 0, 32), UDim2.fromOffset(10, 44), 5, -5)
		makePart("LeftLeg", UDim2.new(0.5, -9, 0, 82), UDim2.fromOffset(12, 46), 6, 2)
		makePart("RightLeg", UDim2.new(0.5, 9, 0, 82), UDim2.fromOffset(12, 46), 6, -2)

		-- Face (kept subtle so the silhouette still reads as a player model).
		local face = Create.new("Frame", {
			Name = "Face",
			Position = UDim2.new(0.5, 0, 0, 12),
			Size = UDim2.fromOffset(16, 10),
			AnchorPoint = Vector2.new(0.5, 0),
			BackgroundTransparency = 1,
			ZIndex = 8,
			Parent = self.Character,
		})
		for _, eyeX in ipairs({ 2, 10 }) do
			local eye = Create.new("Frame", {
				Name = "Eye",
				Position = UDim2.fromOffset(eyeX, 1),
				Size = UDim2.fromOffset(3, 3),
				BackgroundColor3 = Color3.fromRGB(30, 30, 34),
				ZIndex = 8,
				Parent = face,
			})
			Create.corner(eye, UDim.new(1, 0))
		end
		local smile = Create.new("Frame", {
			Name = "Smile",
			Position = UDim2.fromOffset(4, 7),
			Size = UDim2.fromOffset(8, 2),
			BackgroundColor3 = Color3.fromRGB(30, 30, 34),
			ZIndex = 8,
			Parent = face,
		})
		Create.corner(smile, 1)

		-- Bounding box + brackets.
		self.Box = Create.new("Frame", {
			Name = "BoundingBox",
			AnchorPoint = Vector2.new(0.5, 0),
			Position = UDim2.new(0.5, 0, 0, -6),
			Size = UDim2.fromOffset(62, 140),
			BackgroundTransparency = 1,
			ZIndex = 5,
			Parent = self.Character,
		})
		self.BoxStroke = Create.stroke(self.Box, self.Color, 1.5, 0.15)

		local function bracket(anchorPoint, position, width, height)
			local frame = Create.new("Frame", {
				Name = "Bracket",
				AnchorPoint = anchorPoint,
				Position = position,
				Size = UDim2.fromOffset(width, height),
				BackgroundColor3 = self.Color,
				BorderSizePixel = 0,
				ZIndex = 6,
				Parent = self.Box,
			})
			table.insert(self._brackets, frame)
		end

		bracket(Vector2.new(0, 0), UDim2.fromOffset(0, 0), 12, 2)
		bracket(Vector2.new(0, 0), UDim2.fromOffset(0, 0), 2, 12)
		bracket(Vector2.new(1, 0), UDim2.new(1, 0, 0, 0), 12, 2)
		bracket(Vector2.new(1, 0), UDim2.new(1, 0, 0, 0), 2, 12)
		bracket(Vector2.new(0, 1), UDim2.new(0, 0, 1, 0), 12, 2)
		bracket(Vector2.new(0, 1), UDim2.new(0, 0, 1, 0), 2, 12)
		bracket(Vector2.new(1, 1), UDim2.new(1, 0, 1, 0), 12, 2)
		bracket(Vector2.new(1, 1), UDim2.new(1, 0, 1, 0), 2, 12)

		-- Name tag.
		self.NameTag = Create.new("Frame", {
			Name = "NameTag",
			AnchorPoint = Vector2.new(0.5, 1),
			Position = UDim2.new(0.5, 0, 0, -12),
			Size = UDim2.fromOffset(104, 30),
			BackgroundColor3 = palette.Background,
			BackgroundTransparency = 0.1,
			ZIndex = 7,
			Parent = self.Character,
		})
		Create.corner(self.NameTag, 5)
		library:Styled(self.NameTag, "Background", "BackgroundColor3")
		self.NameTagStroke = Create.stroke(self.NameTag, self.Color, 1, 0.45)

		self.NameLabel = Create.label({
			Name = "PlayerName",
			Text = self.Target.Name,
			Font = Enum.Font.GothamBold,
			TextSize = 11,
			TextXAlignment = Enum.TextXAlignment.Center,
			Position = UDim2.fromOffset(2, 4),
			Size = UDim2.new(1, -4, 0, 13),
			ZIndex = 8,
			Parent = self.NameTag,
		})
		library:Styled(self.NameLabel, "Text", "TextColor3")

		local healthTrack = Create.new("Frame", {
			Name = "HealthTrack",
			Position = UDim2.fromOffset(5, 20),
			Size = UDim2.new(1, -10, 0, 3),
			BackgroundColor3 = palette.Outline,
			ZIndex = 8,
			Parent = self.NameTag,
		})
		Create.corner(healthTrack, 1)
		library:Styled(healthTrack, "Outline", "BackgroundColor3")

		self.HealthFill = Create.new("Frame", {
			Name = "HealthFill",
			Size = UDim2.fromScale(1, 1),
			BackgroundColor3 = palette.Success,
			ZIndex = 9,
			Parent = healthTrack,
		})
		Create.corner(self.HealthFill, 1)

		-- Connections.
		table.insert(self._connections, self.Stage:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			self:_updateScale()
		end))

		table.insert(self._connections, library.ThemeManager.Changed:Connect(function()
			self:_applyColor()
			self:_renderTarget()
		end))

		-- Capped 30 Hz animation through the shared scheduler.
		self._task = library.Scheduler:Every(1 / 30, function()
			self:_update()
		end)

		self:_updateScale()
		self:_applyColor()
		self:_renderTarget()
		self:_updateVisibility()

		return self
	end

	function ESPPreview:_updateScale()
		if not self.Stage then
			return
		end

		local height = self.Stage.AbsoluteSize.Y
		if height <= 0 then
			return
		end

		self.CharacterScale.Scale = math.clamp(height / 260, 0.7, 1.05)
	end

	function ESPPreview:_renderChip(key, animate)
		local chip = self.Chips[key]
		if not chip then
			return
		end

		local palette = self.Library.Palette
		local enabled = self.Enabled[key] == true
		local info = animate and Tween.Info.Fast or Tween.Info.Instant

		Tween.play(chip.Button, {
			BackgroundColor3 = enabled and self.Color or palette.SurfaceHigh,
			BackgroundTransparency = enabled and 0.82 or 0.2,
		}, info)

		chip.Dot.BackgroundColor3 = enabled and self.Color or palette.Placeholder
		chip.Label.TextColor3 = enabled and self.Color or palette.SubText
	end

	function ESPPreview:_applyColor()
		local color = self.Color

		if self.LivePill then
			self.LivePill.BackgroundColor3 = color
			self.LiveDot.BackgroundColor3 = color
			self.LiveLabel.TextColor3 = color
		end

		self.Highlight.BackgroundColor3 = color
		self.HighlightGlow.BackgroundColor3 = color
		self.BoxStroke.Color = color
		self.Tracer.BackgroundColor3 = color
		self.NameTagStroke.Color = color

		for _, bracket in ipairs(self._brackets) do
			bracket.BackgroundColor3 = color
		end
		for _, stroke in ipairs(self._partStrokes) do
			stroke.Color = color
		end

		for _, definition in ipairs(CHIP_DEFS) do
			self:_renderChip(definition.Key, false)
		end
	end

	function ESPPreview:_renderTarget()
		local palette = self.Library.Palette
		local target = self.Target
		local fraction = Util.clamp(target.Health / math.max(target.MaxHealth, 1), 0, 1)

		self.NameLabel.Text = tostring(target.Name)
		self.HealthFill.Size = UDim2.fromScale(fraction, 1)
		self.HealthFill.BackgroundColor3 = fraction > 0.6 and palette.Success
			or fraction > 0.3 and palette.Warning
			or palette.Danger
		self.DistanceLabel.Text = tostring(math.floor(target.Distance)) .. " m"
	end

	function ESPPreview:_updateVisibility()
		self.Highlight.Visible = self.Enabled.Highlight == true
		self.HighlightGlow.Visible = self.Highlight.Visible
		self.Box.Visible = self.Enabled.Box == true
		self.Tracer.Visible = self.Enabled.Tracer == true
		self.NameTag.Visible = self.Enabled.Name == true
	end

	function ESPPreview:_update()
		if self.Destroyed then
			return
		end

		-- Pause the animation while the tab, the embed is filtered, or the window is hidden.
		if not self.Frame or not self.Frame.Visible then
			return
		end

		local content = self.Frame.Parent and self.Frame.Parent.Parent
		if content and not content.Visible then
			return
		end
		local main = content and content.Parent
		local root = main and main.Parent and main.Parent.Parent
		if root and root.Visible == false then
			return
		end

		local clock = os.clock()
		self._sway = math.sin(clock * 0.9) * 9
		self._bob = math.sin(clock * 1.8) * 2
		self._lean = math.sin(clock * 0.9 + 0.7) * 1.5

		self.Character.Position = UDim2.new(0.5, self._sway, 0.5, self._bob)
		self.Character.Rotation = self._lean

		if self.Enabled.Highlight then
			self.Highlight.BackgroundTransparency = 0.56 + math.sin(clock * 2.2) * 0.05
			self.HighlightGlow.BackgroundTransparency = 0.9 + math.sin(clock * 1.4) * 0.02
		end

		local stage = self.Stage
		local size = stage.AbsoluteSize
		if size.X <= 0 or size.Y <= 0 then
			return
		end

		local stagePosition = stage.AbsolutePosition
		local characterPosition = self.Character.AbsolutePosition - stagePosition
		local characterSize = self.Character.AbsoluteSize

		local bottom = Vector2.new(size.X * 0.5, size.Y)
		local target = Vector2.new(
			characterPosition.X + characterSize.X * 0.5,
			characterPosition.Y + characterSize.Y * 0.74
		)
		local delta = target - bottom

		self.Tracer.Size = UDim2.fromOffset(math.max(delta.Magnitude, 1), 1.5)
		self.Tracer.Position = UDim2.fromOffset(bottom.X, bottom.Y)
		self.Tracer.Rotation = math.deg(math.atan2(delta.Y, delta.X))
	end

	function ESPPreview:GetSettings()
		return {
			Highlight = self.Enabled.Highlight == true,
			Box = self.Enabled.Box == true,
			Tracer = self.Enabled.Tracer == true,
			Name = self.Enabled.Name == true,
			Color = self.Color,
			Target = self.Target,
		}
	end

	function ESPPreview:_commit()
		self.Changed:Fire(self:GetSettings())
	end

	function ESPPreview:SetEnabled(key, value, silent)
		if self.Enabled[key] == nil or self.Destroyed then
			return
		end

		self.Enabled[key] = value == true
		self:_renderChip(key, true)
		self:_updateVisibility()

		if not silent then
			self:_commit()
		end
	end

	function ESPPreview:Toggle(key)
		if self.Enabled[key] == nil then
			return
		end
		self:SetEnabled(key, not self.Enabled[key])
	end

	function ESPPreview:SetColor(color)
		if typeof(color) ~= "Color3" or self.Destroyed then
			return
		end

		self.Color = color
		self:_applyColor()
		self:_commit()
	end

	function ESPPreview:SetTarget(data)
		if type(data) ~= "table" or self.Destroyed then
			return
		end

		if data.Name ~= nil then
			self.Target.Name = tostring(data.Name)
		end
		if tonumber(data.Health) ~= nil then
			self.Target.Health = tonumber(data.Health)
		end
		if tonumber(data.MaxHealth) ~= nil then
			self.Target.MaxHealth = tonumber(data.MaxHealth)
		end
		if tonumber(data.Distance) ~= nil then
			self.Target.Distance = tonumber(data.Distance)
		end

		self:_renderTarget()
	end

	function ESPPreview:OnChanged(callback)
		return self.Changed:Connect(callback)
	end

	function ESPPreview:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true

		if self._task then
			self.Library.Scheduler:Remove(self._task)
			self._task = nil
		end

		for _, connection in ipairs(self._connections) do
			connection:Disconnect()
		end
		table.clear(self._connections)

		self.Changed:Destroy()
		self.Frame:Destroy()
	end

	return ESPPreview
end

__modules["Components/Keybind"] = function()
	--[[
		Components/Keybind.lua
		Click-to-rebind key capture.

		Supports keyboard keys as well as the three mouse buttons, cancels with
		Escape, and sets `Library.Capturing` while listening so the menu toggle and
		popups don't fire while the user is picking a new key.
	]]

	local UserInputService = game:GetService("UserInputService")

	local Base = __require("Utils/Base")
	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")
	local Util = __require("Utils/Util")

	local Keybind = setmetatable({}, { __index = Base })
	Keybind.__index = Keybind

	function Keybind.new(library, section, config)
		config = config or {}
		config.Height = config.Height or 34
		config.Default = config.Default or Enum.KeyCode.RightShift

		local self = Base.new(library, section, "Keybind", config)
		setmetatable(self, Keybind)

		self.Value = config.Default
		self.Capturing = false
		self.CaptureConnection = nil

		self.Hit = Create.textButton({
			Name = "Hit",
			Size = UDim2.fromScale(1, 1),
			ZIndex = 2,
			Parent = self.Holder,
		})
		self:AddHover(self.Hit)

		self.Label = Create.label({
			Name = "Label",
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -130, 1, 0),
			Text = self.Name,
			TextSize = 13,
			ZIndex = 3,
			Parent = self.Hit,
		})
		library:Styled(self.Label, "Text", "TextColor3")

		self.KeyButton = Create.textButton({
			Name = "Key",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -10, 0.5, 0),
			Size = UDim2.fromOffset(100, 24),
			Text = "",
			TextSize = 11,
			Font = Enum.Font.GothamBold,
			TextXAlignment = Enum.TextXAlignment.Center,
			BackgroundTransparency = 0.15,
			ZIndex = 3,
			Parent = self.Hit,
		})
		Create.corner(self.KeyButton, 6)
		library:Styled(self.KeyButton, "SurfaceHigh", "BackgroundColor3")

		self.KeyStroke = Create.stroke(self.KeyButton, library.Palette.Outline, 1, 0.4)
		library:Styled(self.KeyStroke, "Outline", "Color")

		self:_render()

		self:_track(self.KeyButton.Activated:Connect(function()
			if self.Destroyed then
				return
			end
			if self.Capturing then
				self:EndCapture()
			else
				self:BeginCapture()
			end
		end))

		self:OnThemeChanged(function()
			if not self.Capturing then
				self:_render()
			end
		end)

		return self
	end

	function Keybind:_render()
		local palette = self.Library.Palette
		self.KeyButton.Text = Util.keyName(self.Value)
		self.KeyButton.TextColor3 = palette.Text
		self.KeyStroke.Color = palette.Outline
		self.KeyStroke.Transparency = 0.4
	end

	function Keybind:BeginCapture()
		if self.Capturing or self.Destroyed then
			return
		end

		self.Capturing = true
		-- SetCapturing also stamps the start time, so an abandoned capture times out
		-- instead of blocking the menu toggle forever.
		self.Library:SetCapturing(true)

		self.KeyButton.Text = "Press a key"
		self.KeyButton.TextColor3 = self.Library.Palette.Primary
		self.KeyStroke.Color = self.Library.Palette.Primary
		self.KeyStroke.Transparency = 0.2

		self.CaptureConnection = UserInputService.InputBegan:Connect(function(input)
			if input.KeyCode == Enum.KeyCode.Escape then
				self:EndCapture()
				return
			end

			-- Non-keyboard input reports KeyCode.None; mouse buttons are captured below.
			if input.KeyCode ~= Enum.KeyCode.None then
				self:SetValue(input.KeyCode)
				self:EndCapture()
			elseif input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.MouseButton2
				or input.UserInputType == Enum.UserInputType.MouseButton3
			then
				self:SetValue(input.UserInputType)
				self:EndCapture()
			end
		end)
	end

	function Keybind:EndCapture()
		if not self.Capturing then
			return
		end

		self.Capturing = false
		self.Library:SetCapturing(false)

		if self.CaptureConnection then
			self.CaptureConnection:Disconnect()
			self.CaptureConnection = nil
		end

		if not self.Destroyed then
			self:_render()
		end
	end

	function Keybind:SetValue(value, silent)
		if self.Destroyed or typeof(value) ~= "EnumItem" then
			return
		end

		local changed = self.Value ~= value
		self.Value = value

		if not self.Capturing then
			self:_render()
		end

		if changed then
			self:_commit(value, silent)
		end
	end

	function Keybind:GetValue()
		return self.Value
	end

	function Keybind:Destroy()
		self:EndCapture()
		Base.Destroy(self)
	end

	return Keybind
end

__modules["Components/Notification"] = function()
	--[[
		Components/Notification.lua
		Top-right notification stack with pooled cards.

		Cards slide in from the right, show a shrinking progress bar, pause while
		hovered, and are returned to the pool after their exit animation. A single
		10 Hz scheduler task drives every active card's lifetime.
	]]

	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")
	local Fade = __require("Utils/Fade")
	local Icons = __require("Utils/Icons")
	local Pool = __require("Utils/Pool")

	local Notification = {}
	Notification.__index = Notification

	local HOLDER_WIDTH = 304
	local CARD_HEIGHT = 76
	local MAX_VISIBLE = 4

	function Notification.new(library)
		local self = setmetatable({}, Notification)

		self.Library = library
		self.Entries = {}
		self._byId = {}
		self._widgets = {}
		self._nextId = 0
		self.MaxVisible = MAX_VISIBLE
		self.Destroyed = false

		self.Holder = Create.new("Frame", {
			Name = "Notifications",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -14, 0, 10),
			Size = UDim2.fromOffset(HOLDER_WIDTH, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			ZIndex = 600,
			Parent = library.ScreenGui,
		})

		Create.new("UIListLayout", {
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 8),
			HorizontalAlignment = Enum.HorizontalAlignment.Right,
			VerticalAlignment = Enum.VerticalAlignment.Top,
			Parent = self.Holder,
		})

		self.Pool = Pool.new(function()
			return self:_createCard()
		end, function(wrapper)
			self:_resetCard(wrapper)
		end)

		self._task = library.Scheduler:Every(0.1, function()
			self:_tick()
		end)

		return self
	end

	function Notification:_createCard()
		local library = self.Library
		local palette = library.Palette

		local wrapper = Create.new("Frame", {
			Name = "Notification",
			Size = UDim2.new(1, 0, 0, CARD_HEIGHT),
			BackgroundTransparency = 1,
			ClipsDescendants = true,
			Visible = false,
		})

		local card = Create.new("Frame", {
			Name = "Card",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, 60, 0, 0),
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 0.05,
			Parent = wrapper,
		})
		library:Styled(card, "Surface", "BackgroundColor3")
		Create.corner(card, 9)
		library:Styled(Create.stroke(card, palette.Outline, 1, 0.3), "Outline", "Color")
		library.ThemeManager:BindGradient(
			Create.new("UIGradient", { Rotation = 90, Parent = card }),
			{ "SurfaceHigh", "Surface" }
		)

		local accent = Create.new("Frame", {
			Name = "Accent",
			Position = UDim2.fromOffset(0, 10),
			Size = UDim2.new(0, 3, 1, -20),
			BackgroundColor3 = palette.Primary,
			Parent = card,
		})
		Create.corner(accent, 2)

		local iconHolder = Create.new("Frame", {
			Name = "IconHolder",
			Position = UDim2.fromOffset(12, 12),
			Size = UDim2.fromOffset(30, 30),
			BackgroundColor3 = palette.Primary,
			BackgroundTransparency = 0.85,
			Parent = card,
		})
		Create.corner(iconHolder, 8)

		-- Text label for plain glyphs/emoji; drawn icons are built on demand in the
		-- same holder (see `_setIcon`), because a drawn icon is fixed at one kind.
		local iconLabel = Create.label({
			Name = "IconText",
			Text = "",
			TextSize = 15,
			TextXAlignment = Enum.TextXAlignment.Center,
			TextYAlignment = Enum.TextYAlignment.Center,
			Size = UDim2.fromScale(1, 1),
			Parent = iconHolder,
		})

		local iconImage = Create.new("ImageLabel", {
			Name = "IconImage",
			Size = UDim2.new(1, -10, 1, -10),
			Position = UDim2.fromOffset(5, 5),
			BackgroundTransparency = 1,
			Image = "",
			ScaleType = Enum.ScaleType.Fit,
			Visible = false,
			Parent = iconHolder,
		})

		local title = Create.label({
			Name = "Title",
			Text = "",
			Font = Enum.Font.GothamBold,
			TextSize = 13,
			Position = UDim2.fromOffset(52, 10),
			Size = UDim2.new(1, -100, 0, 16),
			TextTruncate = Enum.TextTruncate.AtEnd,
			Parent = card,
		})
		library:Styled(title, "Text", "TextColor3")

		local content = Create.label({
			Name = "Content",
			Text = "",
			TextSize = 12,
			TextWrapped = true,
			TextTruncate = Enum.TextTruncate.AtEnd,
			TextYAlignment = Enum.TextYAlignment.Top,
			Position = UDim2.fromOffset(52, 27),
			Size = UDim2.new(1, -66, 0, 34),
			Parent = card,
		})
		library:Styled(content, "SubText", "TextColor3")

		local close = Create.textButton({
			Name = "Close",
			Text = "",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -10, 0, 10),
			Size = UDim2.fromOffset(18, 18),
			Parent = card,
		})
		Create.corner(close, 9)

		local closeIcon = Icons.new("close", close, 11, palette.SubText, 2)
		closeIcon.AnchorPoint = Vector2.new(0.5, 0.5)
		closeIcon.Position = UDim2.fromScale(0.5, 0.5)

		library:Styled(close, "SubText", "TextColor3")

		close.MouseEnter:Connect(function()
			Icons.setColor(closeIcon, palette.Danger)
			Tween.play(close, { BackgroundTransparency = 0.8, BackgroundColor3 = palette.Danger }, Tween.Info.Fast)
		end)

		close.MouseLeave:Connect(function()
			Icons.setColor(closeIcon, palette.SubText)
			Tween.play(close, { BackgroundTransparency = 1 }, Tween.Info.Fast)
		end)

		local progressTrack = Create.new("Frame", {
			Name = "ProgressTrack",
			Position = UDim2.fromOffset(10, CARD_HEIGHT - 8),
			Size = UDim2.new(1, -20, 0, 2),
			BackgroundColor3 = palette.Primary,
			BackgroundTransparency = 0.8,
			Parent = card,
		})
		Create.corner(progressTrack, 1)

		local progressFill = Create.new("Frame", {
			Name = "ProgressFill",
			Size = UDim2.fromScale(1, 1),
			BackgroundColor3 = palette.Primary,
			Parent = progressTrack,
		})
		Create.corner(progressFill, 1)

		self._widgets[wrapper] = {
			Card = card,
			Accent = accent,
			IconHolder = iconHolder,
			IconLabel = iconLabel,
			IconImage = iconImage,
			Icon = nil,
			DefaultKind = "diamond",
			Title = title,
			Content = content,
			Close = close,
			ProgressTrack = progressTrack,
			ProgressFill = progressFill,
		}

		local function findEntry()
			local id = wrapper:GetAttribute("CherryNotification")
			return id and self._byId[id] or nil
		end

		card.MouseEnter:Connect(function()
			local entry = findEntry()
			if entry and not entry.Dismissed then
				entry.Hovered = true
				if entry.ProgressTween then
					entry.ProgressTween:Pause()
				end
			end
		end)

		card.MouseLeave:Connect(function()
			local entry = findEntry()
			if entry then
				entry.Hovered = false
				if entry.ProgressTween and not entry.Dismissed then
					entry.ProgressTween:Play()
				end
			end
		end)

		close.Activated:Connect(function()
			local entry = findEntry()
			if entry then
				self:_dismiss(entry)
			end
		end)

		return wrapper
	end

	--[[
		Picks the card's leading icon:
		  * "rbxassetid://…"  -> the ImageLabel (custom art)
		  * a known name/glyph -> a drawn icon, recoloured to the card's accent
		  * anything else     -> the raw glyph/emoji in the text label
		Drawn icons are rebuilt per show because an icon instance is fixed at one
		kind; the card itself is still pooled.
	]]
	function Notification:_setIcon(widgets, accent, icon)
		local kind = nil

		if type(icon) == "string" and string.sub(icon, 1, 10) == "rbxassetid" then
			widgets.IconImage.Image = icon
			widgets.IconImage.Visible = true
			widgets.IconLabel.Visible = false
		elseif icon == nil then
			kind = widgets.DefaultKind or "diamond"
		else
			kind = Icons.resolve(icon)
		end

		if widgets.Icon then
			widgets.Icon:Destroy()
			widgets.Icon = nil
		end

		if kind then
			widgets.IconImage.Visible = false
			widgets.IconImage.Image = ""
			widgets.IconLabel.Visible = false

			local drawn = Icons.new(kind, widgets.IconHolder, 15, accent, 3)
			drawn.AnchorPoint = Vector2.new(0.5, 0.5)
			drawn.Position = UDim2.fromScale(0.5, 0.5)
			widgets.Icon = drawn
		elseif type(icon) == "string" and icon ~= "" and string.sub(icon, 1, 10) ~= "rbxassetid" then
			widgets.IconLabel.Visible = true
			widgets.IconLabel.Text = icon
			widgets.IconLabel.TextColor3 = accent
		end
	end

	function Notification:_resetCard(wrapper)
		local widgets = self._widgets[wrapper]
		if not widgets then
			return
		end

		wrapper.Visible = false
		wrapper:SetAttribute("CherryNotification", nil)

		widgets.Card.Position = UDim2.new(1, 60, 0, 0)
		Fade.set(widgets.Card, 0)
		widgets.ProgressFill.Size = UDim2.fromScale(1, 1)
		widgets.Title.Text = ""
		widgets.Content.Text = ""
		widgets.IconImage.Visible = false
		widgets.IconImage.Image = ""
		widgets.IconLabel.Visible = true

		if widgets.Icon then
			widgets.Icon:Destroy()
			widgets.Icon = nil
		end
	end

	function Notification:Show(config)
		if self.Destroyed then
			return nil
		end

		config = config or {}

		local duration = math.max(tonumber(config.Duration) or 5, 0.1)
		local wrapper = self.Pool:Get(self.Holder)
		local widgets = self._widgets[wrapper]

		self._nextId += 1
		local id = self._nextId

		wrapper:SetAttribute("CherryNotification", id)
		wrapper.Visible = true
		widgets.Card.Visible = true
		-- Newest cards stack on top; the UIListLayout sorts ascending.
		wrapper.LayoutOrder = -id

		local palette = self.Library.Palette
		local accent = config.Color
		if typeof(accent) ~= "Color3" then
			local kind = config.Type or "info"
			if kind == "success" then
				accent = palette.Success
			elseif kind == "warning" then
				accent = palette.Warning
			elseif kind == "error" or kind == "danger" then
				accent = palette.Danger
			else
				accent = palette.Primary
			end
		end

		widgets.Accent.BackgroundColor3 = accent
		widgets.IconHolder.BackgroundColor3 = accent
		widgets.ProgressTrack.BackgroundColor3 = accent
		widgets.ProgressFill.BackgroundColor3 = accent
		widgets.Close.TextColor3 = palette.SubText
		widgets.Title.Text = tostring(config.Title or "Notification")
		widgets.Content.Text = tostring(config.Content or "")

		-- Type drives the default icon when the caller did not pass one.
		local kind = config.Type
		widgets.DefaultKind = (kind == "success" and "success")
			or (kind == "warning" and "warning")
			or ((kind == "error" or kind == "danger") and "error")
			or (kind == "info" and "info")
			or "diamond"

		self:_setIcon(widgets, accent, config.Icon)

		local entry = {
			Id = id,
			Wrapper = wrapper,
			Card = widgets.Card,
			Config = config,
			Duration = duration,
			Remaining = duration,
			Hovered = false,
			Dismissed = false,
		}
		entry.Dismiss = function()
			self:_dismiss(entry)
		end

		self._byId[id] = entry
		table.insert(self.Entries, entry)

		widgets.Card.Position = UDim2.new(1, 60, 0, 0)
		Fade.play(widgets.Card, 1, 0, 0.36, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
		Tween.play(widgets.Card, {
			Position = UDim2.new(1, 0, 0, 0),
		}, Tween.Info.Glide)

		widgets.ProgressFill.Size = UDim2.fromScale(1, 1)
		entry.ProgressTween = Tween.create(widgets.ProgressFill, {
			Size = UDim2.fromScale(0, 1),
		}, Tween.linear(duration))
		entry.ProgressTween:Play()

		-- Dismissed cards linger for their exit animation, so pick the oldest card
		-- that is still visible instead of blindly trimming the head of the list.
		local guard = 0
		while #self.Entries > self.MaxVisible and guard < 10 do
			guard += 1

			local target = nil
			for index = 1, #self.Entries do
				local candidate = self.Entries[index]
				if candidate ~= entry and not candidate.Dismissed then
					target = candidate
					break
				end
			end

			if not target then
				break
			end

			self:_dismiss(target)
		end

		return entry
	end

	function Notification:_dismiss(entry)
		if not entry or entry.Dismissed then
			return
		end

		entry.Dismissed = true

		if entry.ProgressTween then
			entry.ProgressTween:Cancel()
		end

		local widgets = self._widgets[entry.Wrapper]
		if widgets then
			Tween.play(widgets.Card, {
				Position = UDim2.new(1, 60, 0, 0),
			}, Tween.Info.Fast)
			Fade.play(widgets.Card, 0, 1, 0.14)
		end

		local wrapper = entry.Wrapper

		task.delay(0.18, function()
			if self.Destroyed then
				return
			end

			self._byId[entry.Id] = nil

			local index = table.find(self.Entries, entry)
			if index then
				table.remove(self.Entries, index)
			end

			if wrapper and wrapper.Parent then
				self.Pool:Release(wrapper)
			end
		end)
	end

	function Notification:_tick()
		for index = #self.Entries, 1, -1 do
			local entry = self.Entries[index]
			if not entry.Dismissed and not entry.Hovered then
				entry.Remaining -= 0.1
				if entry.Remaining <= 0 then
					self:_dismiss(entry)
				end
			end
		end
	end

	function Notification:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true

		if self._task then
			self.Library.Scheduler:Remove(self._task)
			self._task = nil
		end

		table.clear(self.Entries)
		table.clear(self._byId)

		if self.Pool then
			self.Pool:Destroy()
			self.Pool = nil
		end

		table.clear(self._widgets)

		if self.Holder then
			self.Holder:Destroy()
			self.Holder = nil
		end
	end

	return Notification
end

__modules["Components/PlayerList"] = function()
	--[[
		Components/PlayerList.lua
		Live player list with quick actions.

		Rows are pooled and only rebuilt when the player set changes. The list
		refreshes once per second through the scheduler (and immediately on join /
		leave), so health stays current without per-frame polling.

		Teleporting needs server authority, so it is opt-in:
			list:SetAction("teleport", function(player) ... end)
	]]

	local Players = game:GetService("Players")

	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")
	local Icons = __require("Utils/Icons")
	local Pool = __require("Utils/Pool")
	local Util = __require("Utils/Util")

	local PlayerList = {}
	PlayerList.__index = PlayerList

	local ROW_HEIGHT = 36

	function PlayerList.new(library, parent, config)
		config = config or {}

		local self = setmetatable({}, PlayerList)

		self.Library = library
		self.Height = config.Height or 280
		self.Filter = ""
		self.Destroyed = false
		self.Rows = {}
		self._connections = {}
		self.Actions = {
			teleport = config.OnTeleport,
			-- Spectate and copy work out of the box; teleport needs server authority.
			spectate = config.OnSpectate or function(player)
				self:_spectate(player)
			end,
			copy = config.OnCopy or function(player)
				self:_copy(player)
			end,
		}

		local palette = library.Palette

		self.Frame = Create.new("Frame", {
			Name = "PlayerList",
			Size = UDim2.new(1, 0, 0, self.Height),
			BackgroundTransparency = 0.08,
			Parent = parent,
		})
		library:Styled(self.Frame, "Surface", "BackgroundColor3")
		Create.corner(self.Frame, 10)
		library:Styled(Create.stroke(self.Frame, palette.Outline, 1, 0.4), "Outline", "Color")

		self.Title = Create.label({
			Name = "Title",
			Text = "Players",
			Font = Enum.Font.GothamBold,
			TextSize = 12,
			Position = UDim2.fromOffset(12, 8),
			Size = UDim2.fromOffset(56, 16),
			Parent = self.Frame,
		})
		library:Styled(self.Title, "Text", "TextColor3")

		self.CountLabel = Create.label({
			Name = "Count",
			Text = "(0)",
			TextSize = 10,
			Position = UDim2.fromOffset(70, 9),
			Size = UDim2.fromOffset(40, 16),
			Parent = self.Frame,
		})
		library:Styled(self.CountLabel, "Placeholder", "TextColor3")

		self.SearchFrame = Create.new("Frame", {
			Name = "SearchFrame",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -42, 0, 8),
			Size = UDim2.fromOffset(140, 22),
			BackgroundTransparency = 0.2,
			Parent = self.Frame,
		})
		Create.corner(self.SearchFrame, 6)
		library:Styled(self.SearchFrame, "Background", "BackgroundColor3")
		library:Styled(Create.stroke(self.SearchFrame, palette.Outline, 1, 0.5), "Outline", "Color")

		self.SearchBox = Create.new("TextBox", {
			Name = "Search",
			Position = UDim2.fromOffset(8, 0),
			Size = UDim2.new(1, -12, 1, 0),
			BackgroundTransparency = 1,
			Text = "",
			PlaceholderText = "Filter players",
			Font = Enum.Font.Gotham,
			TextSize = 11,
			TextXAlignment = Enum.TextXAlignment.Left,
			ClearTextOnFocus = false,
			Parent = self.SearchFrame,
		})
		library:Styled(self.SearchBox, "Text", "TextColor3")
		library:Styled(self.SearchBox, "Placeholder", "PlaceholderColor3")

		self.RefreshButton = Create.textButton({
			Name = "Refresh",
			Text = "",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -10, 0, 8),
			Size = UDim2.fromOffset(24, 22),
			Parent = self.Frame,
		})
		Create.corner(self.RefreshButton, 5)

		self.RefreshIcon = Icons.new("refresh", self.RefreshButton, 13, palette.SubText, 2)
		self.RefreshIcon.AnchorPoint = Vector2.new(0.5, 0.5)
		self.RefreshIcon.Position = UDim2.fromScale(0.5, 0.5)
		Icons.bindTheme(self.RefreshIcon, library, "SubText")

		self.RefreshButton.MouseEnter:Connect(function()
			Icons.setColor(self.RefreshIcon, self.Library.Palette.Primary)
			Tween.play(self.RefreshButton, {
				BackgroundTransparency = 0.75,
				BackgroundColor3 = self.Library.Palette.SurfaceHigh,
			}, Tween.Info.Fast)
		end)

		self.RefreshButton.MouseLeave:Connect(function()
			Icons.setColor(self.RefreshIcon, self.Library.Palette.SubText)
			Tween.play(self.RefreshButton, { BackgroundTransparency = 1 }, Tween.Info.Fast)
		end)

		self.List = Create.new("ScrollingFrame", {
			Name = "List",
			Position = UDim2.fromOffset(10, 38),
			Size = UDim2.new(1, -20, 1, -48),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ScrollBarThickness = 3,
			ScrollBarImageTransparency = 0.35,
			ScrollingDirection = Enum.ScrollingDirection.Y,
			CanvasSize = UDim2.new(0, 0, 0, 0),
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			ClipsDescendants = true,
			Parent = self.Frame,
		})
		Create.padding(self.List, 0, 4, 0, 0)
		Create.list(self.List, 3)
		library:Styled(self.List, "Outline", "ScrollBarImageColor3")

		self.Pool = Pool.new(function()
			return self:_createRow()
		end, function(row)
			row:SetAttribute("PlayerName", nil)
			row.Visible = true
		end, 8)

		table.insert(self._connections, self.SearchBox:GetPropertyChangedSignal("Text"):Connect(function()
			self.Filter = self.SearchBox.Text or ""
			self:Refresh()
		end))

		table.insert(self._connections, self.RefreshButton.Activated:Connect(function()
			self:Refresh()
		end))

		table.insert(self._connections, Players.PlayerAdded:Connect(function()
			self:Refresh()
		end))

		table.insert(self._connections, Players.PlayerRemoving:Connect(function()
			self:Refresh()
		end))

		table.insert(self._connections, library.ThemeManager.Changed:Connect(function()
			self:Refresh()
		end))

		self._task = library.Scheduler:Every(1, function()
			if not self.Frame or not self.Frame.Visible then
				return
			end

			local content = self.Frame.Parent and self.Frame.Parent.Parent
			if not content or not content.Visible then
				return
			end

			local main = content.Parent
			local root = main and main.Parent and main.Parent.Parent
			if root and root.Visible == false then
				return
			end

			self:Refresh()
		end)

		self:Refresh()

		return self
	end

	function PlayerList:_createRow()
		local library = self.Library
		local palette = library.Palette

		local row = Create.new("Frame", {
			Name = "Row",
			Size = UDim2.new(1, 0, 0, ROW_HEIGHT),
			BackgroundColor3 = palette.SurfaceHigh,
			BackgroundTransparency = 0.7,
			Parent = nil,
		})
		Create.corner(row, 6)
		library:Styled(row, "SurfaceHigh", "BackgroundColor3")

		local avatar = Create.new("ImageLabel", {
			Name = "Avatar",
			Position = UDim2.fromOffset(5, 5),
			Size = UDim2.fromOffset(26, 26),
			BackgroundColor3 = palette.Surface,
			BackgroundTransparency = 0.2,
			Image = "rbxthumb://type=AvatarHeadShot&id=1&w=48&h=48",
			ScaleType = Enum.ScaleType.Crop,
			Parent = row,
		})
		Create.corner(avatar, UDim.new(1, 0))
		library:Styled(avatar, "Surface", "BackgroundColor3")

		local name = Create.label({
			Name = "PlayerName",
			Text = "",
			TextSize = 12,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Position = UDim2.fromOffset(38, 4),
			Size = UDim2.new(1, -150, 0, 14),
			Parent = row,
		})
		library:Styled(name, "Text", "TextColor3")

		local status = Create.label({
			Name = "Status",
			Text = "",
			TextSize = 10,
			Position = UDim2.fromOffset(38, 19),
			Size = UDim2.new(1, -150, 0, 12),
			Parent = row,
		})
		library:Styled(status, "SubText", "TextColor3")

		local actions = {
			{ Name = "teleport", Label = "TP", Offset = 10, Color = "Primary" },
			{ Name = "spectate", Icon = "eye", Offset = 38 },
			{ Name = "copy", Icon = "copy", Offset = 66 },
		}

		local buttons = {}

		for _, action in ipairs(actions) do
			local button = Create.textButton({
				Name = action.Name,
				Text = action.Label or "",
				TextSize = 10,
				Font = Enum.Font.GothamBold,
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, -action.Offset, 0.5, 0),
				Size = UDim2.fromOffset(24, 22),
				Parent = row,
			})
			Create.corner(button, 4)
			library:Styled(button, "SubText", "TextColor3")

			local icon = action.Icon and Icons.new(action.Icon, button, 13, palette.SubText, 2)
			if icon then
				icon.AnchorPoint = Vector2.new(0.5, 0.5)
				icon.Position = UDim2.fromScale(0.5, 0.5)
			end

			button.Activated:Connect(function()
				local playerName = row:GetAttribute("PlayerName")
				local player = playerName and Players:FindFirstChild(playerName)
				if player then
					self:_runAction(action.Name, player)
				end
			end)

			button.MouseEnter:Connect(function()
				button.TextColor3 = self.Library.Palette.Primary
				button.BackgroundTransparency = 0.75
				button.BackgroundColor3 = self.Library.Palette.Surface
				if icon then
					Icons.setColor(icon, self.Library.Palette.Primary)
				end
			end)

			button.MouseLeave:Connect(function()
				button.TextColor3 = self.Library.Palette.SubText
				button.BackgroundTransparency = 1
				if icon then
					Icons.setColor(icon, self.Library.Palette.SubText)
				end
			end)

			buttons[action.Name] = button
		end

		row.MouseEnter:Connect(function()
			Tween.play(row, { BackgroundTransparency = 0.5 }, Tween.Info.Fast)
		end)

		row.MouseLeave:Connect(function()
			Tween.play(row, { BackgroundTransparency = 0.7 }, Tween.Info.Fast)
		end)

		return row
	end

	function PlayerList:_renderRow(row, player)
		local palette = self.Library.Palette
		local avatar = row:FindFirstChild("Avatar")
		local nameLabel = row:FindFirstChild("PlayerName")
		local statusLabel = row:FindFirstChild("Status")

		if avatar then
			local url = string.format("rbxthumb://type=AvatarHeadShot&id=%d&w=48&h=48", player.UserId)
			-- Avoid re-requesting the same thumbnail every refresh tick.
			if avatar.Image ~= url then
				avatar.Image = url
			end
		end

		local localPlayer = Players.LocalPlayer
		if nameLabel then
			nameLabel.Text = player.Name .. (player == localPlayer and "  (you)" or "")
		end

		local character = player.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")

		if statusLabel then
			if humanoid and humanoid.Health > 0 then
				statusLabel.Text = string.format("Alive · %d HP", math.floor(humanoid.Health))
				statusLabel.TextColor3 = palette.Success
			elseif character then
				statusLabel.Text = "Dead"
				statusLabel.TextColor3 = palette.Danger
			else
				statusLabel.Text = "Loading..."
				statusLabel.TextColor3 = palette.SubText
			end
		end
	end

	function PlayerList:_runAction(name, player)
		local handler = self.Actions[name]

		if type(handler) ~= "function" then
			self.Library:Notify({
				Title = "Action unavailable",
				Content = "Set a handler with PlayerList:SetAction('" .. name .. "', fn).",
				Type = "warning",
			})
			return
		end

		local ok, err = pcall(handler, player)
		if not ok then
			warn("[CherryUI] Player action '" .. name .. "' failed: " .. tostring(err))
		end
	end

	function PlayerList:SetAction(name, callback)
		self.Actions[name] = callback
		return self
	end

	function PlayerList:Refresh()
		if self.Destroyed then
			return
		end

		local players = Players:GetPlayers()
		local localPlayer = Players.LocalPlayer

		table.sort(players, function(a, b)
			if a == b then
				return false
			end
			if a == localPlayer then
				return true
			elseif b == localPlayer then
				return false
			end

			local aName, bName = string.lower(a.Name), string.lower(b.Name)
			if aName == bName then
				return a.UserId < b.UserId
			end
			return aName < bName
		end)

		local filter = string.lower(self.Filter)
		local seen = {}
		local shown = 0

		for _, player in ipairs(players) do
			local matches = filter == "" or string.find(string.lower(player.Name), filter, 1, true) ~= nil
			if matches then
				shown += 1

				local row = self.Rows[player]
				if not row then
					row = self.Pool:Get(self.List)
					self.Rows[player] = row
				end

				row:SetAttribute("PlayerName", player.Name)
				row.LayoutOrder = shown
				row.Visible = true
				self:_renderRow(row, player)

				seen[player] = true
			end
		end

		for player, row in pairs(self.Rows) do
			if not seen[player] then
				self.Rows[player] = nil
				self.Pool:Release(row)
			end
		end

		self.CountLabel.Text = "(" .. tostring(shown) .. ")"
	end

	function PlayerList:_spectate(player)
		local character = player.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")

		if not humanoid then
			self.Library:Notify({
				Title = "Can't spectate",
				Content = player.Name .. " has no character right now.",
				Type = "warning",
			})
			return
		end

		local camera = workspace.CurrentCamera
		if camera then
			camera.CameraType = Enum.CameraType.Custom
			camera.CameraSubject = humanoid
		end

		self.Library:Notify({
			Title = "Spectating",
			Content = player.Name,
			Type = "info",
		})
	end

	function PlayerList:_copy(player)
		local copied = Util.copy(player.Name)

		self.Library:Notify({
			Title = copied and "Copied username" or "Clipboard unavailable",
			Content = copied and player.Name or ("Copy manually: " .. player.Name),
			Type = copied and "success" or "warning",
		})
	end

	function PlayerList:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true

		if self._task then
			self.Library.Scheduler:Remove(self._task)
			self._task = nil
		end

		for _, connection in ipairs(self._connections) do
			connection:Disconnect()
		end
		table.clear(self._connections)

		table.clear(self.Rows)

		if self.Pool then
			self.Pool:Destroy()
			self.Pool = nil
		end

		self.Frame:Destroy()
	end

	return PlayerList
end

__modules["Components/Section"] = function()
	--[[
		Components/Section.lua
		A titled card inside a tab that groups related controls.

		Sections own their controls, hand out layout order, and collapse themselves
		when every child is hidden by search or a dependency.
	]]

	local Create = __require("Utils/Create")

	local Button = __require("Components/Button")
	local ColorPicker = __require("Components/ColorPicker")
	local Dropdown = __require("Components/Dropdown")
	local Keybind = __require("Components/Keybind")
	local Slider = __require("Components/Slider")
	local TextBox = __require("Components/TextBox")
	local Toggle = __require("Components/Toggle")

	local Section = {}
	Section.__index = Section

	function Section.new(library, tab, config)
		config = config or {}

		local self = setmetatable({}, Section)

		self.Library = library
		self.Tab = tab
		self.Name = tostring(config.Name or "Section")
		self.Components = {}
		self.StaticCount = 0
		self.Destroyed = false
		self._order = 0

		local palette = library.Palette

		self.Frame = Create.new("Frame", {
			Name = self.Name,
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = tab:_nextOrder(),
			Parent = tab.Scroller,
		})
		Create.list(self.Frame, 6)

		self.Header = Create.new("Frame", {
			Name = "Header",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 20),
			LayoutOrder = 1,
			Parent = self.Frame,
		})

		self.Accent = Create.new("Frame", {
			Name = "Accent",
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 2, 0.5, 0),
			Size = UDim2.fromOffset(3, 12),
			Parent = self.Header,
		})
		Create.corner(self.Accent, 2)
		library.ThemeManager:BindGradient(
			Create.new("UIGradient", { Rotation = 90, Parent = self.Accent }),
			{ "Primary", "Accent" }
		)

		self.HeaderLabel = Create.label({
			Name = "Title",
			Text = string.upper(self.Name),
			TextSize = 10,
			Font = Enum.Font.GothamBold,
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -12, 1, 0),
			Parent = self.Header,
		})
		library:Styled(self.HeaderLabel, "Primary", "TextColor3")

		self.Body = Create.new("Frame", {
			Name = "Body",
			BackgroundTransparency = 0.1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 2,
			Parent = self.Frame,
		})
		library:Styled(self.Body, "Surface", "BackgroundColor3")
		Create.corner(self.Body, 10)
		library:Styled(Create.stroke(self.Body, palette.Outline, 1, 0.35), "Outline", "Color")
		Create.padding(self.Body, 5, 6, 5, 6)
		Create.list(self.Body, 0)

		return self
	end

	function Section:_nextOrder()
		self._order += 1
		return self._order
	end

	function Section:_add(component)
		table.insert(self.Components, component)
		self:UpdateVisibility()
		return component
	end

	function Section:AddToggle(config)
		return self:_add(Toggle.new(self.Library, self, config))
	end

	function Section:AddButton(config)
		return self:_add(Button.new(self.Library, self, config))
	end

	function Section:AddSlider(config)
		return self:_add(Slider.new(self.Library, self, config))
	end

	function Section:AddDropdown(config)
		return self:_add(Dropdown.new(self.Library, self, config))
	end

	function Section:AddTextBox(config)
		return self:_add(TextBox.new(self.Library, self, config))
	end

	function Section:AddKeybind(config)
		return self:_add(Keybind.new(self.Library, self, config))
	end

	function Section:AddColorPicker(config)
		return self:_add(ColorPicker.new(self.Library, self, config))
	end

	-- Simple non-interactive text block (destroyed with the section).
	function Section:AddLabel(text, config)
		config = config or {}

		local label = Create.label({
			Name = "Label",
			Text = tostring(text),
			TextSize = config.TextSize or 12,
			TextWrapped = true,
			TextColor3 = self.Library.Palette.SubText,
			Position = UDim2.fromOffset(8, 4),
			Size = UDim2.new(1, -16, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = self:_nextOrder(),
			Parent = self.Body,
		})
		self.Library:Styled(label, "SubText", "TextColor3")
		self.StaticCount += 1
		self:UpdateVisibility()

		return label
	end

	function Section:UpdateVisibility(filtering)
		if self.Destroyed then
			return false
		end

		local visibleCount = 0
		for _, component in ipairs(self.Components) do
			if not component.Destroyed and component.Visible then
				visibleCount += 1
			end
		end

		-- Label-only sections (notes, descriptions) have no controls to count.
		local hasVisible = visibleCount > 0
			or (not filtering and #self.Components == 0 and self.StaticCount > 0)
		self.Frame.Visible = hasVisible

		return hasVisible
	end

	function Section:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true

		-- Snapshot: each component unregisters itself from this section.
		local components = table.clone(self.Components)
		for _, component in ipairs(components) do
			component:Destroy()
		end
		table.clear(self.Components)

		if self.Tab and self.Tab.Sections then
			local index = table.find(self.Tab.Sections, self)
			if index then
				table.remove(self.Tab.Sections, index)
			end
		end

		self.Frame:Destroy()

		if self.Tab and not self.Tab.Destroyed then
			self.Tab:UpdateVisibility()
		end
	end

	return Section
end

__modules["Components/Slider"] = function()
	--[[
		Components/Slider.lua
		Smooth slider with a live value display that doubles as a numeric input.

		Dragging updates the value directly (no tweens) so it tracks the cursor
		exactly; clicking the value label lets the user type a precise number. All
		updates are clamped, step-rounded (optional) and formatted via `config.Format`.
	]]

	local UserInputService = game:GetService("UserInputService")

	local Base = __require("Utils/Base")
	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")
	local Util = __require("Utils/Util")

	local Slider = setmetatable({}, { __index = Base })
	Slider.__index = Slider

	function Slider.new(library, section, config)
		config = config or {}
		config.Height = config.Height or 48

		local minimum = tonumber(config.Min) or 0
		local maximum = tonumber(config.Max) or 100
		if maximum <= minimum then
			maximum = minimum + 1
		end

		config.Min = minimum
		config.Max = maximum
		if config.Default == nil then
			config.Default = minimum
		end

		local self = Base.new(library, section, "Slider", config)
		setmetatable(self, Slider)

		self.Min = minimum
		self.Max = maximum
		self.Step = tonumber(config.Step) or 0
		self.Decimals = tonumber(config.Decimals) or 0
		self.Suffix = config.Suffix or ""
		self.Dragging = false

		if type(config.Format) == "function" then
			self.Format = config.Format
		else
			local decimals = self.Decimals
			local suffix = self.Suffix
			self.Format = function(value)
				return Util.trimNumber(value, decimals) .. suffix
			end
		end

		self.Value = self:_clean(tonumber(config.Default) or minimum)

		self.Hit = Create.textButton({
			Name = "Hit",
			Size = UDim2.fromScale(1, 1),
			ZIndex = 2,
			Parent = self.Holder,
		})
		self:AddHover(self.Hit)

		self.Label = Create.label({
			Name = "Label",
			Position = UDim2.fromOffset(12, 5),
			Size = UDim2.new(1, -100, 0, 18),
			Text = self.Name,
			TextSize = 13,
			ZIndex = 3,
			Parent = self.Hit,
		})
		library:Styled(self.Label, "Text", "TextColor3")

		self.ValueBox = Create.new("TextBox", {
			Name = "ValueBox",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -12, 0, 5),
			Size = UDim2.fromOffset(76, 18),
			BackgroundTransparency = 1,
			Text = "",
			TextSize = 12,
			Font = Enum.Font.Code,
			TextXAlignment = Enum.TextXAlignment.Right,
			TextYAlignment = Enum.TextYAlignment.Center,
			ClearTextOnFocus = false,
			ZIndex = 4,
			Parent = self.Hit,
		})
		library:Styled(self.ValueBox, "Primary", "TextColor3")

		self.Track = Create.textButton({
			Name = "Track",
			Position = UDim2.fromOffset(12, 29),
			Size = UDim2.new(1, -24, 0, 14),
			ZIndex = 3,
			Parent = self.Hit,
		})

		self.Rail = Create.new("Frame", {
			Name = "Rail",
			Position = UDim2.fromOffset(0, 5),
			Size = UDim2.new(1, 0, 0, 4),
			ZIndex = 3,
			Parent = self.Track,
		})
		Create.corner(self.Rail, 2)
		library:Styled(self.Rail, "SurfaceHigh", "BackgroundColor3")

		self.Fill = Create.new("Frame", {
			Name = "Fill",
			Size = UDim2.fromScale(0, 1),
			ZIndex = 4,
			Parent = self.Rail,
		})
		Create.corner(self.Fill, 2)
		library.ThemeManager:BindGradient(
			Create.new("UIGradient", { Rotation = 0, Parent = self.Fill }),
			{ "Primary", "Accent" }
		)

		self.Knob = Create.new("Frame", {
			Name = "Knob",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0, 0, 0.5, 0),
			Size = UDim2.fromOffset(12, 12),
			BackgroundColor3 = Color3.new(1, 1, 1),
			ZIndex = 5,
			Parent = self.Track,
		})
		Create.corner(self.Knob, UDim.new(1, 0))
		library:Styled(Create.stroke(self.Knob, library.Palette.Primary, 2, 0), "Primary", "Color")

		self.KnobScale = Create.new("UIScale", { Scale = 1, Parent = self.Knob })

		self:_render()

		self:_wireEvents()

		return self
	end

	function Slider:_alpha()
		return (self.Value - self.Min) / math.max(self.Max - self.Min, 1e-6)
	end

	function Slider:_render()
		local alpha = Util.clamp(self:_alpha(), 0, 1)

		self.Fill.Size = UDim2.new(alpha, 0, 1, 0)
		self.Knob.Position = UDim2.new(alpha, 0, 0.5, 0)

		if not self.ValueBox:IsFocused() then
			self.ValueBox.Text = self.Format(self.Value)
		end
	end

	function Slider:_clean(value)
		value = tonumber(value) or self.Min
		value = Util.clamp(value, self.Min, self.Max)

		if self.Step > 0 then
			value = math.floor(value / self.Step + 0.5) * self.Step
		end

		return Util.clamp(Util.round(value, self.Decimals), self.Min, self.Max)
	end

	function Slider:_valueFromPosition(x)
		local width = self.Track.AbsoluteSize.X
		if width <= 0 then
			return nil
		end

		local relative = Util.clamp((x - self.Track.AbsolutePosition.X) / width, 0, 1)
		return self:_clean(self.Min + (self.Max - self.Min) * relative)
	end

	function Slider:_wireEvents()
		self:_track(self.Track.InputBegan:Connect(function(input)
			if input.UserInputType ~= Enum.UserInputType.MouseButton1
				and input.UserInputType ~= Enum.UserInputType.Touch
			then
				return
			end

			self.Dragging = true
			self:_beginDrag()
			local value = self:_valueFromPosition(input.Position.X)
			if value then
				self:SetValue(value)
			end
		end))

		self:_track(self.Track.MouseEnter:Connect(function()
			Tween.play(self.KnobScale, { Scale = 1.2 }, Tween.Info.Fast)
		end))

		self:_track(self.Track.MouseLeave:Connect(function()
			Tween.play(self.KnobScale, { Scale = 1 }, Tween.Info.Fast)
		end))

		self:_track(self.ValueBox.FocusLost:Connect(function()
			local text = self.ValueBox.Text
			local number = tonumber(string.match(text, "%-?%d+%.?%d*") or "")

			if number then
				self:SetValue(number)
			else
				self:_render()
			end
		end))

		self:OnThemeChanged(function()
			self:_render()
		end)
	end

	-- Drag listeners only exist while a drag is in progress, so idle sliders cost nothing.
	function Slider:_beginDrag()
		if self._dragConnection then
			return
		end

		self._dragConnection = UserInputService.InputChanged:Connect(function(input)
			if not self.Dragging then
				return
			end
			if input.UserInputType ~= Enum.UserInputType.MouseMovement
				and input.UserInputType ~= Enum.UserInputType.Touch
			then
				return
			end

			local value = self:_valueFromPosition(input.Position.X)
			if value then
				self:SetValue(value)
			end
		end)

		self._endConnection = UserInputService.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch
				then
				self:_endDrag()
			end
		end)
	end

	function Slider:_endDrag()
		self.Dragging = false

		if self._dragConnection then
			self._dragConnection:Disconnect()
			self._dragConnection = nil
		end

		if self._endConnection then
			self._endConnection:Disconnect()
			self._endConnection = nil
		end
	end

	function Slider:SetValue(value, silent)
		if self.Destroyed then
			return
		end

		local cleaned = self:_clean(value)
		local changed = self.Value ~= cleaned

		self.Value = cleaned
		self:_render()

		if changed then
			self:_commit(cleaned, silent)
		end
	end

	function Slider:GetValue()
		return self.Value
	end

	function Slider:Destroy()
		self:_endDrag()
		Base.Destroy(self)
	end

	return Slider
end

__modules["Components/Tab"] = function()
	--[[
		Components/Tab.lua
		A tab page: a scrolling column of sections plus optional embeds.

		Lazy loading: pass a builder as the third argument to `window:AddTab` and
		the heavy content is only constructed the first time the tab is selected:
			local tab = window:AddTab("Combat", "target", function(page) ... end)
		Eager `tab:AddSection(...)` calls still work, they just build immediately.
	]]

	local Create = __require("Utils/Create")
	local Icons = __require("Utils/Icons")
	local Section = __require("Components/Section")
	local ESPPreview = __require("Components/ESPPreview")
	local PlayerList = __require("Components/PlayerList")

	local Tab = {}
	Tab.__index = Tab

	function Tab.new(library, window, config)
		config = config or {}

		local self = setmetatable({}, Tab)

		self.Library = library
		self.Window = window
		self.Name = tostring(config.Name or "Tab")
		self.Icon = config.Icon
		self.Builder = config.Builder
		self.Built = false
		self.Destroyed = false
		self.HasContent = true
		self.Sections = {}
		self.Embeds = {}
		self._order = 0

		self.Content = Create.new("Frame", {
			Name = tostring(self.Name) .. "Content",
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			Visible = false,
			Parent = window.Content,
		})

		self.Scroller = Create.new("ScrollingFrame", {
			Name = "Scroller",
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ScrollBarThickness = 4,
			ScrollBarImageTransparency = 0.3,
			ScrollingDirection = Enum.ScrollingDirection.Y,
			CanvasSize = UDim2.new(0, 0, 0, 0),
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			ClipsDescendants = true,
			Parent = self.Content,
		})
		Create.padding(self.Scroller, 2, 10, 14, 10)
		Create.list(self.Scroller, 10)
		library:Styled(self.Scroller, "Outline", "ScrollBarImageColor3")

		return self
	end

	function Tab:_nextOrder()
		self._order += 1
		return self._order
	end

	function Tab:AddSection(name, config)
		config = config or {}

		if type(name) == "table" then
			config = name
			name = config.Name
		end

		config.Name = name or config.Name or "Section"

		local section = Section.new(self.Library, self, config)
		table.insert(self.Sections, section)

		return section
	end

	function Tab:AddESPPreview(config)
		local preview = ESPPreview.new(self.Library, self.Scroller, config)
		preview.Frame.LayoutOrder = self:_nextOrder()
		table.insert(self.Embeds, preview)
		return preview
	end

	function Tab:AddPlayerList(config)
		local list = PlayerList.new(self.Library, self.Scroller, config)
		list.Frame.LayoutOrder = self:_nextOrder()
		table.insert(self.Embeds, list)
		return list
	end

	function Tab:EnsureBuilt()
		if self.Built or self.Destroyed then
			return self
		end

		self.Built = true

		if type(self.Builder) == "function" then
			local ok, err = pcall(self.Builder, self)
			if not ok then
				warn("[CherryUI] Tab '" .. tostring(self.Name) .. "' builder failed: " .. tostring(err))

				-- Show it in the window as well: a half-built tab with no explanation
				-- is the hardest thing in this library to debug from the outside.
				if self.Window and not self.Window.Destroyed then
					self.Window:ShowNotice({
						Type = "error",
						Title = 'Tab "' .. tostring(self.Name) .. '" failed to build',
						Content = tostring(err),
					})
				end
			end
		end

		self:UpdateVisibility(false)
		return self
	end

	function Tab:Select()
		self.Window:SelectTab(self)
	end

	function Tab:UpdateVisibility(filtering, query)
		if self.Destroyed then
			return false
		end

		local visibleSections = 0
		for _, section in ipairs(self.Sections) do
			if section:UpdateVisibility(filtering) then
				visibleSections += 1
			end
		end

		-- A search that names the tab ("esp", "players") keeps its embeds on screen;
		-- otherwise an embed-only tab would dim to empty on every keystroke.
		local nameMatch = false
		if filtering and query and #query > 0 then
			nameMatch = string.find(string.lower(self.Name), query, 1, true) ~= nil
		end

		for _, embed in ipairs(self.Embeds) do
			embed.Frame.Visible = (not filtering) or nameMatch
		end

		local hasContent = visibleSections > 0 or (#self.Embeds > 0 and (not filtering or nameMatch))
		self.HasContent = hasContent

		local transparency = hasContent and 0 or 0.5
		if self.ButtonLabel then
			self.ButtonLabel.TextTransparency = transparency
		end
		if self.ButtonIcon then
			if Icons.isIcon(self.ButtonIcon) then
				Icons.setTransparency(self.ButtonIcon, transparency)
			else
				self.ButtonIcon.TextTransparency = transparency
			end
		end

		return hasContent
	end

	function Tab:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true

		-- Snapshot: sections unregister themselves from this tab.
		local sections = table.clone(self.Sections)
		for _, section in ipairs(sections) do
			section:Destroy()
		end
		table.clear(self.Sections)

		local embeds = table.clone(self.Embeds)
		for _, embed in ipairs(embeds) do
			embed:Destroy()
		end
		table.clear(self.Embeds)

		self.Content:Destroy()

		-- The tab button lives in the window's tab bar, not in Content.
		if self.Button then
			self.Button:Destroy()
			self.Button = nil
		end

		if self.Window.ActiveTab == self then
			self.Window.ActiveTab = nil
		end

		if self.Window.Tabs then
			local index = table.find(self.Window.Tabs, self)
			if index then
				table.remove(self.Window.Tabs, index)
			end
		end
	end

	return Tab
end

__modules["Components/TextBox"] = function()
	--[[
		Components/TextBox.lua
		Text input with an optional numeric mode (clamping + parsing).

		Values are committed on focus loss / Enter. Numeric input accepts an
		optional minus, digits and a decimal point; invalid input restores the last
		valid value instead of calling the user's callback.
	]]

	local Base = __require("Utils/Base")
	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")

	local TextBox = setmetatable({}, { __index = Base })
	TextBox.__index = TextBox

	function TextBox.new(library, section, config)
		config = config or {}
		config.Height = config.Height or 34

		local self = Base.new(library, section, "TextBox", config)
		setmetatable(self, TextBox)

		self.Numeric = config.Numeric == true
		self.Min = tonumber(config.Min)
		self.Max = tonumber(config.Max)
		self.Value = config.Default

		self.Hit = Create.textButton({
			Name = "Hit",
			Size = UDim2.fromScale(1, 1),
			ZIndex = 2,
			Parent = self.Holder,
		})
		self:AddHover(self.Hit)

		self.Label = Create.label({
			Name = "Label",
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -140, 1, 0),
			Text = self.Name,
			TextSize = 13,
			ZIndex = 3,
			Parent = self.Hit,
		})
		library:Styled(self.Label, "Text", "TextColor3")

		self.Box = Create.new("Frame", {
			Name = "Input",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -10, 0.5, 0),
			Size = UDim2.fromOffset(config.Width or 112, 24),
			BackgroundTransparency = 0.15,
			ZIndex = 3,
			Parent = self.Hit,
		})
		Create.corner(self.Box, 6)
		library:Styled(self.Box, "SurfaceHigh", "BackgroundColor3")

		self.BoxStroke = Create.stroke(self.Box, library.Palette.Outline, 1, 0.4)
		library:Styled(self.BoxStroke, "Outline", "Color")

		self.Input = Create.new("TextBox", {
			Name = "Input",
			Position = UDim2.fromOffset(8, 0),
			Size = UDim2.new(1, -16, 1, 0),
			BackgroundTransparency = 1,
			Text = "",
			PlaceholderText = config.Placeholder or (self.Numeric and "0" or "Enter text"),
			Font = Enum.Font.Gotham,
			TextSize = 12,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Center,
			ClearTextOnFocus = config.ClearTextOnFocus == true,
			ZIndex = 4,
			Parent = self.Box,
		})
		library:Styled(self.Input, "Text", "TextColor3")
		library:Styled(self.Input, "Placeholder", "PlaceholderColor3")

		self:_render()

		self:_track(self.Input.Focused:Connect(function()
			Tween.play(self.BoxStroke, { Transparency = 0, Color = self.Library.Palette.Primary }, Tween.Info.Fast)
		end))

		self:_track(self.Input.FocusLost:Connect(function()
			Tween.play(self.BoxStroke, {
				Transparency = 0.4,
				Color = self.Library.Palette.Outline,
			}, Tween.Info.Fast)
			self:_commitInput()
		end))

		self:OnThemeChanged(function()
			self:_render()
		end)

		return self
	end

	function TextBox:_render()
		self._updating = true
		self.Input.Text = self.Value ~= nil and tostring(self.Value) or ""
		self._updating = false
	end

	function TextBox:_commitInput()
		if self.Destroyed then
			return
		end

		local text = self.Input.Text

		if self.Numeric then
			local number = tonumber(string.match(text, "%-?%d+%.?%d*") or "")
			if number == nil then
				self:_render()
				return
			end

			if self.Min then
				number = math.max(number, self.Min)
			end
			if self.Max then
				number = math.min(number, self.Max)
			end

			self:SetValue(number)
		else
			text = string.gsub(text, "^%s+", "")
			text = string.gsub(text, "%s+$", "")
			self:SetValue(text)
		end
	end

	function TextBox:SetValue(value, silent)
		if self.Destroyed then
			return
		end

		local changed = self.Value ~= value
		self.Value = value
		self:_render()

		if changed then
			self:_commit(value, silent)
		end
	end

	function TextBox:GetValue()
		return self.Value
	end

	function TextBox:Destroy()
		Base.Destroy(self)
	end

	return TextBox
end

__modules["Components/Toggle"] = function()
	--[[
		Components/Toggle.lua
		Animated switch. Clicking anywhere on the row toggles it.

		The knob and track are tweened rather than snapped, and the control re-reads
		its colors whenever the theme changes so state colors always match the
		active palette.
	]]

	local Base = __require("Utils/Base")
	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")

	local Toggle = setmetatable({}, { __index = Base })
	Toggle.__index = Toggle

	local TRACK_WIDTH = 38
	local KNOB_SIZE = 14
	local KNOB_PADDING = 3

	function Toggle.new(library, section, config)
		config = config or {}
		config.Height = config.Height or 34
		config.Default = config.Default == true

		local self = Base.new(library, section, "Toggle", config)
		setmetatable(self, Toggle)

		self.Value = config.Default

		self.Hit = Create.textButton({
			Name = "Hit",
			Size = UDim2.fromScale(1, 1),
			ZIndex = 2,
			Parent = self.Holder,
		})
		self:AddHover(self.Hit)

		self.Label = Create.label({
			Name = "Label",
			Size = UDim2.new(1, -76, 1, 0),
			Position = UDim2.fromOffset(12, 0),
			Text = self.Name,
			TextSize = 13,
			ZIndex = 3,
			Parent = self.Hit,
		})
		library:Styled(self.Label, "Text", "TextColor3")

		self.Track = Create.new("Frame", {
			Name = "Track",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -12, 0.5, 0),
			Size = UDim2.fromOffset(TRACK_WIDTH, 20),
			ZIndex = 3,
			Parent = self.Hit,
		})
		Create.corner(self.Track, 10)

		self.TrackStroke = Create.stroke(self.Track, library.Palette.Outline, 1, 0.35)

		self.Knob = Create.new("Frame", {
			Name = "Knob",
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, KNOB_PADDING, 0.5, 0),
			Size = UDim2.fromOffset(KNOB_SIZE, KNOB_SIZE),
			ZIndex = 4,
			Parent = self.Track,
		})
		Create.corner(self.Knob, UDim.new(1, 0))

		self:_render(false)

		self:_track(self.Hit.Activated:Connect(function()
			if self.Destroyed then
				return
			end
			self:SetValue(not self.Value)
		end))

		self:OnThemeChanged(function()
			self:_render(false)
		end)

		return self
	end

	function Toggle:_render(animate)
		local palette = self.Library.Palette
		local info = animate and Tween.Info.Fast or Tween.Info.Instant
		local enabled = self.Value == true

		self.Track.BackgroundColor3 = enabled and palette.Primary or palette.SurfaceHigh
		self.TrackStroke.Color = enabled and palette.Primary or palette.Outline
		self.TrackStroke.Transparency = enabled and 0.7 or 0.35
		self.Knob.BackgroundColor3 = enabled and Color3.new(1, 1, 1) or palette.SubText

		Tween.play(self.Knob, {
			Position = enabled
				and UDim2.new(0, TRACK_WIDTH - KNOB_SIZE - KNOB_PADDING, 0.5, 0)
				or UDim2.new(0, KNOB_PADDING, 0.5, 0),
		}, info)
	end

	function Toggle:SetValue(value, silent)
		if self.Destroyed then
			return
		end

		value = value == true
		local changed = self.Value ~= value

		self.Value = value
		self:_render(changed)

		if changed then
			self:_commit(value, silent)
		end
	end

	function Toggle:GetValue()
		return self.Value == true
	end

	function Toggle:Destroy()
		Base.Destroy(self)
	end

	return Toggle
end

__modules["Components/Window"] = function()
	--[[
		Components/Window.lua
		The main Cherry UI window.

		Reference layout:
		  header  - logo, title, search box, close button (drag handle)
		  tab bar - horizontal tabs with an accent underline + theme dots on the right
		  content - lazily built tab pages

		Performance notes:
		  * `Main` clips its descendants, so nothing draws outside the rounded panel
		  * one global InputChanged/InputEnded connection handles drag and resize
		  * a UIScale keeps the window usable on smaller viewports
	]]

	local UserInputService = game:GetService("UserInputService")

	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")
	local Fade = __require("Utils/Fade")
	local Icons = __require("Utils/Icons")
	local Logo = __require("Core/Logo")
	local Tab = __require("Components/Tab")

	local Window = {}
	Window.__index = Window

	local HEADER_HEIGHT = 44
	local TAB_BAR_HEIGHT = 34
	local TAB_WIDTH = 86

	function Window.new(library, config)
		config = config or {}

		local self = setmetatable({}, Window)

		self.Library = library
		self.Config = config
		self.Title = tostring(config.Title or "Cherry UI")
		self.Subtitle = tostring(config.Subtitle or ("v" .. tostring(library.Version)))
		self.MinWidth = tonumber(config.MinWidth) or 480
		self.MinHeight = tonumber(config.MinHeight) or 300
		self.Resizable = config.Resizable ~= false
		self._resizeAxes = { X = true, Y = true }

		-- Accept both explicit Width/Height and the documented `Size = UDim2` form.
		local width = tonumber(config.Width)
		local height = tonumber(config.Height)
		local size = config.Size

		if typeof(size) == "UDim2" then
			local viewport = self:_viewportSize()

			if size.X.Scale > 0 then
				width = math.floor(viewport.X * size.X.Scale)
			end
			if size.Y.Scale > 0 then
				height = math.floor(viewport.Y * size.Y.Scale)
			end
			if size.X.Offset > 0 then
				width = size.X.Offset
			end
			if size.Y.Offset > 0 then
				height = size.Y.Offset
			end
		end

		self.Width = math.max(width or 640, self.MinWidth)
		self.Height = math.max(height or 460, self.MinHeight)
		self.Tabs = {}
		self.ActiveTab = nil
		self.Visible = false
		self.Destroyed = false
		self.SearchEntries = {}

		self._connections = {}
		self._baseScale = 1
		self._animScale = 1
		self._dragging = false
		self._resizing = false

		self:_build()
		self:_bindEvents()
		self:_updateScale()

		-- The ScreenGui reports a 0x0 AbsoluteSize until its first render, so scale
		-- once more after the frame is on screen (otherwise a small viewport can keep
		-- the window at 100% and push it off the edges).
		task.defer(function()
			if not self.Destroyed then
				self:_updateScale()
			end
		end)

		--[[
			An empty window is undiagnosable from the outside, so after a moment of
			grace it explains itself: this is what happens when the calling script hit
			an error before its first AddTab (or is running a stale bundle).
		]]
		task.delay(1.5, function()
			if self.Destroyed or #self.Tabs > 0 then
				return
			end

			warn(string.format(
				"[CherryUI] Window '%s' has no tabs yet. Add one with window:AddTab(name, icon, builder).",
				self.Title
			))

			self:ShowNotice({
				Type = "info",
				Icon = "layers",
				Title = "This window has no tabs yet",
				Content = table.concat({
					"If your script already calls AddTab, it hit an error before reaching it —",
					"check the Output/console for the first message. Otherwise:",
					'',
					'window:AddTab("Combat", "target", function(tab)',
					'\ttab:AddSection("Aimbot"):AddToggle({ Name = "Enable Aimbot" })',
					'end)',
				}, "\n"),
			})
		end)

		library.Windows[self] = true

		if config.StartOpen ~= false then
			self:Open()
		end

		return self
	end

	function Window:_track(connection)
		table.insert(self._connections, connection)
		return connection
	end

	-- Viewport size with fallbacks for the first frames, when the ScreenGui has not
	-- been laid out yet and `AbsoluteSize` is still (0, 0).
	function Window:_viewportSize()
		local screenGui = self.Library.ScreenGui
		local size = screenGui and screenGui.AbsoluteSize

		if size and size.X > 0 and size.Y > 0 then
			return size
		end

		local camera = workspace.CurrentCamera
		if camera and camera.ViewportSize and camera.ViewportSize.X > 0 then
			return camera.ViewportSize
		end

		return Vector2.new(1280, 800)
	end

	-- Keeps the window inside the viewport, including after a resolution change.
	function Window:_fitToViewport()
		if not self.Root then
			return
		end

		local viewport = self:_viewportSize()
		local factor = math.max(self._baseScale, 0.4)
		local maxWidth = math.max(240, viewport.X / factor - 24)
		local maxHeight = math.max(180, viewport.Y / factor - 24)

		local width = math.clamp(self.Width, math.min(self.MinWidth, maxWidth), maxWidth)
		local height = math.clamp(self.Height, math.min(self.MinHeight, maxHeight), maxHeight)

		if math.floor(width) ~= self.Width or math.floor(height) ~= self.Height then
			self.Width = math.floor(width)
			self.Height = math.floor(height)
			self.Root.Size = UDim2.fromOffset(self.Width, self.Height)
		end
	end

