	function Window:_bindEvents()
		self:_track(self.TitleBar.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch
			then
				self:_startDrag(input)
			end
		end))

		local grips = {
			{ Button = self.ResizeGrip, Axes = { X = true, Y = true } },
			{ Button = self.RightGrip, Axes = { X = true, Y = false } },
			{ Button = self.BottomGrip, Axes = { X = false, Y = true } },
		}

		for _, grip in ipairs(grips) do
			self:_track(grip.Button.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch
				then
					self:_startResize(input, grip.Axes)
				end
			end))
		end

		self:_track(UserInputService.InputChanged:Connect(function(input)
			self:_onInputChanged(input)
		end))

		self:_track(UserInputService.InputEnded:Connect(function(input)
			self:_onInputEnded(input)
		end))

		self:_track(self.CloseButton.Activated:Connect(function()
			self:Close()
		end))

		-- The close button reacts in the danger colour so it never looks like a
		-- plain square: background tint, icon recolour, and a small scale pop.
		self:_track(self.CloseButton.MouseEnter:Connect(function()
			local palette = self.Library.Palette
			Tween.play(self.CloseButton, { BackgroundTransparency = 0.8 }, Tween.Info.Fast)
			Icons.setColor(self.CloseIcon, palette.Danger)
			Icons.setSize(self.CloseIcon, 14, Tween.Info.Fast)
		end))

		self:_track(self.CloseButton.MouseLeave:Connect(function()
			Tween.play(self.CloseButton, { BackgroundTransparency = 1 }, Tween.Info.Fast)
			Icons.setColor(self.CloseIcon, self.Library.Palette.SubText)
			Icons.setSize(self.CloseIcon, 12, Tween.Info.Fast)
		end))

		self:_track(self.CloseButton.MouseEnter:Connect(function()
			Tween.play(self.CloseButton, {
				BackgroundTransparency = 0.15,
				BackgroundColor3 = self.Library.Palette.Danger,
				TextColor3 = Color3.new(1, 1, 1),
			}, Tween.Info.Fast)
		end))

		self:_track(self.CloseButton.MouseLeave:Connect(function()
			Tween.play(self.CloseButton, {
				BackgroundTransparency = 1,
				BackgroundColor3 = self.Library.Palette.SurfaceHigh,
				TextColor3 = self.Library.Palette.SubText,
			}, Tween.Info.Fast)
		end))

		self:_track(self.SearchBox:GetPropertyChangedSignal("Text"):Connect(function()
			self:Filter(self.SearchBox.Text)
		end))

		self:_track(self.SearchBox.Focused:Connect(function()
			Tween.play(self.SearchStroke, {
				Color = self.Library.Palette.Primary,
				Transparency = 0.1,
			}, Tween.Info.Fast)
		end))

		self:_track(self.SearchBox.FocusLost:Connect(function()
			Tween.play(self.SearchStroke, {
				Color = self.Library.Palette.Outline,
				Transparency = 0.35,
			}, Tween.Info.Fast)
		end))

		local screenGui = self.Library.ScreenGui
		if screenGui then
			self:_track(screenGui:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
				self:_updateScale()
			end))
		end

		self:_track(self.Library.ThemeManager.Changed:Connect(function()
			self:_updateThemeDots()
			for _, tab in ipairs(self.Tabs) do
				self:_setTabActive(tab, tab == self.ActiveTab)
			end
		end))
	end

	function Window:_updateScale()
		if not self.Library.ScreenGui then
			return
		end

		local size = self:_viewportSize()
		if size.X <= 0 or size.Y <= 0 then
			return
		end

		local scale = math.min(size.X / 1280, size.Y / 800)
		self._baseScale = math.clamp(scale, 0.7, 1.1)
		self:_applyScale()
		self:_fitToViewport()
	end

	function Window:_applyScale()
		if self.Scale then
			self.Scale.Scale = self._baseScale * self._animScale
		end
	end

	function Window:_startDrag(input)
		if not self.Visible or self.Destroyed then
			return
		end

		if UserInputService:GetFocusedTextBox() then
			return
		end

		self._dragging = true
		self._dragOrigin = self.Library.Overlay.AbsolutePosition

		local absolute = self.Root.AbsolutePosition - self._dragOrigin
		local size = self.Root.AbsoluteSize

		self._dragStartPosition = Vector2.new(absolute.X + size.X * 0.5, absolute.Y + size.Y * 0.5)
		self._dragStartMouse = Vector2.new(input.Position.X, input.Position.Y)
	end

	function Window:_startResize(input, axes)
		if not self.Resizable or not self.Visible or self.Destroyed then
			return
		end

		self._resizing = true
		self._resizeAxes = axes or { X = true, Y = true }
		self._resizeStartMouse = Vector2.new(input.Position.X, input.Position.Y)
		self._resizeStartSize = Vector2.new(self.Root.AbsoluteSize.X, self.Root.AbsoluteSize.Y)
		self._resizeStartTopLeft = self.Root.AbsolutePosition - self.Library.Overlay.AbsolutePosition
	end

	function Window:_onInputChanged(input)
		if input.UserInputType ~= Enum.UserInputType.MouseMovement
			and input.UserInputType ~= Enum.UserInputType.Touch
		then
			return
		end

		if self._dragging then
			local delta = Vector2.new(input.Position.X, input.Position.Y) - self._dragStartMouse
			local center = self._dragStartPosition + delta
			local viewport = self.Library.Overlay.AbsoluteSize
			local size = self.Root.AbsoluteSize

			local minX = size.X * 0.5 - 24
			local maxX = viewport.X - size.X * 0.5 + 24
			local minY = size.Y * 0.5 - 24
			local maxY = viewport.Y - size.Y * 0.5 + 24

			self.Root.Position = UDim2.fromOffset(
				math.clamp(center.X, minX, math.max(minX, maxX)),
				math.clamp(center.Y, minY, math.max(minY, maxY))
			)
		elseif self._resizing then
			local delta = Vector2.new(input.Position.X, input.Position.Y) - self._resizeStartMouse
			local viewport = self:_viewportSize()
			local factor = self.Scale.Scale

			if factor <= 0 then
				factor = 1
			end

			local axes = self._resizeAxes or { X = true, Y = true }
			local topLeft = self._resizeStartTopLeft or Vector2.new(0, 0)

			-- Grow only along the axis the grip belongs to (edges resize one axis).
			local targetWidth = self._resizeStartSize.X / factor
			local targetHeight = self._resizeStartSize.Y / factor
			if axes.X then
				targetWidth += delta.X / factor
			end
			if axes.Y then
				targetHeight += delta.Y / factor
			end

			local maxWidth = math.max(200, (viewport.X - topLeft.X - 12) / factor)
			local maxHeight = math.max(160, (viewport.Y - topLeft.Y - 12) / factor)
			local width = math.floor(math.clamp(targetWidth, math.min(self.MinWidth, maxWidth), maxWidth))
			local height = math.floor(math.clamp(targetHeight, math.min(self.MinHeight, maxHeight), maxHeight))

			self.Width = width
			self.Height = height
			self.Root.Size = UDim2.fromOffset(width, height)

			-- AnchorPoint is centered, so compensate to keep the top-left pinned while resizing.
			self.Root.Position = UDim2.fromOffset(
				topLeft.X + width * factor * 0.5,
				topLeft.Y + height * factor * 0.5
			)
		end
	end

	function Window:_onInputEnded(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch
		then
			self._dragging = false
			self._resizing = false
		end
	end

	--------------------------------------------------------------------------
	-- Notices
	--------------------------------------------------------------------------

	local NOTICE_STYLE = {
		info = { Token = "Primary", Kind = "info" },
		success = { Token = "Success", Kind = "success" },
		warning = { Token = "Warning", Kind = "warning" },
		error = { Token = "Danger", Kind = "error" },
	}

	--[[
		Shows a card across the top of the content area. The console is easy to miss
		(and invisible in a screenshot), so warnings that matter — a tab that failed
		to build, a window with no tabs — are reported in the interface itself.

			window:ShowNotice({
				Type = "error",        -- info | success | warning | error
				Title = "Tab failed to build",
				Content = "...",
				Duration = 8,          -- seconds; omit to keep it on screen
			})

		Returns a handle with `:Dismiss()`. Only one notice shows at a time.
	]]
	function Window:ShowNotice(config)
		config = config or {}

		if self.Destroyed or not self.NoticeHolder then
			return nil
		end

		local library = self.Library
		local style = NOTICE_STYLE[config.Type or "info"] or NOTICE_STYLE.info
		local token = style.Token
		local accent = library.Palette[token] or library.Palette.Primary

		self:ClearNotice()

		local card = Create.new("Frame", {
			Name = "NoticeCard",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 0.05,
			ZIndex = 41,
			Parent = self.NoticeHolder,
		})
		library:Styled(card, "Surface", "BackgroundColor3")
		Create.corner(card, 10)
		library:Styled(Create.stroke(card, accent, 1, 0.45), token, "Color")
		Create.padding(card, 12, 34, 12, 12)

		local accentBar = Create.new("Frame", {
			Name = "Accent",
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 6, 0, 8),
			Size = UDim2.fromOffset(3, 16),
			ZIndex = 42,
			Parent = card,
		})
		Create.corner(accentBar, 2)
		library:Styled(accentBar, token, "BackgroundColor3")

		local icon = Icons.new(Icons.resolve(config.Icon) or style.Kind, card, 16, accent, 42)
		icon.Position = UDim2.fromOffset(2, 0)

		local title = Create.label({
			Name = "Title",
			Text = tostring(config.Title or "Notice"),
			Font = Enum.Font.GothamBold,
			TextSize = 13,
			Position = UDim2.fromOffset(24, 0),
			Size = UDim2.new(1, -24, 0, 17),
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = 42,
			Parent = card,
		})
		library:Styled(title, "Text", "TextColor3")

		local content = Create.label({
			Name = "Content",
			Text = tostring(config.Content or ""),
			TextSize = 11,
			TextWrapped = true,
			TextYAlignment = Enum.TextYAlignment.Top,
			Position = UDim2.fromOffset(24, 18),
			Size = UDim2.new(1, -24, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			ZIndex = 42,
			Parent = card,
		})
		library:Styled(content, "SubText", "TextColor3")

		local close = Create.textButton({
			Name = "Dismiss",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -4, 0, 0),
			Size = UDim2.fromOffset(18, 18),
			Text = "",
			ZIndex = 42,
			Parent = card,
		})
		Create.corner(close, 9)

		local closeIcon = Icons.new("close", close, 10, library.Palette.SubText, 43)
		closeIcon.AnchorPoint = Vector2.new(0.5, 0.5)
		closeIcon.Position = UDim2.fromScale(0.5, 0.5)

		local notice
		notice = {
			Frame = card,
			Dismiss = function()
				if self._notice == notice then
					self:ClearNotice()
				end
			end,
		}

		self._notice = notice
		self.NoticeHolder.Visible = true

		self:_track(close.Activated:Connect(function()
			notice.Dismiss()
		end))

		-- Slide + fade in, so it never just pops into an empty panel.
		card.Position = UDim2.fromOffset(0, -8)
		Fade.play(card, 1, 0, 0.24, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
		Tween.play(card, { Position = UDim2.fromOffset(0, 0) }, Tween.Info.Smooth)

		local duration = tonumber(config.Duration)
		if duration and duration > 0 then
			task.delay(duration, function()
				notice.Dismiss()
			end)
		end

		return notice
	end

	function Window:ClearNotice()
		local notice = self._notice
		if not notice then
			return
		end

		self._notice = nil

		if self.NoticeHolder and not self.NoticeHolder.Destroyed then
			self.NoticeHolder.Visible = false
		end

		if notice.Frame then
			notice.Frame:Destroy()
		end
	end

	--[[
		Adds a tab. Failures are reported in the window instead of silently
		leaving a blank menu (and instead of taking the caller's script down):
		`AddTab` returns nil and the reason appears in a notice card.
	]]
	function Window:AddTab(name, icon, builder)
		if self.Destroyed then
			return nil
		end

		-- window:AddTab("Combat", function(tab) ... end) works too.
		if type(icon) == "function" and builder == nil then
			builder = icon
			icon = nil
		end

		local ok, tab = pcall(self._createTab, self, name, icon, builder)

		if not ok then
			warn("[CherryUI] Could not create tab '" .. tostring(name) .. "': " .. tostring(tab))
			self:ShowNotice({
				Type = "error",
				Title = 'Could not create tab "' .. tostring(name) .. '"',
				Content = tostring(tab),
			})
			return nil
		end

		-- The first tab clears the "no tabs yet" hint.
		self:ClearNotice()
		return tab
	end

	function Window:_createTab(name, icon, builder)
		-- (`Window:CreateTab` is an alias for this, provided at the end of the file.)

		local tab = Tab.new(self.Library, self, {
			Name = name,
			Icon = icon,
			Builder = builder,
		})
		table.insert(self.Tabs, tab)

		local palette = self.Library.Palette
		local button = Create.textButton({
			Name = tostring(name) .. "Tab",
			Size = UDim2.fromOffset(TAB_WIDTH, 26),
			BackgroundColor3 = palette.SurfaceHigh,
			BackgroundTransparency = 1,
			ZIndex = 6,
			Parent = self.TabList,
		})
		button.LayoutOrder = #self.Tabs
		Create.corner(button, 5)

		-- Tab icons accept a friendly name / glyph ("combat", "◎", "🎯") that maps
		-- to a drawn icon; anything else is rendered as text so plain labels and
		-- emoji still work.
		local kind = Icons.resolve(icon)
		local hasIcon = kind ~= nil or (type(icon) == "string" and icon ~= "")
		local offset = hasIcon and 26 or 8

		if kind then
			tab.ButtonIcon = Icons.new(kind, button, 15, palette.SubText, 7)
			tab.ButtonIcon.Position = UDim2.fromOffset(7, 5.5)
		elseif hasIcon then
			tab.ButtonIcon = Create.label({
				Name = "Icon",
				Text = icon,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Center,
				TextColor3 = palette.SubText,
				Position = UDim2.fromOffset(7, 0),
				Size = UDim2.fromOffset(16, 26),
				ZIndex = 7,
				Parent = button,
			})
		end

		local nameLabel = Create.label({
			Name = "Name",
			Text = tostring(name),
			TextSize = 11,
			TextColor3 = palette.SubText,
			Position = UDim2.fromOffset(offset, 0),
			Size = UDim2.new(1, -offset - 4, 1, 0),
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = 7,
			Parent = button,
		})

		local indicator = Create.new("Frame", {
			Name = "Indicator",
			AnchorPoint = Vector2.new(0.5, 1),
			Position = UDim2.new(0.5, 0, 1, 0),
			Size = UDim2.fromOffset(18, 2),
			BackgroundTransparency = 1,
			ZIndex = 7,
			Parent = button,
		})
		Create.corner(indicator, 1)
		self.Library.ThemeManager:Bind(indicator, "BackgroundColor3", "Primary")

		tab.Button = button
		tab.ButtonLabel = nameLabel
		tab.Indicator = indicator

		self:_track(button.MouseEnter:Connect(function()
			if self.ActiveTab ~= tab then
				Tween.play(button, { BackgroundTransparency = 0.7 }, Tween.Info.Fast)
			end
		end))

		self:_track(button.MouseLeave:Connect(function()
			if self.ActiveTab ~= tab then
				Tween.play(button, { BackgroundTransparency = 1 }, Tween.Info.Fast)
			end
		end))

		self:_track(button.Activated:Connect(function()
			self:SelectTab(tab)
		end))

		if #self.Tabs == 1 then
			self:SelectTab(tab, true)
		end

		return tab
	end

	function Window:_setTabActive(tab, active)
		if tab.Destroyed or not tab.Button or not tab.ButtonLabel or not tab.Indicator then
			return
		end

		local palette = self.Library.Palette
		local info = Tween.Info.Fast

		Tween.play(tab.Button, {
			BackgroundTransparency = active and 0.75 or 1,
			BackgroundColor3 = palette.SurfaceHigh,
		}, info)

		Tween.play(tab.ButtonLabel, {
			TextColor3 = active and palette.Primary or palette.SubText,
		}, info)

		if tab.ButtonIcon then
			local color = active and palette.Primary or palette.SubText

			if Icons.isIcon(tab.ButtonIcon) then
				Icons.setColor(tab.ButtonIcon, color)
			else
				Tween.play(tab.ButtonIcon, { TextColor3 = color }, info)
			end
		end

		Tween.play(tab.Indicator, {
			BackgroundTransparency = active and 0 or 1,
			Size = UDim2.fromOffset(active and 22 or 10, 2),
		}, info)
	end

	function Window:SelectTab(tab, instant)
		if self.Destroyed or not tab or tab.Destroyed then
			return
		end

		if self.ActiveTab == tab then
			tab:EnsureBuilt()
			return
		end

		local popup = self.Library:GetActivePopup()
		if popup then
			popup:Close()
		end

		local previous = self.ActiveTab
		self.ActiveTab = tab
		tab:EnsureBuilt()

		if previous and previous ~= tab then
			previous.Content.Visible = false
		end

		local content = tab.Content
		content.Visible = true

		-- A plain Frame cannot group-fade, so `Fade` drives the subtree's
		-- transparency. Skip it while the window itself is fading in, otherwise the
		-- two snapshots would capture each other's in-between values.
		if instant or Fade.playing(self.Root) then
			Fade.set(content, 0)
			content.Position = UDim2.fromOffset(0, 0)
		else
			Fade.play(content, 1, 0, 0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
			content.Position = UDim2.fromOffset(0, 8)
			Tween.play(content, { Position = UDim2.fromOffset(0, 0) }, Tween.Info.Smooth)
		end

		for _, other in ipairs(self.Tabs) do
			self:_setTabActive(other, other == tab)
		end

		self:Filter(self.SearchBox.Text)
	end

	function Window:RegisterSearchEntry(component)
		local keywords = component.Config.Keywords
		if type(keywords) == "string" then
			keywords = { keywords }
		end

		local entry = {
			Component = component,
			Label = component.Name,
			Keywords = keywords,
			Tab = component.Section.Tab,
		}

		table.insert(self.SearchEntries, entry)
		return entry
	end

	function Window:UnregisterSearchEntry(component)
		for index = #self.SearchEntries, 1, -1 do
			if self.SearchEntries[index].Component == component then
				table.remove(self.SearchEntries, index)
			end
		end
	end

	function Window:Filter(query)
		if self.Destroyed then
			return
		end

		local rawQuery = tostring(query or "")
		query = string.lower(rawQuery)
		local filtering = #query > 0

		if filtering then
			for _, tab in ipairs(self.Tabs) do
				tab:EnsureBuilt()
			end
		end

		for _, entry in ipairs(self.SearchEntries) do
			local match = true

			if filtering then
				match = string.find(string.lower(entry.Label), query, 1, true) ~= nil

				if not match and entry.Keywords then
					for _, keyword in ipairs(entry.Keywords) do
						if string.find(string.lower(tostring(keyword)), query, 1, true) then
							match = true
							break
						end
					end
				end
			end

			if entry.Component.SearchMatch ~= match then
				entry.Component.SearchMatch = match
				entry.Component:UpdateVisibility()
			end
		end

		for _, tab in ipairs(self.Tabs) do
			tab:UpdateVisibility(filtering, query)
		end

		local active = self.ActiveTab
		if filtering and active and not active.HasContent then
			self.NoResults.Text = 'No settings match "' .. rawQuery .. '"'
			self.NoResults.Visible = true
		else
			self.NoResults.Visible = false
		end
	end

	function Window:Open(animate)
		if self.Destroyed or self.Visible then
			return
		end

		self.Visible = true
		self:_updateScale()
		self.Root.Visible = true

		if self.Library.Cursor then
			self.Library.Cursor:Refresh()
		end

		if animate == false then
			Fade.set(self.Root, 0)
			self._animScale = 1
			self:_applyScale()
			return
		end

		self._animToken = (self._animToken or 0) + 1
		local token = self._animToken

		Fade.play(self.Root, 1, 0, 0.26, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
		self._animScale = 0.96
		self:_applyScale()

		Tween.number(0.96, 1, 0.32, function(value)
			if self.Destroyed or self._animToken ~= token then
				return
			end
			self._animScale = value
			self:_applyScale()
		end, Enum.EasingStyle.Back, Enum.EasingDirection.Out)

		self:_playLogoIntro()
		self:_playPetalBurst()
	end

	function Window:Close(animate)
		if self.Destroyed or not self.Visible then
			return
		end

		self.Visible = false

		if self.Library.Cursor then
			self.Library.Cursor:Refresh()
		end

		-- A hidden, still-focused search box would swallow the toggle keybind.
		if self.SearchBox and self.SearchBox:IsFocused() then
			self.SearchBox:ReleaseFocus()
		end

		local popup = self.Library:GetActivePopup()
		if popup then
			popup:Close()
		end

		self._animToken = (self._animToken or 0) + 1
		local token = self._animToken

		if animate == false then
			self.Root.Visible = false
			Fade.set(self.Root, 0)
			self._animScale = 1
			self:_applyScale()
			return
		end

		Fade.play(self.Root, 0, 1, 0.16)
		Tween.number(1, 0.96, 0.18, function(value)
			if self.Destroyed or self._animToken ~= token then
				return
			end
			self._animScale = value
			self:_applyScale()
		end)

		task.delay(0.24, function()
			if self.Destroyed or self.Visible or self._animToken ~= token then
				return
			end
			self.Root.Visible = false
			Fade.set(self.Root, 0)
			self._animScale = 1
			self:_applyScale()
		end)
	end

	function Window:Toggle()
		if self.Visible then
			self:Close()
		else
			self:Open()
		end
	end

	function Window:_playLogoIntro()
		if not self.Logo then
			return
		end

		-- The window's own fade already brings the logo's pixels in; adding a second
		-- nested fade would snapshot the logo mid-transition. Only motion here.
		self.Logo.Rotation = -32
		Tween.play(self.Logo, { Rotation = 0 }, Tween.Info.Glide)
	end

	function Window:_playPetalBurst()
		local palette = self.Library.Palette
		local colors = { palette.Primary, palette.Accent, palette.Primary }

		for index = 1, 10 do
			local color = colors[(index % #colors) + 1]
			local petal = Logo.Petal(color, 6 + math.random() * 4)
			petal.Parent = self.Root
			petal.Position = UDim2.fromOffset(26, 22)
			petal.Rotation = math.random(0, 360)

			local angle = (index / 10) * math.pi * 2 + math.random() * 0.35
			local distance = 40 + math.random() * 55
			local targetX = 26 + math.cos(angle) * distance
			local targetY = 22 + math.sin(angle) * distance

			Tween.play(petal, {
				Position = UDim2.fromOffset(targetX, targetY),
				Rotation = petal.Rotation + math.random(-160, 160),
				BackgroundTransparency = 1,
				Size = UDim2.fromOffset(2, 3),
			}, Tween.Info.Glide)

			task.delay(0.5, function()
				if petal and petal.Parent then
					petal:Destroy()
				end
			end)
		end
	end

	function Window:_updateThemeDots()
		if not self._themeDots then
			return
		end

		local active = self.Library.ThemeManager.Name

		for name, dot in pairs(self._themeDots) do
			local isActive = name == active
			Tween.play(dot.Button, {
				Size = UDim2.fromOffset(isActive and 13 or 10, isActive and 13 or 10),
				BackgroundTransparency = isActive and 0 or 0.35,
			}, Tween.Info.Fast)
			dot.Stroke.Transparency = isActive and 0.15 or 1
		end
	end

	function Window:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true
		self.Visible = false

		local popup = self.Library:GetActivePopup()
		if popup then
			popup:Close()
		end

		self.Library.Windows[self] = nil
		if self.Library.PrimaryWindow == self then
			self.Library.PrimaryWindow = nil
		end

		if self.SearchBox and self.SearchBox:IsFocused() then
			self.SearchBox:ReleaseFocus()
		end

		-- Snapshot: each tab removes itself from self.Tabs.
		local tabs = table.clone(self.Tabs)
		for _, tab in ipairs(tabs) do
			tab:Destroy()
		end
		table.clear(self.Tabs)
		table.clear(self.SearchEntries)

		for _, connection in ipairs(self._connections) do
			connection:Disconnect()
		end
		table.clear(self._connections)

		self.Root:Destroy()
	end

	--[[
		Naming alias: plenty of UI libraries call this `CreateTab`, and a missing
		method means the caller's whole script dies on the next line — leaving an
		empty window with no explanation. Both spellings do the same thing.
	]]
	Window.CreateTab = Window.AddTab

	return Window
end

__modules["Core/Cursor"] = function()
	--[[
		Core/Cursor.lua
		The Cherry cursor: Roblox's own arrow, plus a cherry that trails it.

		Earlier versions hid the system pointer and drew a replacement arrow from
		GuiObjects. That is the wrong trade: a drawn arrow is always heavier and
		blurrier than the client's own cursor, its hotspot math is approximate, and
		if anything goes wrong the user is left with no pointer at all.

		So this keeps the native cursor untouched and draws the branding as a small
		badge that follows the pointer with a little lag. The result reads as a
		deliberate accent instead of a worse arrow, never blocks a click (the badge
		sits below-right of the hotspot and is not `Active`), and cannot leave the
		client without a cursor.

		Modes (see `CherryUI:SetCursorMode`):
		  * "always" - the badge is always there (default)
		  * "menu"   - only while a Cherry UI window is open
		  * "off"    - nothing but the Roblox cursor

		Cost: one RenderStepped connection, alive only while the badge is visible.
	]]

	local GuiService = game:GetService("GuiService")
	local RunService = game:GetService("RunService")
	local UserInputService = game:GetService("UserInputService")

	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")

	local Cursor = {}
	Cursor.__index = Cursor

	local BADGE = 20
	-- Where the badge sits relative to the pointer hotspot: clear of the arrow
	-- itself, so the two never overlap.
	local OFFSET = Vector2.new(9, 11)
	-- Follow speed (per second). High enough to feel attached, low enough to trail.
	local FOLLOW = 16
	-- A jump this large is a teleport/respawn, not movement: snap instead of glide.
	local SNAP_DISTANCE = 220

	local MODES = { menu = true, always = true, off = true }
	local LEAF_DARK = Color3.fromHex("22C55E")
	local LEAF_LIGHT = Color3.fromHex("A7F3D0")
	local STEM_COLOR = Color3.fromHex("4ADE80")

	local function topbarInset()
		local ok, inset = pcall(function()
			return GuiService:GetGuiInset()
		end)

		if ok and typeof(inset) == "Vector2" then
			return inset.Y
		end

		return 36
	end

	function Cursor.new(library)
		local self = setmetatable({}, Cursor)

		self.Library = library
		self.Mode = "always"
		self.Visible = false
		self.Destroyed = false
		self.Inset = topbarInset()
		self._position = nil
		self._connection = nil
		self._behaviorConnection = nil
		self._inputConnection = nil

		self.Frame = Create.new("Frame", {
			Name = "CherryCursor",
			AnchorPoint = Vector2.new(0, 0),
			Size = UDim2.fromOffset(BADGE, BADGE),
			BackgroundTransparency = 1,
			Active = false,
			Visible = false,
			ZIndex = 5000,
			Parent = library.ScreenGui,
		})

		self.Scale = Create.new("UIScale", { Scale = 1, Parent = self.Frame })

		-- Soft accent halo so the badge reads on light and dark backgrounds alike.
		local glow = Create.new("Frame", {
			Name = "Glow",
			Position = UDim2.fromScale(-0.2, -0.2),
			Size = UDim2.fromScale(1.4, 1.4),
			BackgroundTransparency = 0.9,
			ZIndex = 1,
			Parent = self.Frame,
		})
		Create.corner(glow, UDim.new(1, 0))
		library:Styled(glow, "Primary", "BackgroundColor3")

		local function cherry(position, size, zIndex)
			local berry = Create.new("Frame", {
				Name = "Cherry",
				Position = position,
				Size = UDim2.fromOffset(size, size),
				ZIndex = zIndex,
				Parent = self.Frame,
			})
			Create.corner(berry, UDim.new(1, 0))
			library.ThemeManager:BindGradient(
				Create.new("UIGradient", { Rotation = 45, Parent = berry }),
				{ "Accent", "Primary" }
			)

			-- A thin light stroke keeps the silhouette readable over dark panels.
			library:Styled(Create.stroke(berry, Color3.new(1, 1, 1), 1, 0.5), "Text", "Color")

			local shine = Create.new("Frame", {
				Name = "Shine",
				Position = UDim2.fromScale(0.2, 0.16),
				Size = UDim2.fromScale(0.32, 0.26),
				BackgroundColor3 = Color3.new(1, 1, 1),
				BackgroundTransparency = 0.4,
				Rotation = -20,
				ZIndex = zIndex + 1,
				Parent = berry,
			})
			Create.corner(shine, UDim.new(1, 0))

			return berry
		end

		-- Stem + leaf first, so the berries overlap them.
		local stem = Create.new("Frame", {
			Name = "Stem",
			Position = UDim2.fromOffset(9, 1),
			Size = UDim2.new(0, 1.6, 0, 6),
			BackgroundColor3 = STEM_COLOR,
			Rotation = 26,
			ZIndex = 2,
			Parent = self.Frame,
		})
		Create.corner(stem, UDim.new(0.5, 0))

		local leaf = Create.new("Frame", {
			Name = "Leaf",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromOffset(12, 3),
			Size = UDim2.fromOffset(9, 5),
			Rotation = -26,
			ZIndex = 2,
			Parent = self.Frame,
		})
		Create.corner(leaf, UDim.new(1, 0))
		Create.new("UIGradient", {
			Rotation = 40,
			Color = ColorSequence.new(LEAF_DARK, LEAF_LIGHT),
			Parent = leaf,
		})

		cherry(UDim2.fromOffset(2, 8), 12, 3)
		cherry(UDim2.fromOffset(11, 11), 10, 4)

		-- Shift-lock / first person hides the pointer; leaving it must restore the
		-- badge even when no window was opened in between.
		self._behaviorConnection = UserInputService:GetPropertyChangedSignal("MouseBehavior"):Connect(function()
			self:Refresh()
		end)

		-- Click feedback: the badge dips when the user presses either mouse button.
		self._inputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)
			if gameProcessed or self.Destroyed or not self.Visible then
				return
			end

			local kind = input.UserInputType
			if kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.MouseButton2 then
				self:_pop()
			end
		end)

		self:Refresh()

		return self
	end

	-- A quick dip-and-settle, driven by the window's own tween presets.
	function Cursor:_pop()
		if not self.Scale then
			return
		end

		self.Scale.Scale = 0.78
		Tween.play(self.Scale, { Scale = 1 }, Tween.Info.Spring)
	end

	-- GUI-space pointer position (the ScreenGui ignores the topbar inset).
	function Cursor:_mousePosition()
		local location = UserInputService:GetMouseLocation()
		return Vector2.new(location.X, location.Y - self.Inset)
	end

	function Cursor:_shouldShow()
		if self.Destroyed or self.Mode == "off" then
			return false
		end

		if UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter then
			return false
		end

		if self.Mode == "always" then
			return true
		end

		local window = self.Library.PrimaryWindow
		return window ~= nil and window.Visible == true and not window.Destroyed
	end

	function Cursor:_follow(delta)
		local target = self:_mousePosition() + OFFSET
		local current = self._position

		if not current then
			self._position = target
		else
			local gap = target - current

			if gap.Magnitude > SNAP_DISTANCE then
				self._position = target
			else
				self._position = current + gap * math.min(1, FOLLOW * (delta or 1 / 60))
			end
		end

		local position = self._position
		self.Frame.Position = UDim2.fromOffset(position.X, position.Y)
	end

	function Cursor:_setVisible(visible)
		if self.Visible == visible then
			return
		end

		self.Visible = visible
		self.Frame.Visible = visible

		if visible then
			self._position = nil
			self:_follow()

			if not self._connection then
				self._connection = RunService.RenderStepped:Connect(function(delta)
					if self:_shouldShow() then
						self:_follow(delta)
					else
						self:_setVisible(false)
					end
				end)
			end
		elseif self._connection then
			self._connection:Disconnect()
			self._connection = nil
		end
	end

	-- Called when window visibility, mouse lock or the mode changes.
	function Cursor:Refresh()
		if self.Destroyed then
			return
		end

		self:_setVisible(self:_shouldShow())
	end

	function Cursor:SetMode(mode)
		if not MODES[mode] then
			warn("[CherryUI] Unknown cursor mode: " .. tostring(mode))
			return false
		end

		self.Mode = mode
		self:Refresh()
		return true
	end

	function Cursor:GetMode()
		return self.Mode
	end

	function Cursor:Destroy()
		if self.Destroyed then
			return
		end

		self:_setVisible(false)
		self.Destroyed = true

		if self._behaviorConnection then
			self._behaviorConnection:Disconnect()
			self._behaviorConnection = nil
		end

		if self._inputConnection then
			self._inputConnection:Disconnect()
			self._inputConnection = nil
		end

		if self.Frame then
			self.Frame:Destroy()
			self.Frame = nil
		end
	end

	return Cursor
end

__modules["Core/Logo"] = function()
	--[[
		Core/Logo.lua
		The Cherry UI mark, drawn entirely with GuiObjects.

		Using frames instead of an image means the logo scales to any size without
		a sprite sheet, adapts to the active theme, and can be animated (the window
		intro rotates and fades it, and `Logo.Petal` powers the petal burst).
	]]

	local Create = __require("Utils/Create")

	local Logo = {}

	local LEAF_DARK = Color3.fromHex("22C55E")
	local LEAF_LIGHT = Color3.fromHex("A7F3D0")
	local STEM_COLOR = Color3.fromHex("4ADE80")

	--[[
		Builds the logo inside `properties.Parent`.
		Colors for the cherries come from the theme palette ("Accent" -> "Primary").
	]]
	function Logo.new(library, properties)
		properties = properties or {}

		local frame = Create.new("Frame", {
			Name = "CherryLogo",
			Size = properties.Size or UDim2.fromOffset(24, 24),
			Position = properties.Position or UDim2.fromOffset(0, 0),
			BackgroundTransparency = 1,
			ZIndex = properties.ZIndex or 5,
			Parent = properties.Parent,
		})

		-- Soft accent halo.
		local glow = Create.new("Frame", {
			Name = "Glow",
			Position = UDim2.fromScale(-0.22, -0.22),
			Size = UDim2.fromScale(1.44, 1.44),
			BackgroundTransparency = 0.9,
			Parent = frame,
		})
		Create.corner(glow, UDim.new(1, 0))
		library:Styled(glow, "Primary", "BackgroundColor3")
		Create.new("UIGradient", {
			Rotation = 90,
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.82),
				NumberSequenceKeypoint.new(1, 1),
			}),
			Parent = glow,
		})

		-- Stems.
		local stems = {
			{ X = 0.44, Y = 0.2, Height = 0.3, Rotation = -24 },
			{ X = 0.57, Y = 0.16, Height = 0.27, Rotation = 18 },
		}

		for _, stemData in stems do
			local stem = Create.new("Frame", {
				Name = "Stem",
				AnchorPoint = Vector2.new(0.5, 0),
				Position = UDim2.fromScale(stemData.X, stemData.Y),
				Size = UDim2.fromScale(0.055, stemData.Height),
				BackgroundColor3 = STEM_COLOR,
				Rotation = stemData.Rotation,
				Parent = frame,
			})
			Create.corner(stem, UDim.new(0.5, 0))
		end

		-- Leaf.
		local leaf = Create.new("Frame", {
			Name = "Leaf",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.65, 0.18),
			Size = UDim2.fromScale(0.36, 0.18),
			Rotation = -28,
			Parent = frame,
		})
		Create.corner(leaf, UDim.new(1, 0))
		Create.new("UIGradient", {
			Rotation = 40,
			Color = ColorSequence.new(LEAF_DARK, LEAF_LIGHT),
			Parent = leaf,
		})

		-- Cherries.
		local function cherry(x, y, size)
			local berry = Create.new("Frame", {
				Name = "Cherry",
				Position = UDim2.fromScale(x, y),
				Size = UDim2.fromScale(size, size),
				Parent = frame,
			})
			Create.corner(berry, UDim.new(1, 0))
			library.ThemeManager:BindGradient(
				Create.new("UIGradient", { Rotation = 45, Parent = berry }),
				{ "Accent", "Primary" }
			)

			local highlight = Create.new("Frame", {
				Name = "Highlight",
				Position = UDim2.fromScale(0.18, 0.14),
				Size = UDim2.fromScale(0.3, 0.24),
				BackgroundColor3 = Color3.new(1, 1, 1),
				BackgroundTransparency = 0.5,
				Parent = berry,
			})
			Create.corner(highlight, UDim.new(1, 0))

			return berry
		end

		cherry(0.07, 0.48, 0.34)
		cherry(0.42, 0.58, 0.36)

		return frame
	end

	--[[
		A single falling petal, used by the window's intro burst.
		The caller owns the returned frame and is responsible for destroying it.
	]]
	function Logo.Petal(color, size)
		size = size or 8

		local petal = Create.new("Frame", {
			Name = "Petal",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Size = UDim2.fromOffset(size * 0.62, size),
			BackgroundColor3 = color,
			ZIndex = 60,
		})

		Create.corner(petal, UDim.new(1, 0))
		Create.new("UIGradient", {
			Rotation = 90,
			Color = ColorSequence.new(color, color:Lerp(Color3.new(1, 1, 1), 0.45)),
			Parent = petal,
		})

		return petal
	end

	return Logo
end

__modules["Core/ThemeManager"] = function()
	--[[
		Core/ThemeManager.lua
		Runtime theme switching with live recoloring.

		Components register their themeable instances with `:Bind`, and the manager
		re-applies the palette when `:SetTheme` is called. Color properties are
		tweened so switching themes feels like part of the UI instead of a hard cut.
		Gradients are handled through `:BindGradient`, which rebuilds the
		ColorSequence from palette tokens.
	]]

	local Tween = __require("Utils/Tween")
	local Signal = __require("Utils/Signal")

	local DEFAULT_THEME = "Crimson"
	local THEME_TWEEN = TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

	local ThemeManager = {}
	ThemeManager.__index = ThemeManager

	function ThemeManager.new(themes, defaultName)
		local self = setmetatable({}, ThemeManager)

		self.Themes = themes or {}
		self.Name = defaultName or DEFAULT_THEME

		if not self.Themes[self.Name] then
			for name in self.Themes do
				self.Name = name
				break
			end
		end

		self.Palette = {}
		self.Bindings = {}
		self.Changed = Signal.new()
		self._loaded = false

		self:_loadPalette(self.Name)

		return self
	end

	function ThemeManager:_loadPalette(name)
		local theme = self.Themes[name]
		if not theme then
			return
		end

		-- Start from the base theme so a partial palette still resolves every token.
		local base = self.Themes[DEFAULT_THEME] or theme
		local merged = {}

		for token, color in base do
			if typeof(color) == "Color3" then
				merged[token] = color
			end
		end

		for token, color in theme do
			if typeof(color) == "Color3" then
				merged[token] = color
			end
		end

		table.clear(self.Palette)
		for token, color in merged do
			self.Palette[token] = color
		end

		self.Palette.Accent = self.Palette.Accent or self.Palette.Primary
	end

	function ThemeManager:GetColor(token)
		return self.Palette[token]
	end

	function ThemeManager:SetTheme(name, animate)
		if not self.Themes[name] then
			warn("[CherryUI] Unknown theme: " .. tostring(name))
			return false
		end

		if name == self.Name and self._loaded then
			return true
		end

		local previous = {}
		for token, color in self.Palette do
			previous[token] = color
		end

		self.Name = name
		self:_loadPalette(name)
		self._loaded = true

		for index = 1, #self.Bindings do
			local binding = self.Bindings[index]

			if binding.Kind == "property" then
				local color = self.Palette[binding.Token]
				local instance = binding.Instance

				if color and instance then
					if animate and previous[binding.Token] ~= color then
						Tween.play(instance, { [binding.Property] = color }, THEME_TWEEN)
					else
						instance[binding.Property] = color
					end
				end
			elseif binding.Kind == "custom" and binding.Apply then
				binding.Apply(self.Palette)
			end
		end

		self.Changed:Fire(name)
		return true
	end

	-- Sets the instance's color immediately and keeps it in sync with the theme.
	function ThemeManager:Bind(instance, property, token)
		property = property or "BackgroundColor3"
		token = token or "Surface"

		local binding = {
			Kind = "property",
			Instance = instance,
			Property = property,
			Token = token,
		}

		local color = self.Palette[token] or self.Palette.Surface
		if color then
			instance[property] = color
		end

		table.insert(self.Bindings, binding)

		local connection
		connection = instance.Destroying:Connect(function()
			self:Unbind(binding)
			if connection then
				connection:Disconnect()
			end
		end)
		binding.Connection = connection

		return instance
	end

	function ThemeManager:BindGradient(gradient, tokens)
		local resolved = tokens or { "Primary", "Accent" }
		local owner = gradient

		local binding = self:BindCustom(function(palette)
			local keypoints = {}
			local count = math.max(#resolved, 1)

			for index = 1, count do
				local color = palette[resolved[index]] or palette.Primary or Color3.new(1, 1, 1)
				local time = 0
				if count > 1 then
					time = (index - 1) / (count - 1)
				end
				table.insert(keypoints, ColorSequenceKeypoint.new(time, color))
			end

			gradient.Color = ColorSequence.new(keypoints)
		end, owner)

		binding.Owner = owner
		return binding
	end

	-- Registers an arbitrary callback that receives the new palette.
	-- `owner` (optional) cleans the binding up when the owner is destroyed.
	function ThemeManager:BindCustom(apply, owner)
		local binding = {
			Kind = "custom",
			Apply = apply,
			Owner = owner,
		}

		table.insert(self.Bindings, binding)
		apply(self.Palette)

		if owner then
			local connection
			connection = owner.Destroying:Connect(function()
				self:Unbind(binding)
				if connection then
					connection:Disconnect()
				end
			end)
			binding.Connection = connection
		end

		return binding
	end

	function ThemeManager:Unbind(binding)
		if not binding then
			return
		end

		local index = table.find(self.Bindings, binding)
		if index then
			table.remove(self.Bindings, index)
		end

		if binding.Connection then
			binding.Connection:Disconnect()
			binding.Connection = nil
		end
	end

	function ThemeManager:Destroy()
		for index = 1, #self.Bindings do
			local binding = self.Bindings[index]
			if binding.Connection then
				binding.Connection:Disconnect()
				binding.Connection = nil
			end
		end

		table.clear(self.Bindings)
		self.Changed:Destroy()
	end

	return ThemeManager
end

