__modules["Utils/Base"] = function()
	--[[
		Utils/Base.lua
		Shared behavior for every Cherry UI control.

		Each control gets a row `Holder` inside its section's card, a `Changed`
		signal, lazy show/hide support for dependencies and search filtering, and a
		consistent `:Destroy()` cleanup path. Controls inherit from this table and
		only implement their visual layer plus `:SetValue()`.
	]]

	local Create = __require("Utils/Create")
	local Signal = __require("Utils/Signal")
	local Tween = __require("Utils/Tween")

	local Base = {}
	Base.__index = Base

	local function matches(expected, value)
		if type(expected) == "function" then
			local ok, result = pcall(expected, value)
			return ok and result and true or false
		elseif type(expected) == "table" then
			for _, item in ipairs(expected) do
				if value == item then
					return true
				end
			end
			return false
		end
		return value == expected
	end

	function Base.new(library, section, kind, config)
		config = config or {}

		local self = setmetatable({}, Base)

		self.Library = library
		self.Section = section
		self.Window = section.Tab.Window
		self.Kind = kind
		self.Name = tostring(config.Name or kind)
		self.Config = config
		self.Default = config.Default
		self.Destroyed = false
		self.Visible = true
		self.SearchMatch = true
		self.ManualVisible = true
		self.Dependencies = {}
		self.RowHeight = config.Height or 34

		self.Changed = Signal.new()
		self._connections = {}

		self.Holder = Create.new("Frame", {
			Name = self.Name,
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, self.RowHeight),
			ClipsDescendants = true,
			Parent = section.Body,
		})
		self.Holder.LayoutOrder = section:_nextOrder()

		library.Config:Register(self)
		self.SearchEntry = self.Window:RegisterSearchEntry(self)

		return self
	end

	function Base:GetValue()
		return self.Value
	end

	--[[
		Stores the value, then fires the public `Changed` signal and the optional
		config callback. `silent` is used by the config manager so restoring a saved
		state does not re-trigger the user's callbacks.
	]]
	function Base:_commit(value, silent)
		self.Value = value

		if silent then
			return
		end

		self.Changed:Fire(value)

		local callback = self.Config.Callback or self.Config.OnChanged
		if type(callback) == "function" then
			local ok, err = pcall(callback, value)
			if not ok then
				warn("[CherryUI] " .. tostring(self.Kind) .. " callback error: " .. tostring(err))
			end
		end
	end

	function Base:SetValue(value, silent)
		self:_commit(value, silent)
	end

	function Base:OnChanged(callback)
		return self.Changed:Connect(callback)
	end

	function Base:OnThemeChanged(callback)
		self:_track(self.Library.ThemeManager.Changed:Connect(callback))
	end

	function Base:_track(connection)
		table.insert(self._connections, connection)
		return connection
	end

	--[[
		Hides this control unless `source:GetValue()` matches `expected`.
		`expected` can be a literal, an array of allowed values, or a predicate.

			local master = section:AddToggle({ Name = "Enable Aimbot" })
			section:AddSlider({ Name = "FOV" }):AddDependency(master)
	]]
	function Base:AddDependency(source, expected)
		if expected == nil then
			expected = true
		end

		table.insert(self.Dependencies, {
			Source = source,
			Expected = expected,
		})

		self:_track(source.Changed:Connect(function()
			self:UpdateVisibility()
		end))

		self:UpdateVisibility()
		return self
	end

	function Base:SetVisible(visible)
		self.ManualVisible = visible ~= false
		self:UpdateVisibility()
		return self
	end

	function Base:UpdateVisibility()
		if self.Destroyed then
			return
		end

		local visible = self.ManualVisible and self.SearchMatch

		if visible then
			for _, dependency in ipairs(self.Dependencies) do
				local source = dependency.Source
				local met = false

				if not source.Destroyed then
					met = matches(dependency.Expected, source:GetValue())
				end

				if not met then
					visible = false
					break
				end
			end
		end

		if visible == self.Visible then
			return
		end

		self.Visible = visible
		self._visibilityToken = (self._visibilityToken or 0) + 1
		local token = self._visibilityToken

		if visible then
			self.Holder.Visible = true
			Tween.play(self.Holder, { Size = UDim2.new(1, 0, 0, self.RowHeight) }, Tween.Info.Fast)
		else
			Tween.play(self.Holder, { Size = UDim2.new(1, 0, 0, 0) }, Tween.Info.Fast)
			task.delay(0.16, function()
				if not self.Destroyed and self._visibilityToken == token then
					self.Holder.Visible = false
				end
			end)
		end

		self.Section:UpdateVisibility()
	end

	-- Adds the standard hover highlight. `target` receives the mouse events.
	function Base:AddHover(target)
		target = target or self.Holder

		local hover = Create.new("Frame", {
			Name = "Hover",
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			ZIndex = 1,
			Parent = self.Holder,
		})
		Create.corner(hover, 6)
		self.Library:Styled(hover, "SurfaceHigh", "BackgroundColor3")

		self:_track(target.MouseEnter:Connect(function()
			Tween.play(hover, { BackgroundTransparency = 0.5 }, Tween.Info.Fast)
		end))

		self:_track(target.MouseLeave:Connect(function()
			Tween.play(hover, { BackgroundTransparency = 1 }, Tween.Info.Fast)
		end))

		return hover
	end

	function Base:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true

		self.Library.Config:Unregister(self)
		self.Window:UnregisterSearchEntry(self)

		local index = self.Section and table.find(self.Section.Components, self)
		if index then
			table.remove(self.Section.Components, index)
		end

		for _, connection in ipairs(self._connections) do
			connection:Disconnect()
		end
		table.clear(self._connections)

		self.Changed:Destroy()
		self.Holder:Destroy()

		if self.Section and not self.Section.Destroyed then
			self.Section:UpdateVisibility()
		end

		self.Value = nil
		self.SearchEntry = nil
	end

	return Base
end

__modules["Utils/Config"] = function()
	--[[
		Utils/Config.lua
		Serializes the whole UI state (component values, theme, menu keybind) and
		persists it through one of four backends:

		  * "memory"    - keeps the data for the current session (default)
		  * "file"      - JSON file via executor functions (writefile/readfile)
		  * "custom"    - your own save/load functions (RemoteFunction, ProfileStore...)
		  * "datastore" - DataStore:GetAsync/SetAsync (server-side or via a bridge)

		Components register themselves automatically, so saving works without any
		extra bookkeeping from the user.
	]]

	local HttpService = game:GetService("HttpService")

	local Config = {}
	Config.__index = Config

	local function encode(value)
		local valueType = typeof(value)

		if valueType == "Color3" then
			return { __type = "Color3", r = value.R, g = value.G, b = value.B }
		elseif valueType == "EnumItem" then
			return { __type = "Enum", enum = tostring(value.EnumType), name = value.Name }
		elseif valueType == "table" then
			local output = {}
			for key, item in pairs(value) do
				local encoded = encode(item)
				if encoded ~= nil then
					output[key] = encoded
				end
			end
			return output
		elseif valueType == "number" or valueType == "string" or valueType == "boolean" then
			return value
		end

		return nil
	end

	local function decode(value)
		if type(value) ~= "table" then
			return value
		end

		if value.__type == "Color3" then
			return Color3.new(tonumber(value.r) or 0, tonumber(value.g) or 0, tonumber(value.b) or 0)
		elseif value.__type == "Enum" then
			local enumName = string.match(tostring(value.enum or ""), "Enum%.(.+)")
			local enum = enumName and Enum[enumName]
			if enum and value.name then
				return enum[value.name]
			end
			return nil
		end

		local output = {}
		for key, item in pairs(value) do
			output[key] = decode(item)
		end
		return output
	end

	local function executorFunction(name)
		local ok, result = pcall(function()
			return _G[name]
		end)
		if ok and type(result) == "function" then
			return result
		end

		local okGenv, genv = pcall(function()
			return getgenv and getgenv() or nil
		end)
		if okGenv and type(genv) == "table" and type(genv[name]) == "function" then
			return genv[name]
		end

		return nil
	end

	function Config.new(library)
		local self = setmetatable({}, Config)

		self.Library = library
		self.Components = {}
		self.Mode = "memory"
		self.Storage = nil
		self.DataStore = nil
		self.DataKey = "CherryUI_Config"
		self.FilePath = "CherryUI/config.json"
		self.Memory = nil
		self._ids = {}
		self._connections = {}
		self._dirty = false
		self._autoTask = nil
		self.Destroyed = false

		return self
	end

	function Config:Register(component)
		local id = component.Config.Id
		if id == nil then
			id = tostring(component.Kind) .. "_" .. tostring(component.Name)
			id = string.gsub(id, "[^%w_]", "_")
		end

		local base = id
		local index = 2
		while self._ids[id] do
			id = base .. "_" .. tostring(index)
			index += 1
		end

		self._ids[id] = true
		component.ConfigId = id

		table.insert(self.Components, component)
		self._connections[component] = component.Changed:Connect(function()
			self:MarkDirty()
		end)

		return id
	end

	function Config:Unregister(component)
		local index = table.find(self.Components, component)
		if index then
			table.remove(self.Components, index)
		end

		local connection = self._connections[component]
		if connection then
			connection:Disconnect()
			self._connections[component] = nil
		end
	end

	function Config:MarkDirty()
		self._dirty = true
	end

	function Config:Serialize()
		local data = {
			version = self.Library.Version,
			theme = self.Library.ThemeManager.Name,
			toggleKey = encode(self.Library.ToggleKey),
			values = {},
		}

		for _, component in ipairs(self.Components) do
			if not component.Destroyed then
				local ok, value = pcall(function()
					return component:GetValue()
				end)

				if ok and value ~= nil then
					local encoded = encode(value)
					if encoded ~= nil then
						data.values[component.ConfigId] = encoded
					end
				end
			end
		end

		return data
	end

	function Config:Apply(data)
		if self.Destroyed or type(data) ~= "table" then
			return false
		end

		-- Lazy tabs must exist before their controls can receive saved values.
		self.Library:_buildAllTabs()

		if type(data.theme) == "string" and self.Library.Themes[data.theme] then
			self.Library:SetTheme(data.theme)
		end

		if data.toggleKey ~= nil then
			local key = decode(data.toggleKey)
			if key ~= nil then
				self.Library:SetToggleKey(key)
			end
		end

		local values = data.values
		if type(values) == "table" then
			for _, component in ipairs(self.Components) do
				local encoded = values[component.ConfigId]
				if encoded ~= nil then
					local ok, value = pcall(decode, encoded)
					if ok and value ~= nil then
						pcall(function()
							component:SetValue(value, true)
						end)
					end
				end
			end
		end

		self.Library:RefreshVisibility()
		self._dirty = false
		return true
	end

	function Config:SetMode(mode, options)
		options = options or {}
		self.Mode = mode

		if mode == "file" then
			self.FilePath = options.Path or options.FilePath or self.FilePath
		elseif mode == "custom" then
			self.Storage = {
				save = options.save or options.Save,
				load = options.load or options.Load,
			}
		elseif mode == "datastore" then
			self.DataStore = options.Store or options.store
			self.DataKey = options.Key or options.key or self.DataKey
		end
	end

	function Config:Save()
		if self.Destroyed then
			return false
		end

		-- Include controls in tabs that have never been opened.
		self.Library:_buildAllTabs()

		local data = self:Serialize()
		self.Memory = data

		local success = false
		local mode = self.Mode

		if mode == "file" then
			local writefile = executorFunction("writefile")
			if not writefile then
				warn("[CherryUI] writefile is unavailable, keeping the config in memory instead.")
				self._dirty = false
				return true
			end

			local folder = string.match(self.FilePath, "^(.+)/[^/]+$")
			if folder then
				local isfolder = executorFunction("isfolder")
				local makefolder = executorFunction("makefolder")
				if isfolder and makefolder then
					local checked, exists = pcall(isfolder, folder)
					if not checked or not exists then
						pcall(makefolder, folder)
					end
				end
			end

			local ok, err = pcall(writefile, self.FilePath, HttpService:JSONEncode(data))
			if not ok then
				warn("[CherryUI] Failed to write config: " .. tostring(err))
			end
			success = ok
		elseif mode == "custom" and self.Storage and type(self.Storage.save) == "function" then
			local ok, err = pcall(self.Storage.save, data)
			if not ok then
				warn("[CherryUI] Custom save failed: " .. tostring(err))
			end
			success = ok
		elseif mode == "datastore" and self.DataStore then
			local ok, err = pcall(function()
				self.DataStore:SetAsync(self.DataKey, data)
			end)
			if not ok then
				warn("[CherryUI] DataStore save failed: " .. tostring(err))
			end
			success = ok
		else
			-- Memory mode: `self.Memory` is the saved state.
			success = true
		end

		if success then
			self._dirty = false
		end

		return success
	end

	function Config:Load()
		if self.Destroyed then
			return false
		end

		local data = nil
		local mode = self.Mode

		if mode == "file" then
			local readfile = executorFunction("readfile")
			local isfile = executorFunction("isfile")
			if not readfile then
				return false
			end
			if isfile then
				local checked, exists = pcall(isfile, self.FilePath)
				if not checked or not exists then
					return false
				end
			end

			local ok, contents = pcall(readfile, self.FilePath)
			if not ok or type(contents) ~= "string" or contents == "" then
				return false
			end

			local decoded, parsed = pcall(HttpService.JSONDecode, HttpService, contents)
			if not decoded then
				warn("[CherryUI] Config file is not valid JSON: " .. tostring(parsed))
				return false
			end
			data = parsed
		elseif mode == "custom" and self.Storage and type(self.Storage.load) == "function" then
			local ok, result = pcall(self.Storage.load)
			if not ok then
				warn("[CherryUI] Custom load failed: " .. tostring(result))
				return false
			end
			data = result
		elseif mode == "datastore" and self.DataStore then
			local ok, result = pcall(function()
				return self.DataStore:GetAsync(self.DataKey)
			end)
			if not ok then
				warn("[CherryUI] DataStore load failed: " .. tostring(result))
				return false
			end
			data = result
		else
			data = self.Memory
		end

		if type(data) ~= "table" then
			return false
		end

		return self:Apply(data)
	end

	function Config:Reset()
		if self.Destroyed then
			return false
		end

		self.Library:_buildAllTabs()

		for _, component in ipairs(self.Components) do
			if component.Default ~= nil then
				local defaultValue = component.Default
				if type(defaultValue) == "table" then
					local copy = {}
					for key, value in pairs(defaultValue) do
						copy[key] = value
					end
					defaultValue = copy
				end

				pcall(function()
					component:SetValue(defaultValue, true)
				end)
			end
		end

		self.Library:SetTheme(self.Library.ThemeOrder[1] or "Crimson")
		self.Library:SetToggleKey(Enum.KeyCode.RightShift)
		self.Library:RefreshVisibility()
		self._dirty = false
		return true
	end

	function Config:EnableAutoSave(interval)
		if self._autoTask then
			return
		end

		self._autoTask = self.Library.Scheduler:Every(interval or 30, function()
			if self._dirty then
				self:Save()
			end
		end)
	end

	function Config:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true

		if self._autoTask then
			self.Library.Scheduler:Remove(self._autoTask)
			self._autoTask = nil
		end

		for _, connection in self._connections do
			connection:Disconnect()
		end

		table.clear(self._connections)
		table.clear(self.Components)
		table.clear(self._ids)
	end

	return Config
end

__modules["Utils/Create"] = function()
	--[[
		Utils/Create.lua
		Small helpers around Instance.new. Every Cherry UI element is built in code,
		so these helpers keep the component files short and visually consistent.

		`Create.new` applies properties before parenting the instance, which avoids a
		layout/update pass for every property assignment.
	]]

	local Create = {}

	local function applyProperties(instance, properties)
		for key, value in properties do
			if key ~= "Parent" then
				instance[key] = value
			end
		end
	end

	function Create.new(className, properties, children)
		local instance = Instance.new(className)

		if properties then
			applyProperties(instance, properties)
		end

		if children then
			for index = 1, #children do
				children[index].Parent = instance
			end
		end

		if properties and properties.Parent then
			instance.Parent = properties.Parent
		end

		return instance
	end

	function Create.corner(parent, radius)
		return Create.new("UICorner", {
			CornerRadius = typeof(radius) == "UDim" and radius or UDim.new(0, radius or 8),
			Parent = parent,
		})
	end

	function Create.stroke(parent, color, thickness, transparency)
		return Create.new("UIStroke", {
			Color = color or Color3.new(1, 1, 1),
			Thickness = thickness or 1,
			Transparency = transparency or 0,
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			LineJoinMode = Enum.LineJoinMode.Round,
			Parent = parent,
		})
	end

	function Create.padding(parent, top, right, bottom, left)
		if right == nil then
			right = top
		end
		if bottom == nil then
			bottom = top
		end
		if left == nil then
			left = right
		end

		return Create.new("UIPadding", {
			PaddingTop = UDim.new(0, top or 0),
			PaddingRight = UDim.new(0, right or 0),
			PaddingBottom = UDim.new(0, bottom or 0),
			PaddingLeft = UDim.new(0, left or 0),
			Parent = parent,
		})
	end

	function Create.list(parent, padding, sortOrder)
		return Create.new("UIListLayout", {
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = sortOrder or Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, padding or 0),
			Parent = parent,
		})
	end

	function Create.label(properties)
		local base = {
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Font = Enum.Font.GothamMedium,
			Text = "",
			TextColor3 = Color3.new(1, 1, 1),
			TextSize = 13,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Center,
		}

		for key, value in properties do
			base[key] = value
		end

		return Create.new("TextLabel", base)
	end

	function Create.textButton(properties)
		local base = {
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Font = Enum.Font.GothamMedium,
			Text = "",
			TextColor3 = Color3.new(1, 1, 1),
			TextSize = 13,
		}

		for key, value in properties do
			base[key] = value
		end

		return Create.new("TextButton", base)
	end

	--[[
		Creates a soft drop shadow made of three stacked frames.
		The layers are placed as siblings behind `frame`, so the caller must place
		both inside a wrapper that is large enough to show the spread.
	]]
	function Create.shadow(container, frame, color, spread, radius)
		spread = spread or 6
		local layers = {}

		for index = 1, 3 do
			local offset = spread * (index / 3)
			local shadow = Create.new("Frame", {
				Name = "Shadow" .. index,
				BackgroundColor3 = color or Color3.new(0, 0, 0),
				BackgroundTransparency = 0.86 + index * 0.04,
				Position = UDim2.fromOffset(-offset, -offset + 3),
				Size = UDim2.new(1, offset * 2, 1, offset * 2),
				ZIndex = math.max((frame.ZIndex or 2) - 1, 1),
				Parent = container,
			})
			Create.corner(shadow, (radius or 14) + offset)
			table.insert(layers, shadow)
		end

		return layers
	end

	return Create
end

__modules["Utils/Fade"] = function()
	--[[
		Utils/Fade.lua
		Whole-subtree fading for plain GuiObjects.

		Roblox only exposes `GroupTransparency` on CanvasGroup, and a CanvasGroup
		re-rasterises its entire subtree whenever any descendant changes — the wrong
		trade for a library that animates an ESP preview at 30 Hz. Instead, `Fade`
		snapshots the transparency of every descendant once, then drives them together
		through a single number tween.

		Transparency is interpolated as `base + (1 - base) * alpha`, so:
		  * alpha 0 restores each element's own transparency exactly (nothing drifts)
		  * alpha 1 hides the subtree no matter what its per-element values were
		  * elements that are already invisible (base = 1) stay invisible

		The snapshot is dropped when a fade completes at alpha 0 (a clean state), and
		kept when it completes at alpha 1 (the values are polluted, but the bases are
		still the clean ones), so close -> open cycles never lose their baseline.
	]]

	local Tween = __require("Utils/Tween")

	local Fade = {}

	-- Only numeric transparency properties. Reading a property the instance does not
	-- have returns nil, which the numeric check below filters out.
	local PROPERTIES = {
		"BackgroundTransparency",
		"TextTransparency",
		"TextStrokeTransparency",
		"ImageTransparency",
		"ScrollBarImageTransparency",
		"Transparency",
	}

	-- root -> { Entries = { { Instance, Property, Base } }, Alpha, Token }
	local Cache = setmetatable({}, { __mode = "k" })

	local function addEntries(entries, instance)
		for index = 1, #PROPERTIES do
			local property = PROPERTIES[index]
			local value = instance[property]

			if type(value) == "number" then
				table.insert(entries, { Instance = instance, Property = property, Base = value })
			end
		end
	end

	local function capture(root)
		local entries = {}

		addEntries(entries, root)
		for _, descendant in ipairs(root:GetDescendants()) do
			addEntries(entries, descendant)
		end

		return { Entries = entries, Alpha = 0, Token = 0 }
	end

	local function apply(state, alpha)
		local entries = state.Entries

		for index = 1, #entries do
			local entry = entries[index]
			local base = entry.Base
			entry.Instance[entry.Property] = base + (1 - base) * alpha
		end

		state.Alpha = alpha
	end

	local function stateFor(root)
		local state = Cache[root]

		if not state then
			state = capture(root)
			Cache[root] = state
		end

		return state
	end

	-- Instantly sets a subtree's fade level (0 = normal, 1 = invisible).
	function Fade.set(root, alpha)
		if not root then
			return
		end

		local state = stateFor(root)
		apply(state, alpha)

		if alpha <= 0 then
			Cache[root] = nil
		end
	end

	--[[
		Animates a subtree from `from` to `to`.
		`onComplete` runs exactly once, for the newest fade on that root only, so a
		rapid open/close cannot leave a half-faded window.
	]]
	function Fade.play(root, from, to, duration, style, direction, onComplete)
		if not root then
			return nil
		end

		local state = stateFor(root)
		state.Token += 1
		local token = state.Token

		apply(state, from)

		local tween = Tween.number(from, to, duration or 0.24, function(value)
			if state.Token ~= token then
				return
			end
			apply(state, value)
		end, style, direction)

		task.delay(duration or 0.24, function()
			if state.Token ~= token then
				return
			end

			apply(state, to)

			if to <= 0 then
				Cache[root] = nil
			end

			if onComplete then
				onComplete()
			end
		end)

		return tween
	end

	function Fade.playing(root)
		local state = Cache[root]
		return state ~= nil and state.Alpha > 0
	end

	-- Drops a cached snapshot (for callers that rebuild a subtree in place).
	function Fade.invalidate(root)
		if root then
			Cache[root] = nil
		end
	end

	return Fade
end

__modules["Utils/Icons"] = function()
	--[[
		Utils/Icons.lua
		Crisp, themeable icons drawn entirely from GuiObjects.

		Why not text glyphs? Roblox's default fonts have no coverage for the
		"dingbat" range (⌕ ✕ ▾ ✓ ◉ …), so those characters render as tofu boxes.
		Uploaded images are not an option either: a drop-in library cannot ship
		asset IDs. Every icon here is composed from a few rounded Frames instead,
		which means it is font-independent, stays sharp at any size, recolors with
		the theme, and animates (rotation, transparency) like any other instance.

		Icons are designed once on a 20x20 grid and scaled to the requested size, so
		the same drawing drives a 12px dropdown check and the 24px cursor arrow.

			Icons.new("target", parent, 16, palette.Primary)
			Icons.setColor(icon, palette.SubText)
			Icons.setTransparency(icon, 0.5)   -- used by tab dimming
	]]

	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")

	local Icons = {}

	-- The design grid every builder draws on.
	Icons.Grid = 20

	-- frame -> { Parts = { { Instance, Color, Transparency } }, Size = n } (weak keys)
	local Registry = setmetatable({}, { __mode = "k" })

	--[[
		A single recolorable part. `color` and `transparency` are the property names
		to write, so one record serves Frames (BackgroundColor3/BackgroundTransparency)
		and strokes (Color/Transparency) alike.
	]]
	local function part(parts, instance, colorProperty, transparencyProperty, color)
		if colorProperty then
			instance[colorProperty] = color
		end

		table.insert(parts, {
			Instance = instance,
			Color = colorProperty,
			Transparency = transparencyProperty,
		})

		return instance
	end

	--------------------------------------------------------------------------
	-- Primitives (each registers what it draws)
	--------------------------------------------------------------------------

	--[[
		A rounded stroke between two points on the design grid.
		One rotated bar beats stacking axis-aligned ones, which leave notches at the
		joints. Used for every diagonal: checks, chevrons, the cursor arrow.
	]]
	function Icons.line(parts, parent, x1, y1, x2, y2, thickness, color, zIndex)
		local dx, dy = x2 - x1, y2 - y1
		local length = math.sqrt(dx * dx + dy * dy)

		local bar = Create.new("Frame", {
			Name = "Line",
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.fromOffset(x1, y1),
			Size = UDim2.fromOffset(length, thickness),
			Rotation = math.deg(math.atan2(dy, dx)),
			ZIndex = zIndex or 3,
			Parent = parent,
		})
		Create.corner(bar, UDim.new(0.5, 0))

		return part(parts, bar, "BackgroundColor3", "BackgroundTransparency", color)
	end

	-- A stroke-only circle/ellipse (UICorner 1 makes any size an ellipse).
	function Icons.ring(parts, parent, x, y, width, height, thickness, color, zIndex)
		local ring = Create.new("Frame", {
			Name = "Ring",
			Position = UDim2.fromOffset(x, y),
			Size = UDim2.fromOffset(width, height),
			BackgroundTransparency = 1,
			ZIndex = zIndex or 2,
			Parent = parent,
		})
		Create.corner(ring, UDim.new(1, 0))

		local stroke = Create.new("UIStroke", {
			Thickness = thickness,
			Parent = ring,
		})

		return part(parts, stroke, "Color", "Transparency", color)
	end

	function Icons.dot(parts, parent, x, y, size, color, zIndex)
		local dot = Create.new("Frame", {
			Name = "Dot",
			Position = UDim2.fromOffset(x, y),
			Size = UDim2.fromOffset(size, size),
			ZIndex = zIndex or 4,
			Parent = parent,
		})
		Create.corner(dot, UDim.new(1, 0))

		return part(parts, dot, "BackgroundColor3", "BackgroundTransparency", color)
	end

	-- A rotated square: the cheapest solid diamond.
	function Icons.diamond(parts, parent, x, y, size, radius, color, zIndex)
		local shape = Create.new("Frame", {
			Name = "Diamond",
			Position = UDim2.fromOffset(x, y),
			Size = UDim2.fromOffset(size, size),
			Rotation = 45,
			ZIndex = zIndex or 2,
			Parent = parent,
		})
		Create.corner(shape, radius or UDim.new(0, 2))

		return part(parts, shape, "BackgroundColor3", "BackgroundTransparency", color)
	end

	-- A stroke-only rounded rectangle (used by "layers" and "copy").
	function Icons.outline(parts, parent, x, y, width, height, radius, thickness, color, zIndex)
		local shape = Create.new("Frame", {
			Name = "Outline",
			Position = UDim2.fromOffset(x, y),
			Size = UDim2.fromOffset(width, height),
			BackgroundTransparency = 1,
			ZIndex = zIndex or 2,
			Parent = parent,
		})
		Create.corner(shape, radius)

		local stroke = Create.new("UIStroke", {
			Thickness = thickness,
			Parent = shape,
		})

		return part(parts, stroke, "Color", "Transparency", color)
	end

	--------------------------------------------------------------------------
	-- Builders: one per icon kind, each draws at `color` on the canvas
	--------------------------------------------------------------------------

	local BUILDERS = {}

	BUILDERS.target = function(parts, color, canvas)
		Icons.ring(parts, canvas, 5, 5, 10, 10, 1.8, color)
		Icons.line(parts, canvas, 10, 1, 10, 4, 1.8, color)
		Icons.line(parts, canvas, 10, 16, 10, 19, 1.8, color)
		Icons.line(parts, canvas, 1, 10, 4, 10, 1.8, color)
		Icons.line(parts, canvas, 16, 10, 19, 10, 1.8, color)
		Icons.dot(parts, canvas, 8.6, 8.6, 2.8, color)
	end

	BUILDERS.eye = function(parts, color, canvas)
		Icons.ring(parts, canvas, 2, 6, 16, 8, 1.8, color)
		Icons.dot(parts, canvas, 8, 8, 4, color)
	end

	BUILDERS.layers = function(parts, color, canvas)
		Icons.outline(parts, canvas, 5, 2, 10, 10, UDim.new(0, 2), 1.8, color, 2)
		Icons.outline(parts, canvas, 5, 8.5, 10, 10, UDim.new(0, 2), 1.8, color, 3)
	end

	BUILDERS.players = function(parts, color, canvas)
		Icons.ring(parts, canvas, 7, 1.5, 6, 6, 1.8, color)
		Icons.outline(parts, canvas, 3, 11, 14, 7, UDim.new(0.5, 0), 1.8, color, 2)
	end

	BUILDERS.settings = function(parts, color, canvas)
		for _, row in ipairs({
			{ Y = 6, Knob = 12 },
			{ Y = 10, Knob = 6 },
			{ Y = 14, Knob = 14 },
		}) do
			Icons.line(parts, canvas, 3, row.Y, 17, row.Y, 1.6, color)
			Icons.dot(parts, canvas, row.Knob - 2.1, row.Y - 2.1, 4.2, color)
		end
	end

	BUILDERS.search = function(parts, color, canvas)
		Icons.ring(parts, canvas, 2.5, 2.5, 11, 11, 1.8, color)
		Icons.line(parts, canvas, 12, 12, 17.5, 17.5, 1.8, color)
	end

	BUILDERS.close = function(parts, color, canvas)
		Icons.line(parts, canvas, 4.5, 4.5, 15.5, 15.5, 1.8, color)
		Icons.line(parts, canvas, 15.5, 4.5, 4.5, 15.5, 1.8, color)
	end

	BUILDERS.check = function(parts, color, canvas)
		Icons.line(parts, canvas, 3.5, 10.5, 8, 15, 1.9, color)
		Icons.line(parts, canvas, 8, 15, 16.5, 4.5, 1.9, color)
	end

	-- Points down at rotation 0; the dropdown rotates it 180 degrees when open.
	BUILDERS.chevron = function(parts, color, canvas)
		Icons.line(parts, canvas, 4.5, 7.5, 10, 13, 1.9, color)
		Icons.line(parts, canvas, 10, 13, 15.5, 7.5, 1.9, color)
	end

	BUILDERS.refresh = function(parts, color, canvas)
		Icons.ring(parts, canvas, 3.5, 3.5, 13, 13, 1.8, color)
		Icons.line(parts, canvas, 12.5, 1.8, 17.2, 1.8, 1.8, color)
		Icons.line(parts, canvas, 17.2, 1.8, 17.2, 6.5, 1.8, color)
	end

	BUILDERS.copy = function(parts, color, canvas)
		Icons.outline(parts, canvas, 3, 2, 9, 11, UDim.new(0, 2), 1.6, color, 2)
		Icons.outline(parts, canvas, 8, 7, 9, 11, UDim.new(0, 2), 1.6, color, 3)
	end

	BUILDERS.diamond = function(parts, color, canvas)
		Icons.diamond(parts, canvas, 5, 5, 10, UDim.new(0, 2), color)
	end

	BUILDERS.info = function(parts, color, canvas)
		Icons.ring(parts, canvas, 2, 2, 16, 16, 1.8, color)
		Icons.dot(parts, canvas, 8.9, 5.5, 2.4, color)
		Icons.line(parts, canvas, 10, 9.5, 10, 14.5, 1.8, color)
	end

	BUILDERS.warning = function(parts, color, canvas)
		Icons.ring(parts, canvas, 2, 2, 16, 16, 1.8, color)
		Icons.line(parts, canvas, 10, 6, 10, 11.5, 1.8, color)
		Icons.dot(parts, canvas, 8.9, 13.2, 2.4, color)
	end

	BUILDERS.success = function(parts, color, canvas)
		Icons.ring(parts, canvas, 2, 2, 16, 16, 1.8, color)
		Icons.line(parts, canvas, 6, 10.5, 9, 13.5, 1.8, color)
		Icons.line(parts, canvas, 9, 13.5, 14.5, 6.5, 1.8, color)
	end

	BUILDERS.error = function(parts, color, canvas)
		Icons.ring(parts, canvas, 2, 2, 16, 16, 1.8, color)
		Icons.line(parts, canvas, 7, 7, 13, 13, 1.8, color)
		Icons.line(parts, canvas, 13, 7, 7, 13, 1.8, color)
	end

	-- The pointer arrow used by Core/Cursor.lua: a stroke-drawn arrowhead plus a
	-- tail. Drawn rather than textured so it never depends on an asset id.
	BUILDERS.cursor = function(parts, color, canvas)
		Icons.line(parts, canvas, 4.5, 1.5, 4.5, 14.5, 1.9, color)
		Icons.line(parts, canvas, 4.5, 1.5, 11, 12, 1.9, color)
		Icons.line(parts, canvas, 4.5, 14.5, 11, 12, 1.9, color)
		Icons.line(parts, canvas, 11, 12, 13.5, 18.5, 2.4, color)
	end

	--------------------------------------------------------------------------
	-- Aliases: friendly names, the old glyphs (existing scripts keep working) and
	-- the emoji people tend to type.
	--------------------------------------------------------------------------

	local ALIASES = {
		target = "target",
		crosshair = "target",
		aim = "target",
		aimbot = "target",
		combat = "target",
		["◎"] = "target",
		["🎯"] = "target",

		layers = "layers",
		visuals = "layers",
		esp = "layers",
		render = "layers",
		["◈"] = "layers",
		["🧊"] = "layers",

		players = "players",
		player = "players",
		list = "players",
		people = "players",
		["☰"] = "players",
		["👥"] = "players",

		settings = "settings",
		config = "settings",
		gear = "settings",
		options = "settings",
		["⚙"] = "settings",
		["⚙️"] = "settings",

		eye = "eye",
		spectate = "eye",
		info = "info",
		["◉"] = "eye",
		["👁"] = "eye",

		search = "search",
		["⌕"] = "search",
		["🔍"] = "search",

		close = "close",
		["✕"] = "close",
		["×"] = "close",
		["✗"] = "close",

		check = "check",
		["✓"] = "check",
		["✔"] = "check",

		chevron = "chevron",
		["▾"] = "chevron",
		["▿"] = "chevron",

		refresh = "refresh",
		reload = "refresh",
		rescan = "refresh",
		["⟳"] = "refresh",
		["↻"] = "refresh",

		copy = "copy",
		clipboard = "copy",
		["⧉"] = "copy",

		diamond = "diamond",
		notification = "diamond",
		["◆"] = "diamond",

		warning = "warning",
		["⚠"] = "warning",
		danger = "error",
		error = "error",
		success = "success",

		cursor = "cursor",
		arrow = "cursor",
		pointer = "cursor",
	}

	-- Maps a glyph / friendly name / kind to a drawable kind, or nil when the
	-- string should be rendered as text (a plain letter or an emoji we don't draw).
	function Icons.resolve(icon)
		if type(icon) ~= "string" then
			return nil
		end

		local kind = ALIASES[icon]
		if kind and BUILDERS[kind] then
			return kind
		end

		return nil
	end

	--------------------------------------------------------------------------
	-- Public API
	--------------------------------------------------------------------------

	--[[
		Builds an icon.
		    kind   - a key from ALIASES / BUILDERS ("target", "close", "cursor", …)
		    parent - parent instance
		    size   - rendered size in pixels (default 16)
		    color  - single colour for every part
	]]
	function Icons.new(kind, parent, size, color, zIndex)
		size = size or 16
		color = color or Color3.new(1, 1, 1)
		zIndex = zIndex or 5

		local root = Create.new("Frame", {
			Name = "Icon_" .. tostring(kind),
			Size = UDim2.fromOffset(size, size),
			BackgroundTransparency = 1,
			ZIndex = zIndex,
			Parent = parent,
		})

		--[[
			The design canvas is 20x20 and a UIScale maps it to the requested size.
			The UIScale sits on the *canvas*, not on the root: UIScale scales the
			GuiObject it is a child of, so hanging it on the root would shrink the
			root's own box and throw off any AnchorPoint-based centering.
		]]
		local canvas = Create.new("Frame", {
			Name = "Canvas",
			Size = UDim2.fromOffset(Icons.Grid, Icons.Grid),
			BackgroundTransparency = 1,
			ZIndex = zIndex,
			Parent = root,
		})

		local scale = Create.new("UIScale", { Scale = size / Icons.Grid, Parent = canvas })

		local parts = {}
		local builder = BUILDERS[kind]

		if builder then
			builder(parts, color, canvas)
		else
			warn("[CherryUI] Unknown icon kind: " .. tostring(kind))
		end

		Registry[root] = {
			Parts = parts,
			Canvas = canvas,
			Scale = scale,
			Size = size,
		}

		return root
	end

	--[[
		Resizes a drawn icon. The drawing lives on a fixed 20x20 design grid that a
		UIScale maps onto the requested size, so both have to move together; passing
		tween info animates the change (used for the close button hover pop).
	]]
	function Icons.setSize(icon, size, info)
		local entry = Registry[icon]
		if not entry then
			return icon
		end

		entry.Size = size

		local rootSize = UDim2.fromOffset(size, size)
		local target = { Scale = size / Icons.Grid }

		if info then
			Tween.play(entry.Scale, target, info)
			Tween.play(icon, { Size = rootSize }, info)
		else
			entry.Scale.Scale = target.Scale
			icon.Size = rootSize
		end

		return icon
	end

	-- Recolors every part of a drawn icon.
	function Icons.setColor(icon, color)
		local entry = Registry[icon]
		if not entry then
			return icon
		end

		for _, item in ipairs(entry.Parts) do
			if item.Color then
				item.Instance[item.Color] = color
			end
		end

		return icon
	end

	-- Fades a drawn icon (0 = solid, 1 = invisible) and hides it entirely at 1.
	function Icons.setTransparency(icon, transparency)
		local entry = Registry[icon]
		if not entry then
			return icon
		end

		for _, item in ipairs(entry.Parts) do
			if item.Transparency then
				item.Instance[item.Transparency] = transparency
			end
		end

		return icon
	end

	-- Keeps every part of an icon in sync with a theme token ("Primary", "SubText").
	function Icons.bindTheme(icon, library, token)
		local entry = Registry[icon]
		if not entry then
			return icon
		end

		for _, item in ipairs(entry.Parts) do
			if item.Color then
				library.ThemeManager:Bind(item.Instance, item.Color, token)
			end
		end

		return icon
	end

	function Icons.isIcon(instance)
		return Registry[instance] ~= nil
	end

	return Icons
end

__modules["Utils/Pool"] = function()
	--[[
		Utils/Pool.lua
		A minimal object pool.

		Used by the notification stack and by dropdown option rows so opening and
		closing UI never spikes the instance count. Pooled objects are unparented on
		release so they cost nothing to render.
	]]

	local Pool = {}
	Pool.__index = Pool

	function Pool.new(create, reset, prefill)
		local self = setmetatable({}, Pool)

		self.Create = create or function()
			return Instance.new("Frame")
		end
		self.Reset = reset
		self.Free = {}
		self.Active = {}
		self.Destroyed = false

		for _ = 1, prefill or 0 do
			local object = self.Create()
			object.Parent = nil
			table.insert(self.Free, object)
		end

		return self
	end

	function Pool:Get(parent)
		local object = table.remove(self.Free)

		if object == nil then
			object = self.Create()
		end

		self.Active[object] = true

		if parent then
			object.Parent = parent
		end

		return object
	end

	function Pool:Release(object)
		if object == nil or self.Active[object] == nil then
			return
		end

		self.Active[object] = nil

		if self.Reset then
			self.Reset(object)
		end

		object.Parent = nil

		if self.Destroyed then
			object:Destroy()
		else
			table.insert(self.Free, object)
		end
	end

	function Pool:ReleaseAll()
		local active = {}

		for object in self.Active do
			table.insert(active, object)
		end

		for index = 1, #active do
			self:Release(active[index])
		end
	end

	function Pool:Destroy()
		self.Destroyed = true

		local owned = {}

		for object in self.Active do
			table.insert(owned, object)
		end
		for index = 1, #self.Free do
			table.insert(owned, self.Free[index])
		end

		self.Active = {}
		self.Free = {}

		for index = 1, #owned do
			owned[index]:Destroy()
		end
	end

	return Pool
end

__modules["Utils/Popup"] = function()
	--[[
		Utils/Popup.lua
		A themed floating panel used by the dropdown and color picker.

		Popups live in the library overlay (not inside the scrolling tab), so they
		are never clipped by the window, and a full-screen click catcher closes them
		when the user clicks outside. Only one popup can be open at a time.
	]]

	local Create = __require("Utils/Create")
	local Tween = __require("Utils/Tween")
	local Fade = __require("Utils/Fade")

	local Popup = {}
	Popup.__index = Popup

	function Popup.new(library, config)
		config = config or {}

		local self = setmetatable({}, Popup)

		self.Library = library
		self.Width = config.Width or 200
		self.Height = config.Height or 140
		self.OnClose = config.OnClose
		self.IsOpen = false
		self.Destroyed = false

		self.Catcher = Create.new("TextButton", {
			Name = "PopupCatcher",
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			Text = "",
			AutoButtonColor = false,
			Visible = false,
			ZIndex = 900,
			Parent = library.Overlay,
		})

		self.Frame = Create.new("Frame", {
			Name = config.Name or "Popup",
			Size = UDim2.fromOffset(self.Width, self.Height),
			Visible = false,
			ClipsDescendants = true,
			ZIndex = 901,
			Parent = library.Overlay,
		})
		library:Styled(self.Frame, "Surface", "BackgroundColor3")
		Create.corner(self.Frame, 10)
		library:Styled(Create.stroke(self.Frame, library.Palette.Outline, 1, 0.25), "Outline", "Color")

		self.Scale = Create.new("UIScale", { Scale = 1, Parent = self.Frame })

		self.Catcher.Activated:Connect(function()
			self:Close()
		end)

		return self
	end

	function Popup:SetSize(width, height)
		self.Width = width
		self.Height = height
		self.Frame.Size = UDim2.fromOffset(width, height)
	end

	function Popup:Open(anchor)
		if self.Destroyed or self.IsOpen or not anchor then
			return
		end

		self.IsOpen = true
		self.Library:SetActivePopup(self)

		self.Catcher.Visible = true
		self.Frame.Visible = true

		local overlay = self.Library.Overlay
		local overlayPosition = overlay.AbsolutePosition
		local overlaySize = overlay.AbsoluteSize
		local anchorPosition = anchor.AbsolutePosition - overlayPosition
		local anchorSize = anchor.AbsoluteSize
		local width = self.Width
		local height = self.Height

		local x = anchorPosition.X + anchorSize.X - width
		local y = anchorPosition.Y + anchorSize.Y + 6

		if y + height > overlaySize.Y - 8 then
			y = anchorPosition.Y - height - 6
		end

		x = math.clamp(x, 8, math.max(8, overlaySize.X - width - 8))
		y = math.clamp(y, 8, math.max(8, overlaySize.Y - height - 8))

		self.Frame.Position = UDim2.fromOffset(x, y)
		self.Scale.Scale = 0.96

		Fade.play(self.Frame, 1, 0, 0.12)
		Tween.play(self.Scale, { Scale = 1 }, Tween.Info.Fast)
	end

	function Popup:Close()
		if not self.IsOpen then
			return
		end

		self.IsOpen = false

		if self.Library:GetActivePopup() == self then
			self.Library:SetActivePopup(nil)
		end

		self.Catcher.Visible = false

		Fade.play(self.Frame, 0, 1, 0.1)

		task.delay(0.1, function()
			if not self.IsOpen and not self.Destroyed then
				self.Frame.Visible = false
			end
		end)

		if self.OnClose then
			local ok, err = pcall(self.OnClose)
			if not ok then
				warn("[CherryUI] Popup close handler error: " .. tostring(err))
			end
		end
	end

	function Popup:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true

		if self.Library:GetActivePopup() == self then
			self.Library:SetActivePopup(nil)
		end

		self.Catcher:Destroy()
		self.Frame:Destroy()
	end

	return Popup
end

__modules["Utils/Scheduler"] = function()
	--[[
		Utils/Scheduler.lua
		One Heartbeat connection drives every repeating Cherry UI task.

		Instead of each live component connecting its own RenderStepped/Heartbeat
		event (and running at 60+ Hz), they register with the scheduler, which ticks
		at a capped frequency (30 Hz by default) and then runs due tasks. The ESP
		preview, player list refresh and notification timers all use it.
	]]

	local RunService = game:GetService("RunService")

	local Scheduler = {}
	Scheduler.__index = Scheduler

	function Scheduler.new(frequency)
		local self = setmetatable({}, Scheduler)

		self.Frequency = frequency or 30
		self.Interval = 1 / self.Frequency
		self.Tasks = {}
		self.Accumulator = 0
		self.Destroyed = false

		self.Connection = RunService.Heartbeat:Connect(function(deltaTime)
			self:_step(deltaTime)
		end)

		return self
	end

	function Scheduler:_step(deltaTime)
		if self.Destroyed then
			return
		end

		self.Accumulator += deltaTime

		if self.Accumulator < self.Interval then
			return
		end

		local elapsed = self.Accumulator
		self.Accumulator = self.Accumulator % self.Interval

		local tasks = self.Tasks
		local index = 1

		while index <= #tasks do
			local taskEntry = tasks[index]

			if taskEntry.Cancelled then
				table.remove(tasks, index)
			else
				taskEntry.Elapsed += elapsed

				while taskEntry.Elapsed >= taskEntry.Interval do
					taskEntry.Elapsed -= taskEntry.Interval

					if taskEntry.Callback then
						local ok, err = pcall(taskEntry.Callback)
						if not ok then
							warn("[CherryUI] Scheduler task error: " .. tostring(err))
						end
					end

					if taskEntry.Cancelled then
						break
					end
				end

				index += 1
			end
		end
	end

	function Scheduler:Every(interval, callback, runImmediately)
		local taskEntry = {
			Interval = math.max(tonumber(interval) or self.Interval, 0.01),
			Elapsed = 0,
			Callback = callback,
			Cancelled = false,
		}

		table.insert(self.Tasks, taskEntry)

		if runImmediately and callback then
			task.spawn(callback)
		end

		return taskEntry
	end

	function Scheduler:Remove(taskEntry)
		if taskEntry then
			taskEntry.Cancelled = true
		end
	end

	function Scheduler:Clear()
		for index = 1, #self.Tasks do
			self.Tasks[index].Cancelled = true
		end
		table.clear(self.Tasks)
	end

	function Scheduler:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true

		if self.Connection then
			self.Connection:Disconnect()
			self.Connection = nil
		end

		self:Clear()
	end

	return Scheduler
end

__modules["Utils/Signal"] = function()
	--[[
		Utils/Signal.lua
		A tiny signal implementation used for component callbacks and library events.

		Design notes:
		* handlers are stored in a dictionary so disconnecting is O(1)
		* firing iterates over a snapshot, so connecting/disconnecting inside a
		  handler is safe
		* handler errors are caught and reported instead of breaking the whole UI
	]]

	local Signal = {}
	Signal.__index = Signal

	function Signal.new()
		return setmetatable({ _handlers = {} }, Signal)
	end

	function Signal:Connect(callback)
		assert(type(callback) == "function", "Signal:Connect expects a function")

		local signal = self
		local connection = {
			Connected = true,
			Callback = callback,
		}

		function connection:Disconnect()
			if not self.Connected then
				return
			end
			self.Connected = false
			self.Callback = nil
			signal._handlers[self] = nil
		end

		function connection:IsConnected()
			return self.Connected
		end

		self._handlers[connection] = true
		return connection
	end

	function Signal:Fire(...)
		local snapshot = {}
		for connection in self._handlers do
			table.insert(snapshot, connection)
		end

		for index = 1, #snapshot do
			local connection = snapshot[index]
			if connection.Connected and connection.Callback then
				local ok, err = pcall(connection.Callback, ...)
				if not ok then
					warn("[CherryUI] Signal handler error: " .. tostring(err))
				end
			end
		end
	end

	function Signal:DisconnectAll()
		for connection in self._handlers do
			connection.Connected = false
			connection.Callback = nil
		end
		table.clear(self._handlers)
	end

	function Signal:Destroy()
		self:DisconnectAll()
	end

	return Signal
end

__modules["Utils/Tween"] = function()
	--[[
		Utils/Tween.lua
		Central place for Cherry UI's motion language.

		Everything animated in the library goes through TweenService with a small,
		consistent set of easing curves (Quad for micro-interactions, Quart for
		larger movements, Back only for the window intro).
	]]

	local TweenService = game:GetService("TweenService")

	local Tween = {}

	Tween.Info = {
		Instant = TweenInfo.new(0.06, Enum.EasingStyle.Linear),
		Snap = TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		Fast = TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		Smooth = TweenInfo.new(0.24, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
		Glide = TweenInfo.new(0.36, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
		Spring = TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
	}

	function Tween.linear(duration)
		return TweenInfo.new(duration or 1, Enum.EasingStyle.Linear)
	end

	--[[
		TweenService:Create raises "no property named 'X' for object 'Y'" for a
		property the instance does not have (GroupTransparency on a Frame is the
		classic case). A cosmetic animation must never take the whole interface down,
		so creation is guarded and failures are reported once per offending property.
	]]
	local reported = {}

	local function createTween(instance, properties, info)
		local ok, result = pcall(TweenService.Create, TweenService, instance, info or Tween.Info.Smooth, properties)

		if ok then
			return result
		end

		local message = tostring(result)
		if not reported[message] then
			reported[message] = true
			warn("[CherryUI] tween skipped: " .. message)
		end

		return nil
	end

	function Tween.create(instance, properties, info)
		return createTween(instance, properties, info)
	end

	function Tween.play(instance, properties, info)
		local tween = createTween(instance, properties, info)

		if tween then
			tween:Play()
		end

		return tween
	end

	--[[
		Animates a number and calls `callback` with every intermediate value.
		Internally it tweens a NumberValue so it can reuse TweenService's easing.
	]]
	function Tween.number(from, to, duration, callback, style, direction)
		assert(type(callback) == "function", "Tween.number expects a callback")

		local holder = Instance.new("NumberValue")
		holder.Value = from

		local tween = createTween(
			holder,
			{ Value = to },
			TweenInfo.new(
				duration or 0.3,
				style or Enum.EasingStyle.Quad,
				direction or Enum.EasingDirection.Out
			)
		)

		local connection = holder:GetPropertyChangedSignal("Value"):Connect(function()
			callback(holder.Value)
		end)

		if not tween then
			holder.Value = to
			connection:Disconnect()
			holder:Destroy()
			callback(to)
			return nil
		end

		tween.Completed:Once(function()
			connection:Disconnect()
			holder:Destroy()
		end)

		tween:Play()
		callback(from)
		return tween
	end

	return Tween
end

__modules["Utils/Util"] = function()
	--[[
		Utils/Util.lua
		Small, dependency-free helpers shared by the components.
	]]

	local Util = {}

	local SPECIAL_KEYS = {
		[Enum.KeyCode.LeftShift] = "LShift",
		[Enum.KeyCode.RightShift] = "RShift",
		[Enum.KeyCode.LeftControl] = "LCtrl",
		[Enum.KeyCode.RightControl] = "RCtrl",
		[Enum.KeyCode.LeftAlt] = "LAlt",
		[Enum.KeyCode.RightAlt] = "RAlt",
		[Enum.KeyCode.Return] = "Enter",
		[Enum.KeyCode.Backspace] = "Backspace",
		[Enum.KeyCode.Escape] = "Esc",
		[Enum.KeyCode.Space] = "Space",
		[Enum.UserInputType.MouseButton1] = "Mouse1",
		[Enum.UserInputType.MouseButton2] = "Mouse2",
		[Enum.UserInputType.MouseButton3] = "Mouse3",
	}

	function Util.clamp(value, minimum, maximum)
		if value < minimum then
			return minimum
		elseif value > maximum then
			return maximum
		end
		return value
	end

	function Util.round(value, decimals)
		decimals = decimals or 0
		local multiplier = 10 ^ decimals
		return math.floor(value * multiplier + 0.5) / multiplier
	end

	-- Formats a number without trailing zeros ("12.50" -> "12.5").
	function Util.trimNumber(value, decimals)
		decimals = decimals or 0
		local rounded = Util.round(value, decimals)

		if decimals <= 0 then
			return string.format("%.0f", rounded)
		end

		local text = string.format("%." .. tostring(decimals) .. "f", rounded)
		text = string.gsub(text, "0+$", "")
		text = string.gsub(text, "%.$", "")

		if text == "" or text == "-0" then
			text = "0"
		end

		return text
	end

	-- Converts a key code / user input type into a short display label.
	function Util.keyName(value)
		if typeof(value) ~= "EnumItem" then
			return "None"
		end

		local special = SPECIAL_KEYS[value]
		if special then
			return special
		end

		local name = value.Name
		name = string.gsub(name, "(%l)(%u)", "%1 %2")
		return name
	end

	function Util.matchesInput(input, binding)
		if typeof(binding) ~= "EnumItem" then
			return false
		end

		if binding.EnumType == Enum.KeyCode then
			return input.KeyCode == binding
		elseif binding.EnumType == Enum.UserInputType then
			return input.UserInputType == binding
		end

		return false
	end

	function Util.hex(color)
		return string.format(
			"#%02X%02X%02X",
			math.floor(color.R * 255 + 0.5),
			math.floor(color.G * 255 + 0.5),
			math.floor(color.B * 255 + 0.5)
		)
	end

	function Util.fromHex(text)
		if type(text) ~= "string" then
			return nil
		end

		local full = string.match(text, "#?(%x%x%x%x%x%x)")
		if full then
			return Color3.fromHex(full)
		end

		local short = string.match(text, "#?(%x%x%x)")
		if short then
			local r = string.sub(short, 1, 1)
			local g = string.sub(short, 2, 2)
			local b = string.sub(short, 3, 3)
			return Color3.fromHex(r .. r .. g .. g .. b .. b)
		end

		return nil
	end

	-- Copies text to the clipboard when an executor provides `setclipboard`.
	function Util.copy(text)
		local copyFunction = nil

		local ok = pcall(function()
			copyFunction = setclipboard
		end)

		if ok and type(copyFunction) == "function" then
			local copied = pcall(copyFunction, tostring(text))
			return copied
		end

		return false
	end

	return Util
end

__modules["init"] = function()
	--[[
		Cherry UI — a high-performance, cherry-picked UI library for Roblox FPS games.

		Usage (from a LocalScript):

			local CherryUI = require(ReplicatedStorage.CherryUI)
			local window = CherryUI:CreateWindow({ Title = "Cherry" })
		local tab = window:AddTab("Combat", "target")
		tab:AddSection("Aimbot"):AddToggle({ Name = "Enable Aimbot" })

		The module deliberately owns a single ScreenGui (created on first use), one
		Heartbeat scheduler and one theme manager, no matter how many windows the
		user creates.
	]]

	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local UserInputService = game:GetService("UserInputService")

	local Create = __require("Utils/Create")
	local Signal = __require("Utils/Signal")
	local Scheduler = __require("Utils/Scheduler")
	local Util = __require("Utils/Util")
	local Tween = __require("Utils/Tween")
	local Fade = __require("Utils/Fade")
	local Icons = __require("Utils/Icons")
	local Pool = __require("Utils/Pool")
	local Popup = __require("Utils/Popup")
	local ConfigManager = __require("Utils/Config")
	local ThemeManager = __require("Core/ThemeManager")
	local Cursor = __require("Core/Cursor")
	local Notification = __require("Components/Notification")
	local Window = __require("Components/Window")

	local Themes = {
		Crimson = __require("Themes/Crimson"),
		Pink = __require("Themes/Pink"),
		Purple = __require("Themes/Purple"),
		Green = __require("Themes/Green"),
		Blue = __require("Themes/Blue"),
	}

	local THEME_ORDER = { "Crimson", "Pink", "Purple", "Green", "Blue" }
	local DEFAULT_THEME = "Crimson"

	local Library = {}
	Library.__index = Library

	function Library.new()
		local self = setmetatable({}, Library)

		-- Bumped so a stale bundle is obvious: `print(CherryUI.Version)` should match
		-- the release you loaded.
		self.Version = "1.1.0"

		--[[
			Exposed so scripts built on Cherry UI can reuse the same motion, pooling
			and icon language instead of writing their own:
				CherryUI.Icons.new("target", frame, 18, CherryUI.Palette.Primary)
				CherryUI.Pool.new(create, reset)
				CherryUI.Tween.play(frame, { BackgroundTransparency = 0 }, CherryUI.Tween.Info.Fast)
		]]
		self.Create = Create
		self.Signal = Signal
		self.Tween = Tween
		self.Fade = Fade
		self.Icons = Icons
		self.Pool = Pool
		self.Popup = Popup
		self.Util = Util

		self.Themes = Themes
		self.ThemeOrder = THEME_ORDER
		self.Windows = {}
		self.ToggleKey = Enum.KeyCode.RightShift
		self.ToggleKeyChanged = Signal.new()
		self.Capturing = false
		self.ActivePopup = nil
		self.ScreenGui = nil
		self.Overlay = nil
		self.Notifier = nil
		self.Cursor = nil
		self.PrimaryWindow = nil
		self.Destroyed = false

		-- The cherry pointer ships on by default: loading the library replaces the
		-- Roblox cursor immediately, even before the first window is created.
		self._cursorMode = "always"

		self.ThemeManager = ThemeManager.new(Themes, DEFAULT_THEME)
		self.Palette = self.ThemeManager.Palette
		self.Scheduler = Scheduler.new(30)
		self.Config = ConfigManager.new(self)

		self:_bindInput()

		-- Build the ScreenGui (and with it the cherry cursor) as soon as the module
		-- runs. Deferred so `require` never yields, and client-only so requiring the
		-- library from server code or Studio's edit mode stays silent.
		task.defer(function()
			if not self.Destroyed and RunService:IsClient() then
				self:_ensureScreen()
			end
		end)

		return self
	end

	-- Applies a palette token now and keeps the instance in sync on theme changes.
	function Library:Styled(instance, token, property)
		return self.ThemeManager:Bind(instance, property, token)
	end

	--[[
		Marks that a Keybind control is waiting for a key. The timestamp lets the
		input handler release a capture that was abandoned (window closed mid-capture,
		focus stolen) instead of leaving the menu toggle dead forever.
	]]
	function Library:SetCapturing(capturing)
		self.Capturing = capturing and true or false
		self._captureStarted = os.clock()
	end

	-- How long an unfinished keybind capture may block the menu toggle.
	local CAPTURE_TIMEOUT = 5

	function Library:_bindInput()
		self._inputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)
			if self.Capturing then
				-- Keybind capture owns the keyboard, but only for a moment: a capture
				-- that never received a key must not swallow the toggle key.
				if os.clock() - (self._captureStarted or 0) < CAPTURE_TIMEOUT then
					return
				end

				self:SetCapturing(false)
			end

			--[[
				The toggle key is checked *before* the gameProcessed bail-out.
				RightShift is a modifier: on some clients it arrives with gameProcessed
				set, and any focused TextBox (the settings search box is a TextBox) used
				to disable the toggle entirely. A menu key must always work, so nothing
				short of an active keybind capture gets to block it.
			]]
			if Util.matchesInput(input, self.ToggleKey) then
				self:ToggleUI()
				return
			end

			if gameProcessed then
				return
			end

			if input.KeyCode == Enum.KeyCode.Escape and self.ActivePopup then
				self.ActivePopup:Close()
			end
		end)
	end

	--[[
		Picks where the ScreenGui should live.

		Executors expose `gethui()`, which returns a container that draws above the
		game's own interfaces; plain Roblox clients only have PlayerGui. Both are
		client-side, so a LocalScript and an injected script take the same path.
	]]
	local function resolveGuiParent(player)
		local getHiddenUi = gethui

		if type(getHiddenUi) == "function" then
			local ok, parent = pcall(getHiddenUi)
			if ok and parent then
				return parent
			end
		end

		return player:WaitForChild("PlayerGui")
	end

	function Library:_ensureScreen()
		if self.ScreenGui and self.ScreenGui.Parent then
			return self.ScreenGui
		end

		if not RunService:IsClient() then
			warn("[CherryUI] Cherry UI builds its interface on the client; require it from a LocalScript (or run it in Studio with Play, not Run).")
			return nil
		end

		-- Never block forever: in Studio's "Run" mode (F8) there is no LocalPlayer and
		-- an unbounded wait would silently swallow the whole script.
		local player = Players.LocalPlayer
		local attempts = 0
		while not player and attempts < 50 do
			task.wait(0.1)
			player = Players.LocalPlayer
			attempts += 1
		end

		if not player then
			warn("[CherryUI] No LocalPlayer: open the place with Play (F5), not Run (F8), or move the script into StarterPlayerScripts.")
			return nil
		end

		local guiProps = {
			Name = "CherryUI",
			ResetOnSpawn = false,
			IgnoreGuiInset = false,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
			DisplayOrder = 999,
		}

		-- Executors sometimes expose a `gethui()` that refuses the parent; falling
		-- back to PlayerGui keeps the library usable instead of erroring there.
		local function buildGui(target)
			local props = table.clone(guiProps)
			props.Parent = target
			return Create.new("ScreenGui", props)
		end

		local ok, screenGui = pcall(buildGui, resolveGuiParent(player))
		if not ok or not screenGui or not screenGui.Parent then
			screenGui = buildGui(player:WaitForChild("PlayerGui"))
		end

		-- Respect device safe areas / the topbar on modern clients.
		pcall(function()
			screenGui.ScreenInsets = Enum.ScreenInsets.CoreUISafeInsets
		end)

		self.ScreenGui = screenGui

		self.Overlay = Create.new("Frame", {
			Name = "Overlay",
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			ZIndex = 500,
			Parent = screenGui,
		})

		self.Cursor = Cursor.new(self)
		self.Notifier = Notification.new(self)

		if self._cursorMode then
			self.Cursor:SetMode(self._cursorMode)
		end

		return screenGui
	end

	function Library:CreateWindow(config)
		if self.Destroyed then
			return nil
		end

		config = config or {}

		if typeof(config.ToggleKey) == "EnumItem" then
			self:SetToggleKey(config.ToggleKey)
		end

		--[[
			Two live windows stack, and the newer one (usually the accidental one)
			sits on top — which looks exactly like "the menu is empty". Say so instead
			of letting the first window hide behind it.
		]]
		local existing = self.PrimaryWindow
		if existing and not existing.Destroyed then
			warn(string.format(
				"[CherryUI] A second window was created while '%s' is still open. Reuse that one, or call window:Destroy() first.",
				existing.Title
			))
		end

		self:_ensureScreen()
		if not self.ScreenGui then
			return nil
		end

		if config.Cursor ~= nil then
			self:SetCursorMode(config.Cursor)
		else
			self:SetCursorMode(self._cursorMode or "always")
		end

		local window = Window.new(self, config)
		self.Windows[window] = true

		if not self.PrimaryWindow then
			self.PrimaryWindow = window

			-- The window opens inside its constructor, before it is the primary one,
			-- so the "menu" cursor needs one more nudge to appear.
			if self.Cursor then
				self.Cursor:Refresh()
			end
		end

		return window
	end

	function Library:GetPrimaryWindow()
		return self.PrimaryWindow
	end

	-- Shows a notice card in the primary window (handy for reporting an error to a
	-- user who never sees the console). See `Window:ShowNotice`.
	function Library:ShowNotice(config)
		local window = self.PrimaryWindow

		if not window or window.Destroyed then
			return nil
		end

		return window:ShowNotice(config)
	end

	function Library:Notify(config)
		if self.Destroyed then
			return nil
		end

		self:_ensureScreen()
		if not self.Notifier then
			return nil
		end

		return self.Notifier:Show(config)
	end

	function Library:GetThemeNames()
		local names = {}
		for _, name in ipairs(self.ThemeOrder) do
			if self.Themes[name] then
				table.insert(names, name)
			end
		end
		return names
	end

	function Library:SetTheme(name, animate)
		if self.Destroyed then
			return false
		end

		if self.ThemeManager:SetTheme(name, animate ~= false) then
			self.Palette = self.ThemeManager.Palette
			self.Config:MarkDirty()
			return true
		end

		return false
	end

	function Library:SetToggleKey(key)
		if typeof(key) ~= "EnumItem" or self.ToggleKey == key then
			return
		end

		self.ToggleKey = key
		self.Config:MarkDirty()
		self.ToggleKeyChanged:Fire(key)
	end

	function Library:OnToggleKeyChanged(callback)
		return self.ToggleKeyChanged:Connect(callback)
	end

	function Library:ToggleUI()
		local window = self.PrimaryWindow

		-- Recover when the primary window was destroyed: toggle any live window so
		-- the keybind keeps working instead of going quiet.
		if not window or window.Destroyed then
			window = nil
			for candidate in self.Windows do
				if not candidate.Destroyed then
					window = candidate
					self.PrimaryWindow = candidate
					break
				end
			end
		end

		if window and not window.Destroyed then
			window:Toggle()
		end
	end

	--[[
		Cursor control: "always" (default) replaces the Roblox pointer as soon as the
		library loads, "menu" draws the cherry only while a Cherry UI window is open,
		and "off" leaves the Roblox cursor untouched.
	]]
	function Library:SetCursorMode(mode)
		if self.Cursor then
			return self.Cursor:SetMode(mode)
		end

		if not (mode == "always" or mode == "menu" or mode == "off") then
			warn("[CherryUI] Unknown cursor mode: " .. tostring(mode))
			return false
		end

		self._cursorMode = mode
		return true
	end

	function Library:GetCursorMode()
		if self.Cursor then
			return self.Cursor:GetMode()
		end

		return self._cursorMode or "always"
	end

	-- Puts Roblox's own pointer back without tearing the interface down. Handy when
	-- another script (or a hard script stop) needs the system cursor again.
	function Library:ResetCursor()
		return self:SetCursorMode("off")
	end

	function Library:SetActivePopup(popup)
		local previous = self.ActivePopup

		if previous and previous ~= popup then
			self.ActivePopup = nil
			previous:Close()
		end

		self.ActivePopup = popup
	end

	function Library:GetActivePopup()
		return self.ActivePopup
	end

	function Library:RefreshVisibility()
		for _, component in ipairs(self.Config.Components) do
			if not component.Destroyed then
				component:UpdateVisibility()
			end
		end

		for window in self.Windows do
			if not window.Destroyed then
				window:Filter(window.SearchBox.Text)
			end
		end
	end

	function Library:_buildAllTabs()
		for window in self.Windows do
			if not window.Destroyed then
				for _, tab in ipairs(window.Tabs) do
					tab:EnsureBuilt()
				end
			end
		end
	end

	function Library:SaveConfig()
		-- Register lazy tabs first so their values are included in the snapshot.
		self:_buildAllTabs()
		return self.Config:Save()
	end

	function Library:LoadConfig()
		self:_buildAllTabs()
		return self.Config:Load()
	end

	function Library:ResetConfig()
		self:_buildAllTabs()
		return self.Config:Reset()
	end

	function Library:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true

		local windows = {}
		for window in self.Windows do
			table.insert(windows, window)
		end
		for index = 1, #windows do
			windows[index]:Destroy()
		end
		table.clear(self.Windows)

		if self.Notifier then
			self.Notifier:Destroy()
			self.Notifier = nil
		end

		if self.Cursor then
			self.Cursor:Destroy()
			self.Cursor = nil
		end

		if self._inputConnection then
			self._inputConnection:Disconnect()
			self._inputConnection = nil
		end

		self.Scheduler:Destroy()
		self.ThemeManager:Destroy()
		self.Config:Destroy()
		self.ToggleKeyChanged:Destroy()

		if self.ScreenGui then
			self.ScreenGui:Destroy()
			self.ScreenGui = nil
		end

		self.Overlay = nil
		self.PrimaryWindow = nil
	end

	return Library.new()
end

local CherryUI = __require("init")

-- Expose the library to executor environments so other scripts can do
-- `getgenv().CherryUI:CreateWindow(...)` without loading it twice.
if type(getgenv) == "function" then
	pcall(function()
		getgenv().CherryUI = CherryUI
	end)
end

return CherryUI
